INSERT INTO curated_memories VALUES('1e9be6a1-f905-426e-b15a-32f010326603','2025-09-02T10:50:29.371034-05:00','2025-09-02T10:50:29.371034-05:00',NULL,NULL,'technical_solution','Claude Desktop MCP Remote серверы проблема и решение: Remote MCP серверы (labrute-docs, grep, tavily-remote, zoo_market-docs, claude-code-templates-docs) падают с ошибкой MODULE_NOT_FOUND es-object-atoms из-за поврежденного NPX кэша. Решение: 1) rm -rf ~/.npm/_npx/* 2) npm cache clean --force 3) npm uninstall -g mcp-remote && npm install -g mcp-remote@latest 4) обновить путь в mcp-remote-v22 скрипте на актуальный путь из which mcp-remote 5) полный перезапуск Claude Desktop. Ключевой инсайт: проблема не в дублировании процессов, а в поврежденном NPX кэше для mcp-remote клиента.',9,'["Claude Desktop", "MCP", "remote servers", "NPX cache", "troubleshooting", "Linux", "Ubuntu"]',NULL,'2025-09-02 15:50:29');
INSERT INTO curated_memories VALUES('463fd9d0-a72a-462a-aad0-d9fc05abad68','2025-09-02T10:50:44.034889-05:00','2025-09-02T10:50:44.034889-05:00',NULL,NULL,'bug_report','Claude Desktop дублирование MCP процессов баг Linux: Claude Desktop на Ubuntu/Linux запускает каждый MCP сервер дважды (двойная инициализация в логах main.log). Это известный баг на GitHub modelcontextprotocol/servers #812. Дубликаты НЕ критичны - серверы работают параллельно. Wrapper скрипты с проверкой pgrep могут предотвратить дубли, но Claude Desktop может игнорировать обновленную конфигурацию из-за кэширования. Практичное решение: автоматическая очистка дубликатов через cron каждые 10 минут с kill старых процессов.',8,'["Claude Desktop", "MCP", "Linux", "Ubuntu", "duplication bug", "process management"]',NULL,'2025-09-02 15:50:44');
INSERT INTO curated_memories VALUES('9171a12d-91c5-4c00-92db-b945a176c96a','2025-09-02T10:55:58.436638-05:00','2025-09-02T10:55:58.436638-05:00',NULL,NULL,'configuration',replace('Persistent AI Memory - настройки и конфигурация:\n- Установлен в /home/dev-avk/projects/persistent-ai-memory/\n- Python venv активируется: source venv/bin/activate\n- MCP сервер: python mcp_server.py\n- SQLite базы в memory_data/ (160KB общий размер)\n- Claude Desktop конфигурация: /home/dev-avk/.config/Claude/claude_desktop_config.json\n- MCP команда для Claude: bash -c "cd /home/dev-avk/projects/persistent-ai-memory && source venv/bin/activate && python mcp_server.py"\n- Исправлена проблема print() в mcp_server.py (закомментирован stdout print)\n- Система полностью работает с Claude Desktop','\n',char(10)),9,'["persistent-ai-memory", "mcp", "sqlite", "claude-desktop", "configuration", "ubuntu"]',NULL,'2025-09-02 15:55:58');
INSERT INTO curated_memories VALUES('b9565b57-8842-4d79-9e95-05fce09e187a','2025-09-02T10:56:06.070779-05:00','2025-09-02T10:56:06.070779-05:00',NULL,NULL,'configuration',replace('OpenMemory Chrome Extension интеграция:\n- Статус: работает стабильно с ChatGPT\n- mem0 API ключ: m0-*******Wgh\n- Настройки: Memory Suggestions включено, Track searches включено\n- Сохраняет предпочтения React/TypeScript в браузерных AI\n- Размер extension: ~5MB\n- Бесплатный тариф mem0.ai используется','\n',char(10)),8,'["openmemory", "chrome-extension", "mem0", "chatgpt", "browser-ai"]',NULL,'2025-09-02 15:56:06');
INSERT INTO curated_memories VALUES('2c56cd46-e670-4641-9074-ca87bb638038','2025-09-02T10:56:18.092387-05:00','2025-09-02T10:56:18.092387-05:00',NULL,NULL,'troubleshooting',replace('CLI Gemini интеграция - результаты и проблемы:\n- CLI Gemini установлен через npm @google/gemini-cli@latest\n- Обнаружены критические ошибки: ImportProcessor ENOENT, поврежденный кэш\n- Создан wrapper скрипт: /home/dev-avk/projects/persistent-ai-memory/gemini-wrapper.sh  \n- Wrapper функциональность: принимает вопросы, пытается вызвать CLI Gemini, сохраняет диалоги в SQLite\n- Проблема: CLI Gemini нестабилен на Ubuntu 24.04, дает ошибки\n- Решение: обход CLI Gemini, фокус на стабильных интеграциях (Claude Desktop + ChatGPT Chrome)\n- Статус: CLI Gemini интеграция отложена до исправления багов Google','\n',char(10)),7,'["cli-gemini", "integration-issues", "wrapper", "ubuntu-24.04", "troubleshooting"]',NULL,'2025-09-02 15:56:18');
INSERT INTO curated_memories VALUES('8ed463b8-61d1-4f14-85eb-503dd67b8f33','2025-09-02T10:56:28.927067-05:00','2025-09-02T10:56:28.927067-05:00',NULL,NULL,'configuration',replace('Полезные алиасы для Persistent AI Memory в .bashrc:\n- ai-memories: показать все записи в ai_memories.db  \n- ai-count: подсчет количества записей\n- ai-top: записи по важности (DESC)\nПуть к базам: /home/dev-avk/projects/persistent-ai-memory/memory_data/\nОсновные базы: ai_memories.db (12KB), mcp_tool_calls.db (40KB), conversations.db (44KB)\nТаблица curated_memories: memory_id, content, importance_level, tags, memory_type','\n',char(10)),8,'["sqlite", "aliases", "bashrc", "database", "ai-memories"]',NULL,'2025-09-02 15:56:28');
