persistent-ai-memory/memory_data/ai_memories.db"\n\ndef save_memory(content, tags=None, memory_type="manual", importance=5):\n    """Сохранить запись в базу"""\n    conn = sqlite3.connect(DB_PATH)\n    cursor = conn.cursor()\n    \n    memory_id = str(uuid.uuid4())\n    timestamp = datetime.now().isoformat()\n    \n    # Use provided tags or default\n    tags_to_save = json.dumps(tags if tags is not None else ["cli", "manual"])\n    \n    cursor.execute("""\n        INSERT INTO curated_memories \n        (memory_id, timestamp_created, timestamp_updated, memory_type, content, importance_level, tags)\n        VALUES (?, ?, ?, ?, ?, ?, ?)\n    """, (memory_id, timestamp, timestamp, memory_type, content, importance, tags_to_save))\n    \n    conn.commit()\n    conn.close()\n    print(f"Сохранено: {memory_id}")\n\ndef search_memory(query):\n    """Поиск в базе"""\n    conn = sqlite3.connect(DB_PATH)\n    cursor = conn.cursor()\n    \n    cursor.execute("""\n        SELECT memory_id, memory_type, importance_level, content, tags \n        FROM curated_memories \n        WHERE content LIKE ? OR tags LIKE ?\n        ORDER BY importance_level DESC\n    """, (f"%{query}%", f"%{query}%"))\n    \n    results = cursor.fetchall()\n    conn.close()\n    \n    if results:\n        print(f"Найдено {len(results)} записей по запросу ''{query}'':")\n        for row in results:\n            print(f"ID: {row[0][:8]}... | Тип: {row[1]} | Важность: {row[2]}")\n            print(f"Содержание: {row[3][:200]}...")\n            try:\n                tags_list = json.loads(row[4])\n                print(f"Теги: {'', ''.join(tags_list)}")\n            except:\n                print(f"Теги: {row[4]}")\n            print("-" * 50)\n    else:\n        print("Записи не найдены")\n\ndef list_memory():\n    """Показать все записи"""\n    conn = sqlite3.connect(DB_PATH)\n    cursor = conn.cursor()\n    \n    cursor.execute("""\n        SELECT memory_id, memory_type, importance_level, content \n        FROM curated_memories \n        ORDER BY timestamp_created DESC \n        LIMIT 10\n    """)\n    \n    results = cursor.fetchall()\n    conn.close()\n    \n    if results:\n        print(f"Найдено {len(results)} записей:")\n        for i, row in enumerate(results, 1):\n            print(f"{i}. [{row[1]}] (важность: {row[2]}) {row[3][:60]}...")\n    else:\n        print("База данных пуста")\n\ndef save_from_file(filepath, tags=None):\n    """Читает контент из файла и сохраняет его в базу."""\n    try:\n        with open(filepath, ''r'', encoding=''utf-8'') as f:\n            content = f.read()\n        # Pass tags to save_memory\n        save_memory(content, tags=tags)\n    except FileNotFoundError:\n        print(f"Ошибка: Файл не найден по пути {filepath}")\n    except Exception as e:\n        print(f"Ошибка при чтении файла: {e}")\n\ndef main():\n    parser = argparse.ArgumentParser(description="Простой CLI для Persistent AI Memory.")\n    subparsers = parser.add_subparsers(dest=''action'', required=True, help=''Действие'')\n\n    # Команда save\n    parser_save = subparsers.add_parser(''save'', help=''Сохранить новую запись.'')\n    parser_save.add_argument(''content'', type=str, help=''Содержимое для сохранения.'')\n    parser_save.add_argument(''--tags'', type=str, help=''Теги через запятую (например, "tag1,tag2").'')\n\n    # Команда save_from_file\n    parser_save_file = subparsers.add_parser(''save_from_file'', help=''Сохранить новую запись из файла.'')\n    parser_save_file.add_argument(''filepath'', type=str, help=''Путь к файлу.'')\n    parser_save_file.add_argument(''--tags'', type=str, help=''Теги через запятую.'')\n\n    # Команда search\n    parser_search = subparsers.add_parser(''search'', help=''Искать записи.'')\n    parser_search.add_argument(''query'', type=str, help=''Поисковый запрос.'')\n\n    # Команда list\n    subparsers.add_parser(''list'', help=''Показать последние 10 записей.'')\n\n    args = parser.parse_args()\n\n    try:\n        tags_list = args.tags.split('','') if ''tags'' in args and args.tags else None\n        \n        if args.action == "save":\n            save_memory(args.content, tags=tags_list)\n        elif args.action == "save_from_file":\n            save_from_file(args.filepath, tags=tags_list)\n        elif args.action == "search":\n            search_memory(args.query)\n        elif args.action == "list":\n            list_memory()\n    except Exception as e:\n        print(f"Ошибка выполнения команды: {e}")\n\nif __name__ == "__main__":\n    main()\n```','\n',char(10)),5,'["script-fix", "simple-memory-py", "argparse", "custom-tags-fix", "python-script", "date-2025-09-08", "persistent-ai-memory", "\u043f\u043b\u043e\u0441\u043a\u0430\u044f \u043f\u0430\u043c\u044f\u0442\u044c", "\u043f\u0440\u043e\u0431\u043b\u0435\u043c\u044b \u0441 \u0437\u0430\u043f\u0438\u0441\u044c\u044e \u0432 \u043f\u0430\u043c\u044f\u0442\u044c"]',NULL,'2025-09-08 21:10:10');
INSERT INTO curated_memories VALUES('2854a56f-d948-4f42-8bb2-05951485a9c5','2025-09-09T00:11:16.334278','2025-09-09T00:11:16.334278',NULL,NULL,'manual',replace('Thoughts\n\n\nЯ кратко проверю текущую Prisma-схему, чтобы понять, есть ли уже модели для блогов и тегов. Это поможет предложить точный план внедрения.\n\nThoughts\n\n\nThoughts\n\n\nThoughts\n\n\n\n\n\nЯ коротко посмотрю существующие клиентские хук-и и мутации для блогов/тегов, чтобы понять, что уже готово на фронтенде и где не хватает логики.\n\nThoughts\n\n\n\nThoughts\n\n\nThoughts\n\n\nThoughts\n\n\nCode agent\nЯ быстро проверю, есть ли готовые админ-страницы и компоненты для управления тегами блогов, чтобы оценить объём недостающей логики.\n\nThoughts\n\n\nАнализ задачи: CRUD блогов и управление тегами в админке\nКраткий вывод\nБэкенд уже полностью готов: есть контроллеры/сервисы/репозитории для блогов и тегов, DTO/схемы, загрузка/удаление изображений.\nФронтенд имеет почти всю инфраструктуру: React Query хуки для CRUD блогов/тегов, страницы админки для блогов и тегов, модальные окна. Но логика не подключена: таблицы используют пустые данные, модалки не вызывают мутации, нет подстановки тегов в фильтры/селекты.\nЧто нужно сделать на фронтенде\nПодключить загрузку данных:\n\nВ AdminBlogsPageComponent:\nЗаменить data: [] на данные из useBlogs.\nДобавить фильтры по тегам: подгружать теги через useBlogTags и передавать их в Filter/BlogModal.\nВ AdminBlogTagsPageComponent:\nЗаменить data: [] на данные из useBlogTags.\nПровести маппинг данных к UI-моделям:\n\nBlogResponse -> IBlog:\nid, createdAt из ответа.\ntitle/description брать из локализованного ответа (в контракте уже есть title/description).\ntagId из blog.tag?.id (или хранить весь tag в строке отображения).\nПодключить мутации:\n\nБлоги:\nonAdd: вызывать useCreateBlog с формированием CreateBlogDto:\ntranslations: массив переводов с текущим языком (useLocale) и title/description из формы.\ntagId из селекта.\nonEdit: вызывать useUpdateBlog(blogId, dto).\nonDelete: вызывать useDeleteBlog(blogId).\nПосле onSuccess: invalidate нужных query (уже реализовано в хуках).\nПодключить загрузку/удаление изображения через useUploadBlogImage/useDeleteBlogImage, если понадобится.\nТеги:\nonAdd/onEdit/onDelete в AdminBlogTagsPageComponent через хук-и useCreateBlogTag/useUpdateBlogTag/useDeleteBlogTag.\nФормировать DTO: translations [{ language, name }], color.\nФильтры и сортировка:\n\nПодключить фильтр по тегам: передать blogTags в Filter в AdminBlogsPageComponent.\nДобавить запрос с параметрами q/page/take в useBlogs (уже поддержано), прокинуть параметры из таблицы/поиска.\nI18n и валидация:\n\nКонтракты требуют translations с уникальными языками и обязательной дефолтной локалью. Использовать текущую локаль как минимум один элемент массива.\nПри редактировании, если нужно мульти-языковая поддержка в UI — добавить переключатель языка (можно отложить, пока хватит одного языка).\nМаршруты/Доступ:\n\nСтраницы уже существуют: /admin/blogs и /admin/blogs/tags, ссылки есть в сайдбаре. Проверить, что AdminClient обеспечивает auth/ролевая защита (уже есть роль ADMIN на бэке).\nРиски/тонкости\nТипы в UI (IBlog) не соответствуют контрактам (BlogResponse содержит tag, media, updatedAt, а IBlog упрощён). Нужен аккуратный маппинг.\nПри создании/редактировании блогов требуется translations массив; текущая BlogModal собирает плоские поля. Нужно собрать dto на основе текущей локали.\nВозможны ошибки из-за валидации zod (дубликат языка, отсутствие дефолтного). Проследить формирование dto.\nХранение/выбор изображения пока закомментировано — это отдельный шаг.\nОценка объёма\nПодключение данных и мутаций на обеих страницах: 4–6 файлов, 150–250 строк правок.\nБез реализации загрузки изображений: 0.5–1 день.\nС поддержкой мультиязычности в UI: +0.5–1 день.\nСледующие шаги (минимальный план)\nAdminBlogsPageComponent:\n\nПодтянуть blogs через useBlogs и blogTags через useBlogTags.\nПреобразовать BlogResponse -> IBlog.\nПередать blogTags в BlogModal и Filter.\nРеализовать onAdd/onEdit/onDelete через хуки мутаций.\nAdminBlogTagsPageComponent:\n\nПодтянуть теги и подключить onAdd/onEdit/onDelete.\nСобрать DTO:\n\nCreateBlogDto: { translations: [{ language: locale, title, description }], tagId }.\nUpdateBlogDto: аналогично, опционально.\nCreate/UpdateBlogTagDto: { translations: [{ language: locale, name }], color }.\nГотов подключить это в коде, когда скажете.','\n',char(10)),5,'["task-analysis", "crud", "blog", "tags", "admin-panel", "frontend", "backend", "nft_collect", "project-plan", "date-2025-09-08", "branch-feature/blog-crud", "blog-crud", "\u0442\u0430\u0441\u043a\u0430 \u043f\u043e \u0431\u043b\u043e\u0433\u0430\u043c nft_collect"]',NULL,'2025-09-08 21:11:16');
INSERT INTO curated_memories VALUES('e49d8ec9-61eb-4a11-9129-22bff453e91d','2025-09-09T00:14:55.867235','2025-09-09T00:14:55.867235',NULL,NULL,'manual',replace('import { IBlog } from ''@/types/blog.interface'';\nimport { CreateBlogDto, CreateBlogTagDto } from ''@repo/contracts'';\n\n/**\n * Creates a valid CreateBlogDto from form data and locale,\n * ensuring the mandatory ''en'' translation is present.\n */\nexport const createBlogDTO = (data: IBlog, locale: string): CreateBlogDto => {\n  const translations = [\n    {\n      language: ''en'',\n      title: data.title,\n      description: data.description,\n    },\n  ];\n\n  // Add current locale translation if it''s not ''en'' to avoid duplicates\n  if (locale !== ''en'') {\n    translations.push({\n      language: locale,\n      title: data.title,\n      description: data.description,\n    });\n  }\n\n  return {\n    translations,\n    tagId: data.tagId,\n  };\n};\n\ninterface IBlogTagForm {\n  name: string;\n  color?: string;\n}\n\n/**\n * Creates a valid CreateBlogTagDto from form data and locale,\n * ensuring the mandatory ''en'' translation is present.\n */\nexport const createBlogTagDTO = (\n  data: IBlogTagForm,\n  locale: string,\n): CreateBlogTagDto => {\n  const translations = [{ language: ''en'', name: data.name }];\n\n  if (locale !== ''en'') {\n    translations.push({ language: locale, name: data.name });\n  }\n\n  return {\n    translations,\n    color: data.color,\n  };\n};\n','\n',char(10)),5,'["dto-helper", "localization-fix", "blog-crud-code", "utils"]',NULL,'2025-09-08 21:14:55');
INSERT INTO curated_memories VALUES('7dfc0b69-755a-447c-849f-db783570a07c','2025-09-09T00:23:41.739721','2025-09-09T00:23:41.739721',NULL,NULL,'manual',replace('# Пояснение к Этапу 0: Зачем нужен файл dto.helper.ts?\n\nЭтот файл решает критическую проблему **несоответствия языков** между нашим фронтендом и бэкендом.\n\n### В чем суть проблемы:\n\n1.  **Требование Бэкенда:** API (сервер) требует, чтобы при создании любой записи (блога или тега) в ней **обязательно** присутствовал перевод на **английском языке (`en`)**.\n\n2.  **Поведение Фронтенда:** Наш интерфейс админки работает на **русском языке (`ru`)**. Когда администратор заполняет форму, он вводит `title` и `description` на русском.\n\nЕсли бы мы просто отправляли данные из формы на сервер, API бы их отклонил с ошибкой, потому что обязательный английский перевод отсутствует. Функции "Добавить" и "Редактировать" просто не работали бы.\n\n### Какую роль выполняет этот файл:\n\nФункции в этом файле (`createBlogDTO` и `createBlogTagDTO`) — это "умные конвертеры". Они берут данные, введенные на русском, и автоматически создают правильный объект для API, в котором:\n*   **Гарантированно есть `en` перевод** (используя русский текст в качестве основы).\n*   Также есть и `ru` перевод.\n\nТаким образом, этот файл — ключевой "переводчик" между тем, что видит пользователь в интерфейсе, и тем, что требует серверная часть для корректного сохранения данных.\n','\n',char(10)),5,'["dto-helper-explanation", "localization-fix-reason", "blog-crud", "technical-decision", "backend-requirements", "frontend-adapter", "date-2025-09-08"]',NULL,'2025-09-08 21:23:41');
INSERT INTO curated_memories VALUES('89aceb0c-e343-4262-b615-fb835492c7de','2025-09-09T12:26:07.851403','2025-09-09T12:26:07.851403',NULL,NULL,'manual',replace('Инструкция по установке AppImage в Linux (на примере Clockify):\n1. Создайте директорию: mkdir -p ~/.local/bin\n2. Переместите AppImage: mv ~/Downloads/Clockify_Setup.AppImage ~/.local/bin/clockify\n3. Сделайте исполняемым: chmod +x ~/.local/bin/clockify\n4. Добавьте алиас в ~/.bashrc для удобства: alias clockify=''~/.local/bin/clockify --no-sandbox &''\n5. Обновите сессию терминала: source ~/.bashrc','\n',char(10)),5,'["linux", "install", "appimage", "clockify", "cli", "bashrc", "alias", "local-bin"]',NULL,'2025-09-09 09:26:07');
INSERT INTO curated_memories VALUES('ca0b5b61-3910-4c6f-a838-23fdcb8ecf08','2025-09-09T14:07:12.396294','2025-09-09T14:07:12.396294',NULL,NULL,'manual',replace('### Проблема\nБэкенд (NestJS API) требует для локализуемых полей (title, description) массив переводов `translations`, в котором **обязательно** должен присутствовать объект с `language: ''en''`. Фронтенд (Next.js) предоставляет только одно значение (например, на русском).\n\n### Что будет без хелпера (текущее поведение)\nПри попытке создать или обновить блог, фронтенд отправляет данные в неверном формате. Валидация на сервере проваливается, потому что не находит обязательный перевод для языка ''en''. Сервер немедленно возвращает ошибку `400 Bad Request`, и пользователь видит сообщение "Ошибка при создании блога". Данные не сохраняются.\n\n### Механизм валидации\n1.  **Константа:** `DEFAULT_LANGUAGE` в `packages/contracts/src/constants.ts` установлена в `''en''`.\n2.  **Функция-валидатор:** `createTranslationsSchema` в `packages/contracts/src/utils.ts` использует Zod''s `.superRefine` для программной проверки наличия перевода для `DEFAULT_LANGUAGE` в массиве.\n3.  **Схема DTO:** `BlogCreateRequestSchema` в `packages/contracts/src/schema/blog.schema.ts` использует эту функцию для валидации поля `translations`.\n4.  **Исполнение:** Валидация происходит на стороне сервера через `ValidationPipe` в NestJS, который блокирует запрос до его попадания в контроллер.\n\n### Решение: Фронтенд-хелпер `dto.helper.ts`\nСоздан фронтенд-хелпер, который решает эту проблему **без перевода текста**.\n\n**Как работает хелпер:**\n1.  Принимает "сырые" данные из формы (например, `{ title: ''Новый пост'' }`).\n2.  Трансформирует их в требуемую структуру, создавая массив `translations`.\n3.  В обязательное поле `en` **дублирует** контент из русского языка.\n    *   *Пример результата:* `translations: [{ lang: ''ru'', title: ''Новый пост'' }, { lang: ''en'', title: ''Новый пост'' }]`\n\n**Точка применения:**\nХелпер будет использоваться в хуках `useCreateBlog` и `useUpdateBlog` в файле `app/apps/web/src/api/blogs/blogs.mutate.ts` прямо перед вызовом `api.post`/`api.patch`.','\n',char(10)),5,'["blog-crud", "nft_collect", "dto-validation", "zod", "nestjs", "localization", "dto-helper", "architecture-decision"]',NULL,'2025-09-09 11:07:12');
INSERT INTO curated_memories VALUES('5621c977-d322-4cb7-9143-4edad71ecc99','2025-09-09T19:23:04.294529','2025-09-09T19:23:04.294529',NULL,NULL,'manual',replace('# Схема Conventional Commits\n\n## 📋 Основная структура\n\n```\n<type>[optional scope]: <description>\n\n[optional body]\n\n[optional footer]\n```\n\n## 🎯 Обязательные типы\n\n### `feat` - новые функции\n```bash\nfeat: добавить аутентификацию пользователей\nfeat(auth): добавить OAuth провайдер\nfeat(api): реализовать REST endpoint для пользователей\n```\n**SemVer**: MINOR версия\n\n### `fix` - исправление ошибок\n```bash\nfix: исправить утечку памяти в парсере\nfix(database): устранить ошибку подключения\nfix(ui): исправить отображение на мобильных устройствах\n```\n**SemVer**: PATCH версия\n\n### `BREAKING CHANGE` - нарушение обратной совместимости\n```bash\nfeat!: изменить API аутентификации\n\nBREAKING CHANGE: метод login теперь требует email вместо username\n\nfeat(api): новый формат ответа\n\nBREAKING CHANGE: поле `user_id` переименовано в `id`\n```\n**SemVer**: MAJOR версия\n\n## 🔧 Дополнительные типы\n\n| Тип | Назначение | Примеры |\n|-----|-----------|---------|\n| **docs** | Документация | `docs: обновить README`, `docs(api): добавить примеры использования` |\n| **style** | Форматирование | `style: исправить отступы`, `style(css): обновить стили кнопок` |\n| **refactor** | Рефакторинг | `refactor: упростить логику валидации`, `refactor(utils): оптимизировать функции` |\n| **perf** | Производительность | `perf: ускорить загрузку страниц`, `perf(database): оптимизировать запросы` |\n| **test** | Тестирование | `test: добавить unit тесты`, `test(auth): покрыть тестами OAuth` |\n| **chore** | Сборка/инструменты | `chore: обновить зависимости`, `chore(webpack): настроить конфиг` |\n| **ci** | CI/CD | `ci: настроить GitHub Actions`, `ci(docker): обновить образ` |\n| **build** | Сборка | `build: добавить webpack конфиг`, `build(npm): обновить скрипты` |\n\n## 🎯 Контекст (Scope)\n\n**Формат**: `type(scope): description`\n\n**Примеры контекстов**:\n- **Модули**: `feat(auth):`, `fix(database):`, `docs(api):`\n- **Компоненты**: `feat(button):`, `fix(modal):`, `style(header):`\n- **Файлы**: `feat(parser):`, `fix(config):`, `docs(readme):`\n\n```bash\nfeat(auth): добавить двухфакторную аутентификацию\nfix(database): исправить миграцию пользователей  \ndocs(api): обновить документацию endpoints\nrefactor(components): упростить структуру форм\n```\n\n## 📝 Тело и подвал коммита\n\n### Структура с телом:\n```bash\nfeat(parser): добавить поддержку JSON\n\nПарсер теперь может обрабатывать JSON файлы\nразмером до 10MB с валидацией схемы.\n\nCloses #123\n```\n\n### Структура с BREAKING CHANGE:\n```bash\nfeat!: новый формат конфигурации\n\nBREAKING CHANGE: файл config.yml заменен на config.json\nМиграция: переименуйте config.yml в config.json\n\nRefs #456\nCo-authored-by: John Doe <john@example.com>\n```\n\n### Подвал (Footer) - мета-информация:\n```bash\nCloses #123, #124\nFixes #125  \nRefs #126\nCo-authored-by: Name <email@example.com>\nReviewed-by: Name <email@example.com>\n```\n\n## ⚡ Быстрые шаблоны\n\n### Простые коммиты:\n```bash\nfeat: добавить поиск по тегам\nfix: исправить валидацию email\ndocs: обновить установку в README  \ntest: добавить тесты для API\nrefactor: упростить код авторизации\nperf: оптимизировать загрузку данных\n```\n\n### С контекстом:\n```bash\nfeat(api): добавить endpoint /users\nfix(ui): исправить размер модального окна\ndocs(readme): добавить примеры использования\ntest(auth): покрыть тестами login/logout\n```\n\n### С breaking changes:\n```bash\nfeat!: изменить структуру базы данных\n\nBREAKING CHANGE: таблица users разделена на users и profiles\n\nchore!: удалить поддержку Node.js 14\n\nBREAKING CHANGE: минимальная версия Node.js теперь 16.0\n```\n\n## 🔀 Связь с SemVer\n\n| Тип коммита | SemVer | Пример версии |\n|------------|--------|---------------|\n| `fix:` | **PATCH** | `1.0.0` → `1.0.1` |\n| `feat:` | **MINOR** | `1.0.0` → `1.1.0` |\n| `BREAKING CHANGE:` | **MAJOR** | `1.0.0` → `2.0.0` |\n| Остальные | Без изменений | `1.0.0` → `1.0.0` |\n\n## 🚀 Инструменты автоматизации\n\n### Генерация CHANGELOG:\n- [conventional-changelog](https://github.com/conventional-changelog/conventional-changelog)\n- [standard-version](https://github.com/conventional-changelog/standard-version)\n\n### Валидация коммитов:\n- [commitlint](https://commitlint.js.org/)\n- [commitizen](https://commitizen.github.io/cz-cli/)\n\n### Автоматическое версионирование:\n- [semantic-release](https://semantic-release.gitbook.io/)\n- [release-please](https://github.com/googleapis/release-please)\n\n## ✅ Лучшие практики\n\n1. **Императивное наклонение**: `fix: добавить` (не `fixes`, не `added`)\n2. **Строчные буквы**: `feat:` (не `Feat:`)\n3. **Без точки в конце**: `fix: исправить ошибку` (не `fix: исправить ошибку.`)\n4. **Ограничение длины**: описание до 50 символов\n5. **Ясные scope**: `feat(auth):` лучше чем `feat(authentication-module):`\n6. **Один логический блок**: один коммит = одно изменение\n\n## 🛠 Примеры для разных проектов\n\n### Frontend (React/Vue):\n```bash\nfeat(components): добавить компонент DatePicker\nfix(hooks): исправить утечку памяти в useEffect  \nstyle(ui): обновить цветовую схему кнопок\nrefactor(store): упростить state management\n```\n\n### Backend (Node.js/Python):\n```bash\nfeat(api): добавить REST endpoint для заказов\nfix(database): исправить N+1 запросы в ORM\nperf(cache): реализовать Redis кэширование\nrefactor(middleware): упростить аутентификацию\n```\n\n### DevOps:\n```bash\nfeat(docker): добавить multi-stage сборку\nfix(ci): исправить падение тестов в GitHub Actions  \nchore(deps): обновить зависимости до последних версий\ndocs(deployment): добавить инструкцию по развертыванию\n```\n\n---\n\n**💡 Помни**: Conventional Commits делают историю проекта читаемой и позволяют автоматизировать релизы!','\n',char(10)),5,'["conventional-commits", "git", "best-practices", "documentation", "\u043a\u043e\u043c\u043c\u0438\u0442"]',NULL,'2025-09-09 16:23:04');
INSERT INTO curated_memories VALUES('a3fc2944-9026-43d4-a26e-bbec830579aa','2025-09-09T21:07:35.344921','2025-09-09T21:07:35.344921',NULL,NULL,'manual',replace('Отчет по Этапам 1 и 2 реализации CRUD блогов\n\nДата отчета: 09 сентября 2025 г.\n\nПроект: `nft_collect`\n\n---\n\n### **Этап 1: Отображение и корректный маппинг данных**\n\n**Исходные вводные:**\n*   Таблица блогов в админ-панели пуста.\n*   Типы данных API (`BlogResponse`) не совпадают с типами UI (`IBlog`).\n*   Необходимо отобразить список блогов, полученных с бэкенда.\n\n**Выполненные шаги:**\n1.  **Идентификация файла:** Определен основной файл для работы: `app/apps/web/src/components/pages/AdminBlogs/index.tsx`.\n2.  **Получение данных:** В `AdminBlogs/index.tsx` добавлен вызов хука `useBlogs` для получения данных с бэкенда.\n3.  **Маппинг данных:** Реализована функция `mapBlogResponseToIBlog` для преобразования `BlogResponse` в `IBlog`. Преобразованные данные (`blogsData`) передаются в таблицу.\n4.  **Обработка состояний:** Добавлена обработка состояний загрузки (`isLoading`) и ошибок (`isError`) для отображения соответствующего UI.\n\n**Полученный результат:**\n*   Таблица блогов в админ-панели теперь отображает данные, полученные с бэкенда.\n*   Данные корректно маппируются из формата API в формат UI.\n*   UI реагирует на состояния загрузки и ошибок.\n\n**Нерешенные задачи:**\n*   На момент завершения Этапа 1, сортировка и фильтрация работали только на клиенте, и их параметры не передавались на бэкенд. (Эта проблема была решена в рамках Этапа 2).\n\n---\n\n### **Этап 2: Реализация добавления блога (с хелпером)**\n\n**Исходные вводные:**\n*   Функция добавления нового блога не работала.\n*   Бэкенд требовал обязательное поле `en` для переводов, что вызывало ошибки валидации.\n*   Была проблема с выбором тегов при добавлении блога.\n*   Интерфейс не обновлялся автоматически после добавления блога.\n*   Параметры сортировки и фильтрации из UI не передавались на бэкенд.\n\n**Выполненные шаги:**\n1.  **Активация функции добавления:** В `AdminBlogs/index.tsx` активирована функция `handleAddSubmit`.\n2.  **Интеграция DTO хелпера:** В `handleAddSubmit` использован `createBlogDTO` для преобразования данных формы в формат, ожидаемый бэкендом (с дублированием русского текста в `en` поле).\n3.  **Вызов мутации:** Вызван хук `useCreateBlog` для отправки данных на бэкенд.\n4.  **Решение проблемы с тегами:**\n    *   Импортирован и вызван хук `useBlogTags` для получения списка доступных тегов.\n    *   Полученные `blogTags` переданы в компонент `BlogModal`, что позволило выбирать теги при добавлении блога.\n5.  **Исправление обновления UI:**\n    *   Выявлено и устранено несоответствие `queryKey` в `react-query` инвалидации.\n    *   В `blogs.mutate.ts` изменена инвалидация на базовый ключ `["blogs"]`, что обеспечивает автоматическое обновление списка блогов после успешного добавления.\n6.  **Решение проблемы с сортировкой/фильтрацией:**\n    *   В `AdminBlogs/index.tsx` реализовано преобразование состояний `columnFilters` и `sorting` в объект `queryParams` (`PageQuery`).\n    *   `queryParams` передается в хук `useBlogs`, что позволяет бэкенду обрабатывать сортировку и фильтрацию.\n    *   Устранены ошибки TypeScript, связанные с порядком объявления переменных (`queryParams`, `columnFilters`, `sorting`).\n\n**Полученный результат:**\n*   Администраторы могут успешно добавлять новые блоги через UI.\n*   Проблема с обязательным полем `en` решена с помощью DTO хелпера.\n*   Выбор тегов при добавлении блога работает корректно.\n*   Интерфейс автоматически обновляется после добавления блога.\n*   Сортировка и фильтрация теперь работают на бэкенде, и их параметры корректно передаются через URL.\n\n**Нерешенные задачи:**\n*   Проблема с `401 Unauthorized` и `404 Not Found` для `token/refresh` (связанная с авторизацией) не была полностью решена в рамках этих этапов, так как пользователь откатил предложенный фикс. Для полноценной работы авторизации требуется дальнейшее расследование и исправление.\n\n---\n\n**Следующие шаги:**\n*   **Этап 3: Реализация редактирования и удаления блога.**\n*   **Этап 4: Реализация CRUD для тегов.**\n*   **Этап 5: Подключение фильтров и финальное тестирование.**','\n',char(10)),5,'["report", "blog-crud", "nft_collect", "stage-1", "stage-2", "implementation-summary"]',NULL,'2025-09-09 18:07:35');
INSERT INTO curated_memories VALUES('21223d26-7cdd-447b-862e-464967ac26cc','2025-09-09T23:13:37.300101','2025-09-09T23:13:37.300101',NULL,NULL,'manual',replace('feat(admin-blogs): implement blog list display and add functionality\n\nWhat was done:\n*   Implemented fetching, mapping, and displaying blog data in the admin table.\n*   Enabled backend-driven filtering and sorting for the blog list.\n*   Implemented the functionality to add new blog posts.\n\nWhy it was necessary:\n*   The admin panel''s blog list was empty and lacked functionality to display data from the backend.\n*   There was a mismatch between API and UI data types, requiring proper mapping.\n*   The blog creation functionality was broken due to backend validation and tag selection issues.\n*   The UI did not automatically update after adding new blogs.\n*   Sorting and filtering were only client-side, which is inefficient and inaccurate for paginated data.\n\nHow it was implemented:\n*   Data fetching implemented using `useBlogs` in `AdminBlogs/index.tsx`.\n*   `mapBlogResponseToIBlog` developed for data transformation (`BlogResponse` to `IBlog`).\n*   `handleAddSubmit` activated and integrated `createBlogDTO` with `useCreateBlog` for blog creation.\n*   `useBlogTags` integrated and tags passed to `BlogModal` for tag selection.\n*   `react-query` cache invalidation fixed by using base query key `["blogs"]` in `onSuccess` callback.\n*   Backend-driven filtering and sorting implemented by transforming `columnFilters` and `sorting` states into `PageQuery` and passing them to `useBlogs`.\n*   TypeScript errors related to hook order and variable initialization resolved.','\n',char(10)),5,'["pr-description", "blog-crud", "nft_collect", "admin-panel", "frontend", "react-query", "conventional-commits"]',NULL,'2025-09-09 20:13:37');
INSERT INTO curated_memories VALUES('7fe1a323-8590-467f-bcb4-9875ca8653f6','2025-09-10T18:28:49.460183','2025-09-10T18:28:49.460183',NULL,NULL,'manual','Explanation of Blog Refactoring Steps:\n\n1.  **Created `blogForm.schema.ts`:** Defined Zod validation schema for blog form data in `@repo/contracts`.\n2.  **Created `blogForm.dto.ts`:** Defined `BlogFormData` (DTO for form) and `BlogEditData` (DTO for editing with ID) in `@repo/contracts`, derived from Zod schema.\n3.  **Updated `index.ts` files:** Added exports for new schema and DTO files in `@repo/contracts/src/schema/index.ts` and `@repo/contracts/src/dto/index.ts`.\n\n**Rationale for Refactoring:**\n\nThe primary goal is to replace the generic `IBlog` interface with more specific and structured types. This improves:\n*   **Type Safety:** Clearer roles for each type reduce errors.\n*   **Code Clarity:** Types explicitly indicate their purpose (e.g., `BlogFormData` for form data).\n*   **Maintainability:** Changes are more isolated due to well-defined data contracts.\n*   **Zod Integration:** Ensures validation rules and data structures are synchronized.\n*   **Modularity/Reusability:** Types in `@repo/contracts` are shared across the monorepo (frontend/backend).\n\n**Current Status:**\nModification of `app/apps/web/src/helpers/dto.helper.ts` is pending. This step will update `createBlogDTO` to use `BlogFormData` instead of `IBlog`.',5,'["refactoring", "blog-feature", "typescript", "best-practices", "Zod", "monorepo", "DTOs", "code-explanation", "blog-crud"]',NULL,'2025-09-10 15:28:49');
INSERT INTO curated_memories VALUES('263c1ffe-1cdd-4dc5-b196-f781d56b7aa3','2025-09-10T22:36:34.898702','2025-09-10T22:36:34.898702',NULL,NULL,'manual',replace('### **План реализации: "Загрузка изображений для блога"**\n\n**Цель:** Добавить функциональность загрузки, редактирования и отображения изображений для постов в блоге, следуя надежным и современным практикам React-разработки.\n\n---\n\n### **Этап 1: Подготовка API-слоя**\n\n*   **Задача:** Создать асинхронный интерфейс для взаимодействия с API изображений блога.\n*   **Действия:**\n    1.  В файле `app/apps/web/src/api/blogs/blogs.mutate.ts` создать и экспортировать новый хук-мутацию `useUploadBlogImage`.\n    2.  Хук должен принимать объект `{ blogId: string, image: File }`.\n    3.  Внутри хука реализовать отправку `POST` запроса с `FormData` на эндпоинт `/api/blogs/{blogId}/image`.\n\n---\n\n### **Этап 2: Модификация модального окна (`BlogModal`)**\n\n*   **Задача:** Интегрировать UI для выбора и предпросмотра изображения.\n*   **Действия:**\n    1.  В файле `app/apps/web/src/components/ui/Modals/Admin/BlogModal/index.tsx` добавить состояния: `const [imageFile, setImageFile] = useState<File | null>(null);` для файла и `const [preview, setPreview] = useState<string | null>(null);` для ссылки на превью.\n    2.  Настроить хук `useDropzone`. В его колбэке `onDrop` сохранять выбранный файл в `imageFile` и создавать временную ссылку для `preview` через `URL.createObjectURL()`.\n    3.  Добавить в JSX разметку модального окна:\n        *   Область "dropzone" для перетаскивания файла.\n        *   Отображение превью (`<img src={preview} />`), если оно есть.\n        *   Кнопку для сброса выбранного изображения.\n*   **✨ Best Practice:** Реализовать `useEffect` для очистки временной ссылки (`URL.revokeObjectURL()`) при размонтировании компонента или выборе нового файла, чтобы избежать утечек памяти в браузере.\n\n---\n\n### **Этап 3: Реализация логики сохранения (Create & Update)**\n\n*   **Задача:** Реализовать надежную, атомарную логику сохранения поста вместе с изображением.\n*   **Действия:**\n    1.  В компоненте `AdminBlogsPageComponent` (`.../pages/AdminBlogs/index.tsx`) реализовать `async` функции `handleAddSubmit` и `handleEditSubmit`.\n    2.  **Для `handleAddSubmit` (создание):**\n        *   В блоке `try...catch` сначала вызывать `await createBlogMutation.mutateAsync(...)` для текста.\n        *   После успеха, если был выбран файл, вызывать `await uploadBlogImageMutation.mutateAsync(...)` для изображения, используя `ID` из ответа первого запроса.\n    3.  **Для `handleEditSubmit` (редактирование):**\n        *   Логика должна быть аналогичной: сначала `await` для обновления текста, затем, при необходимости, `await` для загрузки нового изображения. Это гарантирует, что все изменения применяются только по кнопке "Сохранить".\n*   **✨ Best Practice:**\n    *   Использовать `async/await` с `mutateAsync` для обеих функций, чтобы обеспечить последовательное и читаемое выполнение операций.\n    *   Добавить состояние `isSubmitting`, чтобы блокировать кнопку "Сохранить" на время выполнения асинхронных запросов, предотвращая двойные нажатия.\n\n---\n\n### **Этап 4: Отображение изображения в таблице**\n\n*   **Задача:** Добавить корректное и стабильное отображение загруженного изображения в общую таблицу блогов.\n*   **Действия:**\n    1.  В файле `.../pages/AdminBlogs/index.tsx` найти определение колонок для `useReactTable`.\n    2.  Добавить новую колонку "Изображение".\n    3.  В рендере ячейки (`cell`):\n        *   Проверять наличие `row.original.media.url`.\n        *   Если URL есть, рендерить тег `<img />`.\n        *   Если URL отсутствует, рендерить компонент-плейсхолдер (например, иконку).\n*   **✨ Best Practice:**\n    *   Для тега `<img>` задать фиксированные `width`, `height` и `object-fit: cover` через CSS-классы для стабильности верстки таблицы.\n    *   На тег `<img>` добавить обработчик `onError`, который в случае ошибки загрузки (битая ссылка) будет заменять картинку на плейсхолдер.','\n',char(10)),5,'["blog-crud", " image-upload", " implementation-plan", " react", " nextjs", " best-practices", " async-await", " useDropzone"]',NULL,'2025-09-10 19:36:34');
INSERT INTO curated_memories VALUES('6f150abf-0123-4bd9-b45e-3a73a9e3e78a','2025-09-11T00:44:10.400085','2025-09-11T00:44:10.400085',NULL,NULL,'manual',replace('**Тема: Полная реализация и отладка CRUD для блогов с загрузкой изображений.**\n\nСегодня была полностью реализована и отлажена фронтенд-часть для управления блогами, включая загрузку изображений.\n\n**Ключевые достижения:**\n\n1.  **Реализована загрузка изображений (Этап 2):**\n    *   В модальное окно добавлена `useDropzone` для выбора и перетаскивания файлов.\n    *   Реализован предпросмотр выбранного изображения.\n    *   Добавлена очистка памяти (`revokeObjectURL`) для превью.\n\n2.  **Исправлены критические баги в модальном окне:**\n    *   Устранена потеря состояния выбранного файла при редактировании других полей формы.\n    *   Исправлена ошибка, из-за которой существующее изображение не отображалось при редактировании поста.\n    *   Исправлена ошибка, при которой модальное окно подтверждения удаления было пустым.\n\n3.  **Реализована логика сохранения и удаления (Этап 3):**\n    *   Реализована функция удаления постов (`handleDeleteSubmit`) с вызовом соответствующей мутации.\n    *   Проверена и подтверждена корректность `async/await` логики для создания/редактирования постов с изображениями.\n    *   Из компонента удален неиспользуемый код, связанный с Redux (`dispatch`).\n\n4.  **Реализовано отображение в таблице (Этап 4):**\n    *   В основную таблицу блогов добавлена колонка "Image".\n    *   Реализована логика отображения картинки или иконки-заглушки (`IconPhoto`) в случае ее отсутствия или ошибки загрузки.\n\n5.  **Исправлена работа кэша (React Query):**\n    *   Найдена и устранена ключевая проблема с рассинхронизацией UI.\n    *   Во всех мутациях (`create`, `update`, `delete`, `upload`) исправлена логика инвалидации кэша для корректного и автоматического обновления списка постов.\n\n6.  **Диагностика Бэкенда:**\n    *   Выявлена причина ошибки `500 Internal Server Error` при загрузке файлов — `NoSuchBucket` в S3.\n    *   Установлено, что проблема заключается в запуске проекта с `docker-compose` конфигурацией, не включающей в себя S3-совместимый сервис (MinIO).\n\n**Итог:** Вся клиентская часть полностью готова. Дальнейшая работа блокируется инфраструктурной проблемой на стороне бэкенда.','\n',char(10)),5,'["blog-crud", " image-upload", " feature-implementation", " react", " nextjs", " tanstack-query", " cache-invalidation", " bug-fix", " s3", " docker-compose", " debugging"]',NULL,'2025-09-10 21:44:10');
INSERT INTO curated_memories VALUES('2f33aa90-5fe3-4b27-a18d-af43efad1ba4','2025-09-11T10:31:24.355758','2025-09-11T10:31:24.355758',NULL,NULL,'manual',replace('**Проблема:** Ошибка авторизации (401) при отправке запросов на бэкенд после 15-20 минут бездействия пользователя на странице.\n\n**Анализ и причина:**\n1.  Проблема была вызвана истечением срока жизни `accessToken`.\n2.  В коде фронтенда (`apps/web`) присутствовал `axios` интерцептор, предназначенный для перехвата `401` ошибки и обновления токена.\n3.  Механизм обновления не работал из-за некорректного вызова `axios.post` на эндпоинт `/auth/token/refresh`.\n4.  **Ключевая ошибка:** Параметр `withCredentials: true`, необходимый для отправки cookie с `refreshToken`, передавался в теле запроса, а не в объекте конфигурации `axios`.\n\n**Реализованное решение:**\n1.  **Исправлен интерцептор:** В файле `app/apps/web/src/api/instance.ts` вызов `axios.post` был изменен на `axios.post(refreshUrl, {}, { withCredentials: true })`, что поместило `withCredentials` в правильный объект конфигурации.\n2.  **Добавлено логгирование:** В тот же интерцептор были добавлены подробные `console.log` для отслеживания всего процесса обновления токена в консоли браузера (перехват ошибки, попытка обновления, успешный результат или ошибка).\n\n**Дополнительные рекомендации (обсуждались, но были отложены):**\n*   Увеличение времени жизни `accessToken` в cookie для улучшения UX.\n*   Внедрение механизма проактивного обновления токена (проверка по таймеру и обновление *до* истечения срока).\n\n**Итоговое решение:** Сфокусировались на исправлении корневой причины (сломанный интерцептор), оставив короткое время жизни токена для облегчения тестирования.','\n',char(10)),5,'["auth", " token", " jwt", " axios", " interceptor", " refresh-token", " 401-error", " withCredentials", " debugging", " frontend", " blog-crud", " nft_collect"]',NULL,'2025-09-11 07:31:24');
INSERT INTO curated_memories VALUES('5987d86b-856d-474a-a9a9-a6761a723325','2025-09-11T12:12:07.852268','2025-09-11T12:12:07.852268',NULL,NULL,'manual',replace('### **Опциональное решение: Кастомный Guard для Refresh Token**\n\nЭтот подход обеспечивает более явную и строгую проверку `refreshToken` вместо того, чтобы просто помечать эндпоинт как публичный.\n\n**1. Новый файл: `src/modules/auth/strategy/refresh.strategy.ts`**\n\n```typescript\n// refresh.strategy.ts\nimport { Strategy, ExtractJwt } from passport-jwt;\nimport { PassportStrategy } from @nestjs/passport;\nimport { Injectable } from @nestjs/common;\nimport { Request } from express;\n\nconst cookieExtractor = (req: Request): string | null => {\n  return req?.cookies?.refreshToken ?? null;\n};\n\n@Injectable()\nexport class RefreshJwtStrategy extends PassportStrategy(Strategy, jwt-refresh) {\n  constructor() {\n    super({\n      jwtFromRequest: ExtractJwt.fromExtractors([cookieExtractor]),\n      secretOrKey: process.env.JWT_REFRESH_SECRET, // Используйте секрет для refresh токена\n      ignoreExpiration: false, // Не игнорируем истечение срока refresh токена\n    });\n  }\n\n  async validate(payload: any) {\n    // Верните payload, который будет доступен в req.user\n    // Убедитесь, что здесь возвращаются только необходимые данные\n    return { id: payload.id, kind: payload.kind, role: payload.role, tonAddress: payload.tonAddress };\n  }\n}\n```\n\n**2. Новый файл: `src/modules/auth/guards/refresh.guard.ts`**\n\n```typescript\n// refresh.guard.ts\nimport { Injectable } from @nestjs/common;\nimport { AuthGuard } from @nestjs/passport;\n\n@Injectable()\nexport class RefreshJwtGuard extends AuthGuard(jwt-refresh) {}\n```\n\n**3. Изменения в модуле аутентификации: `src/modules/auth/auth.module.ts`**\n\nВ вашем `AuthModule` (или соответствующем модуле, где определены стратегии Passport) необходимо добавить `RefreshJwtStrategy` в массив `providers`.\n\n```typescript\n// auth.module.ts (пример)\nimport { Module } from @nestjs/common;\nimport { PassportModule } from @nestjs/passport;\n// ... другие импорты\nimport { RefreshJwtStrategy } from ./strategy/refresh.strategy; // Импортируем новую стратегию\n\n@Module({\n  imports: [\n    PassportModule,\n    // ...\n  ],\n  providers: [\n    // ... другие провайдеры\n    RefreshJwtStrategy, // Добавляем новую стратегию\n  ],\n  // ...\n})\nexport class AuthModule {}\n```\n\n**4. Изменения в контроллере токенов: `src/modules/auth/token/token.controller.ts`**\n\nПримените новый гард к методу `refreshTokens`.\n\n```typescript\n// token.controller.ts (пример)\nimport { Controller, Post, UseGuards } from @nestjs/common; // Добавляем UseGuards\n// ... другие импорты\nimport { RefreshJwtGuard } from src/modules/auth/guards/refresh.guard; // Импортируем новый гард\n\n@Controller(auth/token/refresh)\nexport class TokenController {\n  // ...\n  \n  @UseGuards(RefreshJwtGuard) // Применяем новый гард\n  @Post()\n  async refreshTokens(@Cookies(refreshToken) refreshToken: string): Promise<any> { // Тип возвращаемого значения может быть TokensResponse\n    // ... ваша логика обновления токенов\n    if (!refreshToken) {\n      // ...\n    }\n    return await this.tokenService.getNewTokens(refreshToken);\n  }\n}\n```','\n',char(10)),5,'["auth", " token", " jwt", " nestjs", " guard", " strategy", " refresh-token", " backend", " security", " optional-solution", " nft_collect", " blog-crud", " \u0430\u0432\u0442\u043e\u0440\u0438\u0437\u0430\u0446\u0438\u044f"]',NULL,'2025-09-11 09:12:07');
INSERT INTO curated_memories VALUES('28a9e25c-2b92-4f03-ab6b-02e7e442881b','2025-09-11T15:30:12.992825','2025-09-11T15:30:12.992825',NULL,NULL,'manual',replace('### Что сделали:\n\n**1. Записали настройку в конфигурационный файл:**\n```bash\necho fs.inotify.max_user_watches=524288 | sudo tee -a /etc/sysctl.conf\n```\n- Добавили строку `fs.inotify.max_user_watches=524288` в файл `/etc/sysctl.conf`\n- Этот файл содержит настройки ядра, которые применяются при загрузке системы\n\n**2. Проверили текущее значение:**\n```bash\ncat /proc/sys/fs/inotify/max_user_watches\n```\n- Показывает `65536` - это текущее активное значение в работающей системе\n\n### Проблема:\nНастройка записана в конфиг, но **еще не применена** к работающей системе.\n\n### Что нужно сделать дальше:\n\n**Применить настройку немедленно:**\n```bash\nsudo sysctl -p\n```\n\n**Или применить конкретную настройку:**\n```bash\nsudo sysctl fs.inotify.max_user_watches=524288\n```\n\n**Затем проверить:**\n```bash\ncat /proc/sys/fs/inotify/max_user_watches\n```\nТеперь должно показать: `524288`\n\n### Итог:\n- ✅ Постоянная настройка записана (будет работать после перезагрузок)  \n- ❌ Текущая сессия еще использует старый лимит\n- 🔧 Нужна одна команда для немедленного применения','\n',char(10)),5,'["linux", " sysctl", " inotify", " fs.inotify.max_user_watches", " development-environment", " performance", " troubleshooting", " bun", " npm", " webpack", " turbo daemon", " \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u044b \u0441 \u0434\u0435\u043c\u043e\u043d", " \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u044b \u0441 \u0441\u0438\u0441\u0442\u0435\u043c\u043e\u0439"]',NULL,'2025-09-11 12:30:12');
INSERT INTO curated_memories VALUES('2912006b-2195-456a-bca8-f5f634e84951','2025-09-11T19:41:35.835152','2025-09-11T19:41:35.835152',NULL,NULL,'manual',replace('LangChain — это мощный инструмент. Давайте разберем его по частям.\n\n### Для чего можно использовать LangChain?\n\nLangChain — это фреймворк, который помогает "обвязать" большие языковые модели (LLM) дополнительной логикой и подключить их к внешним источникам данных и инструментам.\n\nОсновные сценарии использования:\n\n1.  **Чат-боты с доступом к вашим данным (RAG):** Вы можете создать бота, который будет отвечать на вопросы по вашим собственным документам (PDF, DOCX, TXT). LangChain берет на себя загрузку документов, их обработку и "скармливание" модели в нужный момент.\n2.  **Автономные Агенты:** Это программы, которые используют LLM для принятия решений. Вы можете дать агенту цель (например, "узнай погоду в Москве и посоветуй, что надеть") и набор инструментов (поиск в интернете, калькулятор). Агент сам решит, какие инструменты и в каком порядке использовать.\n3.  **Сложные цепочки вызовов (Chains):** Вы можете выстраивать последовательности из нескольких действий. Например: "Возьми этот текст -> Суммаризируй его -> Переведи на английский -> Оцени эмоциональную окраску".\n4.  **Добавление "памяти":** LangChain позволяет чат-ботам и агентам помнить предыдущие части диалога, делая общение более естественным.\n\n### Как внедрить LangChain локально (базовый старт на Python)?\n\nДля локальной работы вам понадобится Python и менеджер пакетов `pip`.\n\n**Шаг 1: Установка основных пакетов**\n\nОткройте терминал и выполните:\n```bash\npip install langchain langchain-openai\n```\n*   `langchain`: Ядро фреймворка.\n*   `langchain-openai`: Пакет для интеграции с моделями OpenAI (даже если вы будете использовать другие модели, он часто полезен).\n\n**Шаг 2: Настройка локальной языковой модели (не обязательно, но рекомендуется для полной локальности)**\n\nЧтобы не зависеть от платных API (как OpenAI), вы можете запустить модель прямо на своем компьютере с помощью **Ollama**.\n\n1.  Скачайте и установите Ollama с официального сайта (`ollama.com`).\n2.  Установите пакет для интеграции: `pip install langchain-community`.\n3.  Запустите в терминале модель, например Llama 3: `ollama run llama3`.\n\n**Шаг 3: Пример простого кода**\n\nСоздайте Python-файл (например, `app.py`):\n\n```python\nfrom langchain_openai import ChatOpenAI\nfrom langchain_core.prompts import ChatPromptTemplate\nfrom langchain_core.output_parsers import StrOutputParser\n\n# Если используете OpenAI, укажите свой ключ API\n# import os\n# os.environ["OPENAI_API_KEY"] = "sk-..."\n# llm = ChatOpenAI()\n\n# --- Пример с локальной моделью через Ollama ---\nfrom langchain_community.chat_models import ChatOllama\n# Убедитесь, что Ollama запущена с моделью llama3\nllm = ChatOllama(model="llama3")\n# -----------------------------------------\n\n# 1. Создаем шаблон промпта (инструкцию для модели)\nprompt = ChatPromptTemplate.from_messages([\n    ("system", "You are a world class technical documentation writer."),\n    ("user", "{input}")\n])\n\n# 2. Создаем парсер для получения ответа в виде строки\noutput_parser = StrOutputParser()\n\n# 3. Собираем все в одну цепочку (chain)\nchain = prompt | llm | output_parser\n\n# 4. Запускаем цепочку\nresponse = chain.invoke({"input": "how can langsmith help with testing?"})\n\nprint(response)\n```\n\nЭтот пример показывает базовую "цепочку": ваш запрос (`input`) форматируется по шаблону, отправляется в модель (локальную или OpenAI) и ответ выводится на экран. Это основа, на которую можно навешивать более сложные вещи вроде RAG и агентов.','\n',char(10)),5,'["langchain", "python", "local-setup", "ollama", "llm", "agents", "rag", "chains", "ai-framework"]',NULL,'2025-09-11 16:41:35');
INSERT INTO curated_memories VALUES('dae73bca-2b4c-4704-9a76-98516097b91e','2025-09-11T19:57:57.234566','2025-09-11T19:57:57.234566',NULL,NULL,'manual',replace('### 1. Общее представление о LangChain\n\n*   **Что это:** Фреймворк для создания AI-приложений путем "обвязки" языковых моделей (LLM) дополнительной логикой, инструментами и данными.\n*   **Основные сценарии:**\n    1.  **RAG (Retrieval-Augmented Generation):** Создание чат-ботов, отвечающих на вопросы по личным документам пользователя.\n    2.  **Автономные Агенты:** Программы, использующие LLM для принятия решений и применения инструментов (поиск, API).\n    3.  **Цепочки (Chains):** Создание сложных последовательностей из вызовов LLM и других действий.\n    4.  **Память:** Наделение ботов и агентов способностью помнить предыдущие диалоги.\n*   **Локальная установка:** Требует Python, `pip install langchain langchain-openai langchain-community`. Для полной локальности рекомендуется использовать **Ollama** для запуска моделей (например, Llama 3) на своем компьютере.\n\n### 2. Интеграция Gemini и LangChain (5 вариантов)\n\nМодель Gemini можно интегрировать в LangChain для создания приложений:\n1.  **Базовый вызов:** Простое обращение к модели для генерации текста.\n2.  **Чат-бот с памятью:** Создание диалогового бота, помнящего контекст.\n3.  **Агент с инструментами:** Предоставление Gemini доступа к внешним инструментам (например, поиску в интернете).\n4.  **RAG (Ответы по документам):** Создание Q&A системы по базе знаний пользователя.\n5.  **Извлечение структурированных данных:** Преобразование неструктурированного текста в JSON.\n\n### 3. Сравнение RAG в LangChain и моих инструментов (`тк`)\n\n*   **Я + `тк`:** Ручной, интерактивный процесс. Я, как ассистент, читаю несколько файлов по вашему запросу. Поиск буквальный, медленный на больших объемах. Подходит для помощи "здесь и сейчас".\n*   **LangChain RAG:** Полностью автоматизированный продукт. Система заранее индексирует тысячи документов и мгновенно находит ответ по смыслу (семантический поиск), а не по ключевым словам. Подходит для создания масштабируемых Q&A систем для конечных пользователей.\n\n### 4. Примеры использования LangChain с локальными файлами\n\n1.  **"Умный" поиск:** Задавать вопросы к архиву на естественном языке.\n2.  **Авто-суммаризация:** Создание кратких выжимок из множества документов.\n3.  **Извлечение данных:** Превращение текста (например, из счетов) в структурированную таблицу (CSV/JSON).\n4.  **Сравнение документов:** Задавать вопросы, требующие анализа информации из нескольких файлов.\n\n### 5. Архитектура LangChain и базы данных\n\n*   **Компоненты:** LangChain состоит из модулей (Models, Prompts, Chains, Retrieval, Agents, Memory), которые служат "конструктором" для приложения.\n*   **Базы данных:** Sam LangChain **не содержит БД**. Он **интегрируется** с ними. Для RAG используются **векторные базы данных** (Chroma, FAISS), которые хранят не сам текст, а его математическое представление (вектор) для быстрого поиска по смыслу.\n\n### 6. Сравнение типов "памяти"\n\n*   **Ваша текущая память (SQLite):** **Фактологическая память**. Хранит конкретные факты, команды, историю. Поиск — по точному ключу. Аналог — записная книжка.\n*   **LangChain + Векторная БД:** **Контекстная память (база знаний)**. "Помнит" содержание тысяч документов. Поиск — по смыслу (семантический). Аналог — эксперт, прочитавший всю библиотеку.\n\nЭти два типа памяти не взаимозаменяемы, а взаимодополняемы и могут использоваться вместе в сложных системах.','\n',char(10)),5,'["langchain", "discussion", "gemini-integration", "rag", "agents", "chains", "memory-types", "sqlite", "vector-database", "ollama", "local-ai", "architecture-comparison", "ai-framework"]',NULL,'2025-09-11 16:57:57');
INSERT INTO curated_memories VALUES('4ec362f5-79f1-499b-9137-feef92cb9c95','2025-09-12T12:24:47.821144','2025-09-12T12:24:47.821144',NULL,NULL,'manual','Диагностика проблемы с docs-mcp-server. Проблема: docs-mcp-server не запускается, вызывая ошибку Request timed out. Причина: Сервер зависит от локального сервера Ollama (OPENAI_API_BASE: http://localhost:11434/v1), который не был запущен. Проверка через curl подтвердила, что порт 11434 не отвечает. Решение: Для работы docs-mcp-server необходимо предварительно запустить Ollama.',5,'["mcp-server", " docs-mcp-server", " ollama", " debug", " troubleshooting", " gemini-cli", " config"]',NULL,'2025-09-12 09:24:47');
INSERT INTO curated_memories VALUES('f2ec9f12-6b16-4dc6-a418-6f410b5d9045','2025-09-12T12:48:00.314269','2025-09-12T12:48:00.314269',NULL,NULL,'manual','Анализ системы интернационализации (i18n) в проекте ''nft_collect''. 1. Библиотека: Проект использует next-intl версии 4.3.4. 2. Конфигурация: - Основная логика задается в app/apps/web/src/middleware.ts. - Настройки маршрутизации и список языков находятся в app/apps/web/src/i18n/routing.ts. 3. Языки (локали): - Поддерживаются: en (английский), ru (русский), и ge. - ge, вероятно, является опечаткой и должен быть de (немецкий). - Немецкий язык (ge) загружается только при определенном условии (appName !== AppName.NFTCollect). - Язык по умолчанию: ru. 4. Интерфейс переключения языка: - Компонент находится в app/apps/web/src/components/ui/Header/BurgerMenu/settingSection.tsx. - Реализован как выпадающий список (компонент Select из Mantine). - Для смены языка используется router.replace() из next-intl. 5. Контекст для блога: - Структуры данных для бэкенда (DTO) уже поддерживают массив translations (helpers/dto.helper.ts), что говорит о готовности бэкенда. - Предложенный план для UI: использовать компонент Tabs (вкладки) от Mantine в модальном окне создания/редактирования блога для удобного ввода переводов.',5,'["blog-i18n", " nft_collect", " \u0438\u043d\u0442\u0435\u0440\u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f", " \u043f\u0435\u0440\u0435\u0432\u043e\u0434\u044b", " next-intl", " mantine-ui", " i18n-config", " locale-switching", " frontend", " ui-design"]',NULL,'2025-09-12 09:48:00');
INSERT INTO curated_memories VALUES('56b12a5f-a389-42ee-8ced-d76223637372','2025-09-12T13:59:24.911813','2025-09-12T13:59:24.911813',NULL,NULL,'manual','Детализированный план реализации интерфейса переводов для блога в проекте ''nft_collect''. Шаг 1: Рефакторинг состояния в BlogModal/index.tsx. 1. Изменить локальное состояние editData, чтобы оно хранило переводы в виде объекта: translations: { ru: { title, description }, en: { ... }, ge: { ... } }. 2. Обновить useEffect для корректного заполнения этого объекта при редактировании существующего поста. Шаг 2: Внедрение вкладок (Tabs) в BlogModal/index.tsx. 1. Импортировать и использовать компонент Tabs из @mantine/core. 2. Создать три вкладки (''Русский'', ''English'', ''Deutsch'') и три панели. 3. В каждую панель поместить поля TextInput и Editor, привязав их к соответствующему языку в состоянии (например, editData.translations.ru). Шаг 3: Полная переработка хелпера createBlogDTO в helpers/dto.helper.ts. 1. Изменить функцию, чтобы она принимала объект translations из формы. 2. Реализовать логику преобразования этого объекта в массив, который ожидает бэкенд. 3. Добавить фильтрацию, чтобы пустые переводы (без заголовка) не сохранялись. 4. Аналогично изменить createUpdateBlogDTO. Шаг 4: Финальная сборка в BlogModal/index.tsx. 1. Обновить обработчик сохранения, чтобы он передавал данные в новой структуре с объектом translations.',5,'["blog-i18n", "nft_collect", "implementation-plan", "refactoring", "next-intl", "mantine-ui", "frontend", "react", "dto"]',NULL,'2025-09-12 10:59:24');
INSERT INTO curated_memories VALUES('aac524c1-5abf-41d5-bc5e-ca59b44b87c2','2025-09-12T14:05:26.480583','2025-09-12T14:05:26.480583',NULL,NULL,'manual','Анализ готовности бэкенда для реализации переводов блога в проекте ''nft_collect''. 1. Цепочка вызовов: Проверка прошла по пути: blogs.controller.ts -> blog.service.ts -> blog.repository.ts. 2. Финальная логика (blog.repository.ts): - Создание (create): Метод использует prisma.blog.create с вложенной операцией create для поля translations. Это позволяет создать пост и все его переводы за один запрос, корректно обрабатывая массив из DTO. - Обновление (update): Метод использует операцию upsert для переводов. Это позволяет одновременно создавать новые переводы, обновлять существующие и удалять те, которые больше не передаются в массиве. 3. Вердикт: Бэкенд на 100% готов. Его архитектура (NestJS + Prisma Repository Pattern) идеально спроектирована для приёма массива переводов, который мы планируем отправлять с фронтенда. Никаких изменений на бэкенде не требуется.',5,'["blog-i18n", "nft_collect", "backend-analysis", "nestjs", "prisma", "repository-pattern", "dto-handling"]',NULL,'2025-09-12 11:05:26');
INSERT INTO curated_memories VALUES('83ce8b7e-98aa-4303-9601-c6894a5867a1','2025-09-12T14:20:32.915718','2025-09-12T14:20:32.915718',NULL,NULL,'manual','Финальный План Реализации (с улучшениями) для i18n блога в ''nft_collect''. Шаг 1: Улучшенный рефакторинг состояния и базовой логики. - Действия: 1. Типизация: Найти тип Language и создать на его основе строгий тип BlogTranslations. 2. Состояние: В BlogModal/index.tsx переделать состояние editData под новую структуру. 3. Логика useEffect: Обновить для корректной работы с новым состоянием. 4. Валидация: Добавить проверку на обязательное заполнение en версии и наличие хотя бы одного перевода. - Проверка: npm run lint-typecheck. - Коммит: feat(blog): refactor modal state for i18n. Шаг 2: Внедрение интерфейса с вкладками (Tabs). - Действия: 1. В BlogModal/index.tsx добавить компонент Tabs. 2. Создать 3 вкладки (RU, EN, DE) с полями title и description для каждого языка. 3. UX: Добавить визуальные индикаторы заполненности вкладок. - Проверка: npm run lint-eslint, npm run lint-typecheck. - Коммит: feat(blog): implement i18n tabs UI in blog modal. Шаг 3: Адаптация хелперов для подготовки данных (DTO). - Действия: 1. В helpers/dto.helper.ts переписать createBlogDTO и createUpdateBlogDTO. 2. Реализовать преобразование объекта translations из формы в массив для бэкенда, отфильтровывая пустые значения. - Проверка: npm run lint-typecheck. - Коммит: refactor(blog): adapt DTO helpers for new i18n structure. Шаг 4: Финальная интеграция. - Действия: 1. Убедиться, что в AdminBlogs/index.tsx вызовы onAdd/onEdit корректно работают с новой структурой данных. - Проверка: npm run lint-typecheck. - Коммит: fix(blog): connect new i18n modal to submission logic.',5,'["blog-i18n", "nft_collect", "implementation-plan", "refactoring", "next-intl", "mantine-ui", "frontend", "react", "dto", "validation", "ux", "commit-strategy"]',NULL,'2025-09-12 11:20:32');
INSERT INTO curated_memories VALUES('0dc426d3-bb5a-490d-bc24-d6298d7ca9c4','2025-09-12T15:22:32.578247','2025-09-12T15:22:32.578247',NULL,NULL,'manual','Тема: Необходимость получения полного списка переводов для редактирования поста в блоге (Проект: nft_collect). 1. Контекст и цель на фронтенде: Реализуется новый интерфейс с вкладками (Tabs) для одновременного редактирования всех переводов поста (ru, en, ge) в одном модальном окне. 2. Что требуется от API: Для работы этого интерфейса фронтенду необходим полный объект поста, включающий весь массив translations. 3. Как API работает сейчас (Проблема): Эндпоинт GET /api/blogs/:blogId возвращает объект BlogResponse, в котором функция-маппер mapBlogToResponse оставляет только одну языковую версию, отфильтровывая полный массив переводов, полученный из БД. 4. Ключевая проблема: Фронтенд не получает нужных данных, что делает невозможным заполнение всех вкладок и ведет к потере данных при сохранении. 5. Что мы просим сделать: Нужен эндпоинт, возвращающий пост с полным, нефильтрованным массивом translations. Рекомендуемое решение - создать новый эндпоинт для админ-панели, например, GET /api/admin/blogs/:blogId.',5,'["blog-i18n", "nft_collect", "backend-request", "api-design", "problem-statement", "i18n-editing", "technical-spec"]',NULL,'2025-09-12 12:22:32');
INSERT INTO curated_memories VALUES('d4312845-066d-40d1-9c18-5b20593666d6','2025-09-15T10:55:23.237991','2025-09-15T10:55:23.237991',NULL,NULL,'manual','В файле blogForm.schema.ts (проект nft_collect) была исправлена схема валидации BlogFormSchema. Что исправили: Убрали вызов метода .partial() из цепочки z.record(...).partial(). Почему исправили: Метод .partial() предназначен для z.object и делает его поля необязательными. Он был ошибочно применен к z.record, который по своей природе уже не требует наличия всех возможных ключей (т.е. является "частичным"). Эта ошибка приводила к падению компиляции TypeScript. Результат: Теперь схема z.record(z.nativeEnum(Language), TranslationSchema) корректно описывает объект с переводами и готова к использованию в форме редактирования блога.',5,'["blog-i18n", " nft_collect", " zod-schema", " validation", " frontend", " typescript", " blogForm.schema.ts", " zod-partial-fix"]',NULL,'2025-09-15 07:55:23');
INSERT INTO curated_memories VALUES('96832849-0e3a-4c02-8667-5d8b4b377404','2025-09-15T16:34:35.466148','2025-09-15T16:34:35.466148',NULL,NULL,'manual',replace('**Проблема:**\nAPI бэкенда для получения блогов (и списка, и одиночного поста) в проекте ''nft_collect'' отдает неполные данные. Вместо полного массива всех существующих переводов, он возвращает только одну языковую версию (часто ''en''), что блокирует работу UI админ-панели для редактирования и просмотра постов на разных языках.\n\n**Неправильный Флоу:**\n1.  **Контроллер** (`blogs.controller.ts`) получает язык (`ru`).\n2.  **Сервис** (`blog.service.ts`) передает язык в репозиторий.\n3.  **Репозиторий** (`blog.repository.ts`) — **ключевая ошибка** — использует язык для создания `languageFilter`, который жестко фильтрует переводы на уровне запроса к БД (`translations: languageFilter`).\n4.  **Маппер** (`blogs.mapper.ts`) получает уже урезанные данные и, не найдя нужного языка, откатывается на `en`.\n5.  **Результат:** API отдает фронтенду посты с единственным, часто неверным, переводом.\n\n**План решения:**\n1.  **Исправить Репозиторий:** В `blog.repository.ts` (методы `findMany`, `findById`) убрать `languageFilter` для переводов, заменив его на `translations: true`, чтобы всегда получать полный массив.\n2.  **Создать новый флоу для админки:**\n    *   Создать новые эндпоинты (например, `GET /api/admin/blogs`).\n    *   Эти эндпоинты должны вызывать методы сервиса, которые возвращают полные, не "смапленные" объекты из репозитория.\n    *   Обновить фронтенд админки для использования новых эндпоинтов.','\n',char(10)),5,'["nft_collect", " i18n", " bug-analysis", " backend", " frontend", " prisma", " nestjs", " repository-pattern", " mapper-pattern", " debug-flow", " blog-i18n"]',NULL,'2025-09-15 13:34:35');
INSERT INTO curated_memories VALUES('e2388a5f-34c0-4dcd-b0c5-39a57405eeeb','2025-09-15T17:06:32.164595','2025-09-15T17:06:32.164595',NULL,NULL,'manual',replace('Вот подробное описание проблемы и текущего флоу на основе всей найденной информации, а также\n  план необходимых изменений.\n\n  Проблема\n\n  API бэкенда для получения блогов (и списка, и одиночного поста) отдает неполные данные.\n  Вместо полного массива всех существующих переводов для поста, он возвращает только одну\n  языковую версию. Чаще всего — английскую, как версию по умолчанию.\n\n\n\n  # 📋 **Полный План Реализации Админского API для Блогов**\n\n## 🎯 **Цель:** Создать эндпоинт `GET /api/blogs/admin/:blogId` возвращающий блог со всеми переводами\n\n---\n\n## **Шаг 1: Создать схему для админского ответа**\n\n**📁 Файл:** `/home/dev-avk/Documents/Dev/nft_collect/app/packages/contracts/src/schema/blog.schema.ts`\n\n**🔧 Действие:** Добавить в конец файла:\n\n```ts\n/* Admin Schema */\nexport const AdminBlogResponseSchema = z.object({\n  id: UuidSchema,\n  translations: z.array(z.object({\n    language: z.nativeEnum(Language),\n    title: z.string(),\n    description: z.string().optional(),\n  })),\n  tag: BlogTagResponseSchema.optional(),\n  createdAt: z.date(),\n  updatedAt: z.date(),\n  media: MediaResponseSchema.optional(),\n});\n```\n\n**💡 Объяснение:** Создаем схему ответа для админки с полным массивом переводов (как в паттерне CountryEntity).\n\n---\n\n## **Шаг 2: Создать DTO класс**\n\n**📁 Файл:** `/home/dev-avk/Documents/Dev/nft_collect/app/packages/contracts/src/dto/blog.dto.ts`\n\n**🔧 Действие:** Добавить в конец файла:\n\n```ts\nexport class AdminBlogResponse extends createZodDto(AdminBlogResponseSchema) {}\n```\n\n**🔧 Также добавить импорт:** В начало файла добавить:\n\n```ts\nimport { AdminBlogResponseSchema } from ''../schema'';\n```\n\n**💡 Объяснение:** DTO класс для типизации фронтенда и Swagger документации (паттерн AdminGetMeResponse).\n\n---\n\n## **Шаг 3: Создать новый метод в Repository**\n\n**📁 Файл:** `/home/dev-avk/Documents/Dev/nft_collect/app/apps/api/src/modules/blogs/repositories/blog/blog.repository.ts`\n\n**🔧 Действие:** Добавить новый метод в класс `BlogRepository`:\n\n```ts\nasync findByIdForAdmin(id: string, tx?: Prisma.TransactionClient): Promise<BlogEntity | null> {\n  const prismaClient = tx ?? this.prisma;\n  \n  return prismaClient.blog.findUnique({\n    where: { id },\n    include: {\n      tag: { include: { translations: true } },\n      translations: true, // ← ВСЕ переводы без фильтра\n      image: true,\n    },\n  });\n}\n```\n\n**💡 Объяснение:** Метод возвращает блог со всеми переводами (как в `CountyEntity` с `translations: true`).\n\n---\n\n## **Шаг 4: Добавить метод в интерфейс Repository**\n\n**📁 Файл:** `/home/dev-avk/Documents/Dev/nft_collect/app/apps/api/src/modules/blogs/repositories/blog/i-blog.repository.ts`\n\n**🔧 Действие:** Добавить в абстрактный класс `IBlogRepository`:\n\n```ts\nabstract findByIdForAdmin(\n  id: string,\n  tx?: Prisma.TransactionClient,\n): Promise<BlogEntity | null>;\n```\n\n**💡 Объяснение:** Добавляем метод в интерфейс для соблюдения контракта.\n\n---\n\n## **Шаг 5: Создать маппер для админского ответа**\n\n**📁 Файл:** `/home/dev-avk/Documents/Dev/nft_collect/app/apps/api/src/modules/blogs/mappers/blogs.mapper.ts`\n\n**🔧 Действие:** Добавить новую функцию в конец файла:\n\n```ts\nexport const mapBlogToAdminResponse = (\n  blog: Prisma.BlogGetPayload<{\n    include: {\n      translations: true;\n      image: true;\n      tag: { include: { translations: true } };\n    };\n  }>,\n): AdminBlogResponse => {\n  const tag = blog.tag ? mapTagToResponse(blog.tag) : null;\n\n  return {\n    id: blog.id,\n    translations: blog.translations, // ← ВЕСЬ массив переводов\n    tag,\n    createdAt: blog.createdAt,\n    updatedAt: blog.updatedAt,\n    media: blog.image,\n  };\n};\n```\n\n**🔧 Также добавить импорт:** В начало файла:\n\n```ts\nimport { AdminBlogResponse } from ''@repo/contracts'';\n```\n\n**💡 Объяснение:** Маппер возвращает полный массив переводов (паттерн `mapCountryToResponse`).\n\n---\n\n## **Шаг 6: Создать метод в Service**\n\n**📁 Файл:** `/home/dev-avk/Documents/Dev/nft_collect/app/apps/api/src/modules/blogs/services/blog.service.ts`\n\n**🔧 Действие:** Добавить новый метод в класс `BlogService`:\n\n```ts\nasync getOneBlogForAdmin(blogId: string): Promise<AdminBlogResponse> {\n  try {\n    const blog = await this.repo.findByIdForAdmin(blogId);\n    \n    if (!blog) {\n      throw new ApiException({\n        message: ''Blog not found'',\n        code: ApiErrorCode.NotFound,\n        extra: { blogId },\n      });\n    }\n    \n    return mapBlogToAdminResponse(blog);\n  } catch (error) {\n    if (error instanceof Prisma.PrismaClientKnownRequestError) {\n      throw new ApiException(error.code as PrismaErrorCode, error.meta);\n    }\n\n    throw new ApiException({\n      message: ''Failed to get blog for admin'',\n      code: ApiErrorCode.Unknown,\n      extra: {\n        originalError: error instanceof Error ? error.message : String(error),\n      },\n    });\n  }\n}\n```\n\n**🔧 Также добавить импорт:** В начало файла:\n\n```ts\nimport { AdminBlogResponse } from ''@repo/contracts'';\nimport { mapBlogToAdminResponse } from ''../mappers/blogs.mapper'';\n```\n\n**💡 Объяснение:** Service использует новый repository метод и маппер (паттерн `PartnerService.getById`).\n\n---\n\n## **Шаг 7: Создать Swagger декоратор**\n\n**📁 Файл:** `/home/dev-avk/Documents/Dev/nft_collect/app/apps/api/src/modules/blogs/decorator/blogs.decorators.ts`\n\n**🔧 Действие 1:** Добавить в объект `operations` в `config`:\n\n```ts\ngetOneBlogAdmin: {\n  type: ''getOne'',\n  operation: {\n    summary: ''Получить блог со всеми переводами для админки / Get blog with all translations for admin'',\n  },\n  request: {\n    params: [\n      {\n        name: ''blogId'',\n        format: ''uuid'',\n      },\n    ],\n  },\n  response: {\n    type: AdminBlogResponse,\n    description: ''Блог успешно получен со всеми переводами. / Blog retrieved with all translations successfully.'',\n    errorTypes: [[ApiErrorCode.NotFound, ''Blog not found'']],\n  },\n},\n```\n\n**🔧 Действие 2:** Добавить в конец файла экспорт:\n\n```ts\nexport const GetOneBlogAdminOperation = createEndpointDecorator(config, ''getOneBlogAdmin'');\n```\n\n**🔧 Действие 3:** Добавить импорт в начало файла:\n\n```ts\nimport { AdminBlogResponse } from ''@repo/contracts'';\n```\n\n**💡 Объяснение:** Создаем Swagger декоратор для документации API (паттерн `GetOneBlogOperation`).\n\n---\n\n## **Шаг 8: Добавить эндпоинт в Controller**\n\n**📁 Файл:** `/home/dev-avk/Documents/Dev/nft_collect/app/apps/api/src/modules/blogs/controllers/blogs.controller.ts`\n\n**🔧 Действие 1:** Добавить новый метод в класс `BlogsController`:\n\n```ts\n@Get(''admin/:blogId'')\n@GetOneBlogAdminOperation()\nasync getOneBlogForAdmin(\n  @Param(''blogId'', ParseUUIDPipe) blogId: string,\n): Promise<AdminBlogResponse> {\n  return await this.blogService.getOneBlogForAdmin(blogId);\n}\n```\n\n**🔧 Действие 2:** Добавить импорты в начало файла:\n\n```ts\nimport { AdminBlogResponse } from ''@repo/contracts'';\nimport { GetOneBlogAdminOperation } from ''../decorator/blogs.decorators'';\n```\n\n**💡 Объяснение:** Создаем эндпоинт `/api/blogs/admin/:blogId` только для админов (роль уже проверяется в `@ApiController`).\n\n---\n\n## **Шаг 9: Пересобрать contracts пакет**\n\n**📁 Команда:** \n\n```bash\ncd /home/dev-avk/Documents/Dev/nft_collect/app/packages/contracts\nnpm run build\n```\n\n**💡 Объяснение:** Обновляем типы для фронтенда.\n\n---\n\n## **Шаг 10: Обновить фронтенд (будущий этап)**\n\n**📁 Файл:** `/home/dev-avk/Documents/Dev/nft_collect/app/apps/web/src/components/pages/AdminBlogs/index.tsx`\n\n**🔧 Будущее действие:** Заменить запрос `getOneBlog` на `getOneBlogAdmin` при редактировании.\n\n---\n\n## 📊 **Результат реализации:**\n\n**✅ Новый эндпоинт:** `GET /api/blogs/admin/:blogId`\n\n**✅ Ответ содержит:**\n```json\n{\n  "id": "uuid",\n  "translations": [\n    {"language": "en", "title": "English title", "description": "..."},\n    {"language": "ru", "title": "Русский заголовок", "description": "..."},\n    {"language": "ge", "title": "ქართული სათაური", "description": "..."}\n  ],\n  "tag": {...},\n  "media": {...},\n  "createdAt": "2025-01-01T00:00:00Z",\n  "updatedAt": "2025-01-01T00:00:00Z"\n}\n```\n\n**✅ Swagger документация:** Автоматически создается\n\n**✅ Типизация фронтенда:** `AdminBlogResponse` тип\n\n**✅ Безопасность:** Только для админов\n\n**✅ Архитектура:** Следует всем паттернам проекта\n\n## 🚀 **Готово к реализации!**','\n',char(10)),5,'["implementation-plan", " nft_collect", " blog-i18n", " backend-fix", " admin-api", " prisma", " nestjs", " repository-pattern", " mapper-pattern", " zod-schema", " swagger", " solution-design"]',NULL,'2025-09-15 14:06:32');
INSERT INTO curated_memories VALUES('fff47eb3-3075-48d2-ae67-85a78ad65e3d','2025-09-15T19:44:12.759595','2025-09-15T19:44:12.759595',NULL,NULL,'manual',replace('**Финальный отчет о реализации i18n для блога (15.09.2025)**\n\n*   **Задача:** Исправить баг с редактированием многоязычных постов блога в проекте `nft_collect`.\n\n*   **Проблема:** Публичный API (`GET /api/blogs`) возвращал только одну языковую версию поста. Это не позволяло загружать все переводы в новый интерфейс с табами в админ-панели, что приводило к потере данных при редактировании и сохранении.\n\n*   **Коренная причина:** `BlogRepository` (`.../repositories/blog/blog.repository.ts`) некорректно фильтровал переводы на уровне запроса к базе данных, возвращая неполный объект.\n\n*   **Реализация (Бэкенд):**\n    1.  **Contracts (`.../contracts/src`):** В `schema/blog.schema.ts` и `dto/blog.dto.ts` были добавлены `AdminBlogResponseSchema` и `AdminBlogResponse` для описания новой, полной структуры ответа.\n    2.  **Repository (`.../repositories/blog/blog.repository.ts`):** Добавлен метод `findByIdForAdmin`, использующий `include: { translations: true }` для получения всех переводов из БД.\n    3.  **Mapper (`.../mappers/blogs.mapper.ts`):** Создан новый маппер `mapBlogToAdminResponse`, который формирует объект ответа, не урезая массив `translations`.\n    4.  **Service (`.../services/blog.service.ts`):** Добавлен метод `getOneBlogForAdmin`, который связывает новый метод репозитория и новый маппер.\n    5.  **Controller (`.../controllers/blogs.controller.ts`):** Создан новый эндпоинт `GET /api/blogs/admin/:blogId`, который выставляет наружу всю новую логику.\n\n*   **Реализация (Фронтенд):**\n    1.  **API Layer (`.../api/blogs/blogs.query.ts`):** Создан хук `useAdminBlog` для обращения к новому админскому эндпоинту.\n    2.  **UI (`.../Modals/Admin/BlogModal/index.tsx`):** Проведен рефакторинг модального окна. Теперь оно получает `blogId`, самостоятельно вызывает хук `useAdminBlog` для получения полных данных и на их основе корректно заполняет все вкладки с переводами.\n    3.  **Parent Component (`.../pages/AdminBlogs/index.tsx`):** Родительский компонент обновлен и теперь передает в модальное окно только `blogId`.\n\n*   **Статус:** Задача успешно реализована и протестирована. Редактирование постов на нескольких языках работает корректно.','\n',char(10)),5,'["nft_collect", " blog-i18n", " bug-fix", " full-stack", " backend", " frontend", " nestjs", " react", " prisma", " solution-summary", " repository-pattern", " admin-api"]',NULL,'2025-09-15 16:44:12');
INSERT INTO curated_memories VALUES('bda80f64-285f-4c8c-8358-8ed362ccec76','2025-09-15T22:08:42.609234','2025-09-15T22:08:42.609234',NULL,NULL,'manual',replace('**Правило: Создание Zod-схем в проекте `nft_collect`**\n\nПри создании новых схем для сущностей, которые имеют стандартные поля (`id`, `createdAt`, `updated`At), необходимо следовать установленному паттерну для обеспечения консистентности кода.\n\n**Источники паттернов:**\n*   **Общие схемы:** `/home/dev-avk/Documents/Dev/nft_collect/app/packages/contracts/src/schema/common.schema.ts` (определяет `IdSchema`, `UuidSchema`, `DateDBSchema`).\n*   **Пример использования:** `/home/dev-avk/Documents/Dev/nft_collect/app/packages/contracts/src/schema/account.schema.ts` (показывает основной паттерн).\n*   **Текущая реализация:** `/home/dev-avk/Documents/Dev/nft_collect/app/packages/contracts/src/schema/blog.schema.ts` (пример применения).\n\n1.  **Определение Основных Полей:** Все уникальные поля сущности определяются внутри `z.object({...})`.\n\n2.  **Поле `id`:** Поле `id` всегда прописывается **напрямую** внутри `z.object` как `id: UuidSchema`.\n    *(Примечание: Не используется `IdSchema.merge()`, так как это не является основным паттерном в проекте, как показал анализ `account.schema.ts`)*.\n\n3.  **Поля Дат (`createdAt`, `updatedAt`):** Эти поля **не прописываются** вручную в `z.object`.\n\n4.  **Слияние Схем:** Схема с датами (`DateDBSchema`) "подмешивается" в основную схему с помощью метода `.merge()` в конце определения.\n\n#### **Пример Правильной Схемы:**\n```typescript\nexport const YourNewResponseSchema = z.object({\n  id: UuidSchema,          // ID определяется здесь\n  title: z.string(),       // Уникальные поля\n  description: z.string(), // ...\n}).merge(DateDBSchema);      // Даты добавляются здесь\n```','\n',char(10)),5,'["nft_collect", " zod-schema", " best-practice", " code-style", " schema-pattern", " common-schema", " blog-crud", " blog-i18n"]',NULL,'2025-09-15 19:08:42');
INSERT INTO curated_memories VALUES('31f5fb26-289a-4b75-b61c-1257d6ddad27','2025-09-16T15:18:35.812477','2025-09-16T15:18:35.812477',NULL,NULL,'manual',replace('### **Отчет по исследованию проблемы сохранения изображений (Бэкенд)**\n\n**1. Исходная проблема**\n\nЗадача состояла в том, чтобы диагностировать и устранить ошибку, возникающую при загрузке изображений для постов блога.\n\n*   **Симптом:** API возвращал ошибку `400 Bad Request`.\n*   **Данные из логов:** Первопричиной была ошибка от S3-сервиса — `NoSuchBucket` (404). Логи показывали, что приложение пыталось загрузить файл в несуществующий бакет с динамическим UUID-подобным именем (`3218af29-86fae...`).\n*   **Первоначальная гипотеза:** Проблема заключается в коде, который ошибочно использует некий динамический ID в качестве имени бакета вместо статического имени из конфигурации.\n\n**2. Шаг 1: Проверка конфигурации (`.env`)**\n\nПервым делом я проверил файл с переменными окружения `app/apps/api/.env`, чтобы убедиться в корректности статической конфигурации.\n\n*   **Результат:** Проверка подтвердила, что все S3-переменные установлены верно:\n    *   `S3_BUCKET_NAME=764e4fe2-dev` (установлено правильное статическое имя)\n    *   `S3_ENDPOINT=https://s3.timeweb.cloud`\n    *   `S3_REGION=ru-1`\n    *   Ключи доступа также присутствовали.\n*   **Вывод:** Конфигурация была корректной. Это усилило подозрение, что ошибка кроется именно в логике кода.\n\n**3. Шаг 2: Анализ кода и цепочки вызовов**\n\nЯ начал отслеживать путь запроса на загрузку изображения, чтобы найти место, где имя бакета подменяется.\n\n*   **`BlogsController` (`.../blogs/controllers/blogs.controller.ts`):** Я обнаружил, что эндпоинт `POST :blogId/image` не обращается к общему `S3Service` напрямую. Вместо этого он делегирует задачу специализированному сервису — `BlogMediaService`.\n\n*   **`BlogMediaService` (`.../blogs/services/blog-media.service.ts`):** Этот сервис, в свою очередь, также не выполнял загрузку сам. Он выступал в роли координатора, вызывая `mediaService.uploadMedia` для выполнения основной работы.\n\n*   **`MediaService` (`.../media/media.service.ts`):** Этот сервис содержал основную логику: он генерировал уникальный ключ (путь) для файла и вызывал `s3Service.putObject`, передавая ему этот ключ и содержимое файла.\n\n*   **`S3Service` (`.../packages/s3/src/s3.service.ts`):** Финальное звено цепочки. Анализ этого сервиса показал, что он **написан корректно**. Метод `putObject` всегда использует для параметра `Bucket` статическое значение `this.bucketName`, которое он получает из `S3_BUCKET_NAME` при инициализации.\n\n**4. Ключевое противоречие**\n\nНа этом этапе возникло главное противоречие, которое и стало ключом к разгадке:\n*   **С одной стороны,** лог ошибки неопровержимо доказывал, что во время выполнения в S3 передавалось динамическое имя бакета.\n*   **С другой стороны,** анализ всей цепочки вызовов в исходном коде показал, что код написан правильно и **не может** этого делать.\n\nЕдинственное логическое объяснение этого парадокса — **рассинхронизация между исходным кодом и кодом, который фактически выполняется на сервере.**\n\n**5. Финальный вердикт и рекомендации**\n\nПроблема заключается не в ошибке в текущем исходном коде, а в том, что **на сервере запущена устаревшая сборка приложения**, содержащая старую версию кода с багом. Вероятно, ошибка была исправлена в репозитории, но изменения не были применены к запущенному инстансу сервиса.\n\n**Рекомендация:**\nДля решения проблемы необходимо **пересобрать API-сервис и перезапустить его**. Это гарантирует, что будет исполняться последняя, исправленная версия кода.\n\n**Команды (согласно `Makefile`):**\n1.  `make build` — для сборки всех пакетов.\n2.  Остановить и снова запустить API-сервис (например, через `make dev-api`).','\n',char(10)),5,'["blog-crud", "nft_collect", "image", "images", "problem-with-images", "investigation-report", "backend-analysis", "s3", "NoSuchBucket", "deployment-issue", "code-analysis", "\u043e\u0442\u0447\u0435\u0442-\u043e\u0431-\u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0438"]',NULL,'2025-09-16 12:18:35');
INSERT INTO curated_memories VALUES('d661107b-421b-40bd-b0bf-ca25e846a7a9','2025-09-16T16:44:44.894452','2025-09-16T16:44:44.894452',NULL,NULL,'manual',replace('# Проблема фронтенда: Null Reference Error\n\n## 🔴 **Описание ошибки**\n\n**Что произошло:**\n- Пользователь зашел на главную страницу `localhost:3001/en`\n- Страница загрузилась с ошибкой 500 (Server Error)\n- В консоли браузера: `TypeError: Cannot read properties of undefined (reading filePath)`\n\n## 🔍 **Техническая диагностика**\n\n### **Место возникновения:**\n```typescript\n// Файл: collectionTable.tsx, строка 47\n<Avatar\n  size={56}\n  src={collection.avatar.filePath} // ❌ ОШИБКА ЗДЕСЬ\n  radius="sm"\n/>\n```\n\n### **Причина ошибки:**\n```typescript\n// Данные из API:\nconst collection = {\n  id: "123",\n  title: "NFT Collection",\n  avatar: null,        // ← avatar равен null!\n  banner: null,\n  category: { name: "Art" }\n}\n\n// Код пытается обратиться:\ncollection.avatar.filePath\n//            ↑\n//         null.filePath → TypeError!\n```\n\n## 🔄 **Цепочка проблемы**\n\n### **1. База данных:**\n```sql\n-- В таблице collections поле avatar_id может быть NULL\nSELECT avatar_id FROM collections WHERE id = 123;\n-- Результат: NULL\n```\n\n### **2. Бэкенд маппер:**\n```typescript\n// Исходно маппер возвращал:\n{\n  avatar: null,  // Prisma вернула null из БД\n  banner: null\n}\n```\n\n### **3. Фронтенд получает:**\n```json\n{\n  "avatar": null,\n  "banner": null,\n  "title": "Collection Name"\n}\n```\n\n### **4. React компонент:**\n```tsx\n// ❌ Код не проверял на null:\n<Avatar src={collection.avatar.filePath} />\n//                      ↑\n//                   Попытка обращения к null\n```\n\n## ⚡ **Момент возникновения ошибки**\n\n**JavaScript execution:**\n```javascript\n// Шаг 1: collection.avatar → null\n// Шаг 2: null.filePath → TypeError!\n// Шаг 3: React Error Boundary перехватывает\n// Шаг 4: Показывает страницу "500 Server Error"\n```\n\n## 🛠️ **Исправление**\n\n### **Фронтенд (применено):**\n```tsx\n// ❌ БЫЛО:\n<Avatar src={collection.avatar.filePath} />\n\n// ✅ СТАЛО:\n<Avatar src={collection.avatar?.filePath} />\n//                              ↑\n//                    Optional chaining\n```\n\n### **Бэкенд (применено):**\n```typescript\n// Улучшен маппер для явной обработки null\nconst mappedCollection = {\n  ...collection,\n  avatar: collection.avatar ?? null,\n  banner: collection.banner ?? null,\n}\n```\n\n## 📊 **Результат исправления**\n\n### **До:**\n- ❌ Страница крашится с 500 ошибкой\n- ❌ Пользователь видит "Server Error"\n- ❌ Приложение неработоспособно\n\n### **После:**\n- ✅ Страница загружается успешно\n- ✅ Вместо изображения показывается fallback аватар\n- ✅ Приложение работает стабильно\n\n## 🎯 **Урок**\n\n**Проблема:** Отсутствие defensive programming для nullable данных из API.\n\n**Решение:** Всегда использовать optional chaining (`?.`) для потенциально nullable свойств объектов.','\n',char(10)),5,'["frontend-bug", "null-reference-error", "type-error", "optional-chaining", "defensive-programming", "nft_collect", "react", "post-mortem", "bug-report", "\u043e\u0442\u0447\u0435\u0442-\u043e\u0431-\u043e\u0448\u0438\u0431\u043a\u0435"]',NULL,'2025-09-16 13:44:44');
INSERT INTO curated_memories VALUES('5b253ac8-5762-4590-9026-2380ac10029c','2025-09-16T19:16:33.761822','2025-09-16T19:16:33.761822',NULL,NULL,'manual',replace('### **Финальный отчет: Диагностика и решение проблемы множественных запросов при удалении**\n\n**Примечание (16.09.2025):** Данное финальное решение не было реализовано в коде. Отчет сохранен как итог проведенного анализа.\n\n**1. Описание Проблемы**\n\nПри удалении поста в блоге, после успешного `DELETE` запроса, фронтенд инициировал серию нежелательных `GET` запросов. Это приводило к ошибкам 400/404 в консоли и создавало лишнюю нагрузку на сеть и сервер.\n\n**2. Диагностика и Поиск Первопричины**\n\nВ ходе расследования мы прошли несколько этапов и выявили несколько связанных проблем.\n\n**2.1. Неверная структура ключа (Query Key)**\n\n*   **Файл:** `app/apps/web/src/config/queryKeys.ts`\n*   **Проблема:** Функция `queryKeys.blogs.withParams()` без аргументов возвращала "широкий" ключ `["blogs"]`, в отличие от других ключей в проекте.\n\n**2.2. Неправильная инвалидация в мутации**\n\n*   **Файл:** `app/apps/web/src/api/blogs/blogs.mutate.ts`\n*   **Проблема:** `useDeleteBlog` использовал этот "широкий" ключ, вызывая нежелательные эффекты.\n\n**2.3. Ключевое открытие: Несоответствие ключей кэша**\n\n*   **Файл:** `app/apps/web/src/api/blogs/blogs.query.ts`\n*   **Проблема:** Хук `useAdminBlog` использует специальный ключ `...blogId(blogId, "admin")`. Попытки удалить кэш с ключом без `"admin"` были обречены на провал.\n\n**3. Рекомендации и Лучшие Практики**\n\n**3.1. Официальная документация TanStack Query**\nДокументация подтверждает, что для точного управления кэшем рекомендуется использовать максимально специфичные ключи, а `removeQueries` является стандартной практикой для удаленных данных.\n\n**3.2. Паттерны текущего проекта**\n*   **Файл:** `app/apps/web/src/api/collections/collections.mutate.ts`\n*   **Паттерн:** В `useRemoveCollection` используется точная инвалидация для конкретного элемента, что подтверждает правильность предлагаемого подхода.\n\n**4. Предлагаемое финальное решение (не реализовано)**\n\n**Шаг 1: Исправить `queryKeys.ts`**\nПривести структуру `blogs` в соответствие с `collections`.\n\n**Шаг 2: Исправить `blogs.mutate.ts`**\nРеализовать `useDeleteBlog` с `invalidateQueries` для списка и `removeQueries` для конкретного удаленного элемента с правильным ключом (`...blogId(blogId, "admin")`).\n```typescript\nexport const useDeleteBlog = () => {\n  const queryClient = useQueryClient();\n\n  return useMutation({\n    mutationKey: mutateKeys.blogs.remove,\n    mutationFn: async (blogId: string) => {\n      await api.delete<void>(BLOGS_ENDPOINTS.BLOG_ID(blogId));\n      return blogId;\n    },\n    onSuccess: (deletedBlogId) => {\n      queryClient.invalidateQueries({\n        queryKey: queryKeys.blogs.all,\n      });\n      queryClient.removeQueries({\n        queryKey: queryKeys.blogs.blogId(deletedBlogId, "admin"),\n      });\n    },\n    onError: (error: AxiosError<IError>) => {\n      toast.error(error.response?.data.message ?? "Ошибка при удалении блога");\n    },\n  });\n};\n```','\n',char(10)),5,'["multiple-requests-bug", "react-query-debug", "tanstack-query", "cache-invalidation", "query-keys", "removeQueries", "nft_collect", "frontend-analysis", "bug-report", "\u043e\u0442\u0447\u0435\u0442-\u043e\u0431-\u043e\u0448\u0438\u0431\u043a\u0435", "date-2025-09-16", "blog-crud", "delete blog", "\u0443\u0434\u0430\u043b\u0435\u043d\u0438\u0435 \u0431\u043b\u043e\u0433\u0430"]',NULL,'2025-09-16 16:16:33');
INSERT INTO curated_memories VALUES('e901bdb0-3135-4702-9e37-a08061048aa7','2025-09-16T20:13:25.665022','2025-09-16T20:13:25.665022',NULL,NULL,'manual',replace('**Задача:** Ограничить отправку уведомлений в Telegram из GitHub Actions только при пушах в ветку `main` или при пуше новых тегов.\n\n**Анализ:**\n1.  Проблема заключалась в том, что в воркфлоу `build.yml` шаги отправки уведомлений (`notify-*`) не имели условных выражений `if` и срабатывали при любом запуске воркфлоу (например, при пуше в ветку `test`).\n2.  Ключевой нюанс: задача `build` имела зависимость `needs: [notify-start]`. Если бы `notify-start` был пропущен из-за условия, `build` также был бы пропущен.\n\n**Решение:**\n1.  В файле `.github/workflows/build.yml` ко всем задачам `notify-*` было добавлено условие `if: github.event_name == push && github.ref == refs/heads/main`.\n2.  В задаче `build` была удалена зависимость `needs: [notify-start]`, чтобы предотвратить ее пропуск.\n3.  Файл `.github/workflows/deploy-prod.yml` не требовал изменений, так как он уже запускается только по тегам.\n\n**Итог:** Уведомления теперь отправляются строго в соответствии с требуемыми условиями.','\n',char(10)),5,'["github-actions", "ci-cd", "workflow-fix", "conditional-jobs", "telegram-notifications", "nft_collect", "date-2025-09-16"]',NULL,'2025-09-16 17:13:25');
INSERT INTO curated_memories VALUES('a708297e-4e8b-49dc-9cd3-1dac33845c75','2025-09-17T13:22:06.132230','2025-09-17T13:22:06.132230',NULL,NULL,'manual',replace('## 🎯 **Решения для гибкой валидации размеров изображений**\n\n### **📋 Найденные подходы:**\n\n### **1. 🎛️ Min/Max Range валидация**\n```typescript\ninterface ImageValidationRules {\n  minWidth?: number;\n  maxWidth?: number;\n  minHeight?: number;  \n  maxHeight?: number;\n  exactWidth?: number;\n  exactHeight?: number;\n}\n\n// Пример правил:\nconst blogRules = {\n  minWidth: 1200,\n  maxWidth: 3000,\n  minHeight: 300,\n  maxHeight: 600\n};\n```\n\n### **2. 📐 Aspect Ratio валидация** \n```typescript\ninterface AspectRatioRules {\n  aspectRatio?: number;        // Точное соотношение (16/9)\n  minAspectRatio?: number;     // Мин. соотношение\n  maxAspectRatio?: number;     // Макс. соотношение\n  allowedRatios?: number[];    // Список разрешенных [16/9, 4/3, 1/1]\n}\n```\n\n### **3. 📦 Dimension Categories**\n```typescript\ntype DimensionCategory = \n  | ''square''      // 1:1 (аватары)\n  | ''landscape''   // шире чем выше\n  | ''portrait''    // выше чем шире\n  | ''banner''      // очень широкий\n  | ''flexible'';   // любые размеры\n```\n\n### **4. 🔧 Smart Auto-resize + Validation**\n```typescript\ninterface SmartValidationRules {\n  fit: ''cover'' | ''contain'' | ''inside'' | ''outside'';\n  maxLongSide: number;   // макс. размер длинной стороны\n  maxShortSide: number;  // макс. размер короткой стороны\n  quality: number;       // качество сжатия\n}\n```\n\n## 🚀 **Рекомендуемое решение: Гибрид подходов**\n\n### **makeImageValidator с комплексными правилами:**## 🎯 **Итоговое решение: Максимально гибкий подход!**\n\n### **✨ Преимущества предложенного решения:**\n\n**1. 🎛️ Множественные типы валидации:**\n- **Точные размеры**: `2600x440px` (как сейчас)\n- **Диапазоны**: `min: 800px, max: 3000px` \n- **Соотношения сторон**: `16:9`, `4:3`, `1:1`\n- **Категории**: `square`, `landscape`, `banner`, `flexible`\n- **Умная валидация**: по длинной/короткой стороне\n\n**2. 📦 Предустановленные профили:**\n- `avatar` → квадратные 100-1000px, 1:1, 2MB\n- `banner` → широкие 2:1-8:1, до 4000px, 5MB  \n- `blog` → ландшафт 1.5:1-4:1, 600-3000px, 5MB\n- `nft` → гибкие, до 4000px любая сторона, 10MB\n- `faq` → любые, до 2000px, 3MB\n\n**3. 🔧 Полная кастомизация:**\n```typescript\n// Точные размеры (как сейчас):\nmakeImageValidator(''blog'', { \n  dimensions: { exactWidth: 2600, exactHeight: 440 } \n})\n\n// Гибкие размеры:\nmakeImageValidator(''blog'', { \n  dimensions: { \n    minAspectRatio: 2.0, maxAspectRatio: 4.0,\n    minWidth: 1200, maxWidth: 3000 \n  } \n})\n```\n\n### **🚀 Использование в контроллерах:**\n\n```typescript\n// Вместо старого ImageValidation:\n @UploadedFile(makeImageValidator(''blog''))     // Гибкие размеры\n @UploadedFile(makeImageValidator(''avatar''))   // Квадратные  \n @UploadedFile(makeImageValidator(''banner''))   // Широкие\n @UploadedFile(makeImageValidator(''nft''))      // Любые размеры\n\n// Кастомные правила:\n @UploadedFile(makeImageValidator(''blog'', {\n  dimensions: { exactWidth: 2600, exactHeight: 440 }\n})) // Точно как сейчас, но через новую систему\n```\n\n### **📋 Миграционный план:**\n1. **Создать** `imageValidation.factory.ts` \n2. **Заменить** все `ImageValidation` на соответствующие типы\n3. **Оставить** строгие размеры где нужно, сделать гибкими где логично\n\n**Это решение покрывает ВСЕ возможные сценарии использования! 🏆**','\n',char(10)),5,'["file-validation", "nft_collect", "architecture-plan", "image-processing", "nestjs-validation-factory", "solution-design", "best-practice", "upload-errors", "\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0438 \u0444\u0430\u0439\u043b\u043e\u0432"]',NULL,'2025-09-17 10:22:06');
INSERT INTO curated_memories VALUES('9b526701-31ed-4d4f-87b1-eb10dec22456','2025-09-17T14:28:08.228802','2025-09-17T14:28:08.228802',NULL,NULL,'manual',replace('### Анализ валидации файлов (до изменений, 17.09.2025)\n\n## 📋 **Полный анализ бэкенда по задаче валидации файлов**\n\n### **🔍 1. ТЕКУЩЕЕ СОСТОЯНИЕ ВАЛИДАЦИИ**\n\n**ImageValidation Pipe (`imageValidation.pipe.ts`):**\n- ✅ **Установлен**: Sharp 0.34.3 \n- ✅ **Реализован**: Комплексная валидация\n- ✅ **Проверяет**: MIME-тип, размер файла (5MB), размеры изображения (2600x440px)\n- ❌ **Проблема**: Фиксированные размеры применяются ко ВСЕМ типам изображений\n\n**ImageTransformer (`imageTransformer.pipe.ts`):**\n- ✅ **Реализован**: Загрузка в S3 через фабрику `makeImageTransformer`\n- ❌ **НЕ валидирует**: Только загружает файлы без проверок\n\n### **🎯 2. ИСПОЛЬЗОВАНИЕ В КОНТРОЛЛЕРАХ (9 эндпоинтов)**\n\n**ImageValidation используется в 8 местах:**\n```typescript\n// BlogsController \nPOST /blogs/:blogId/image → ImageValidation ❌ (некорректно для блогов)\n\n// UserController\nPOST /users/:userId/avatar → ImageValidation ❌ (аватар как баннер 2600x440)\nPOST /users/:userId/banner → ImageValidation ✅ (корректно)\n\n// PartnerController  \nPOST /partners/:partnerId/avatar → ImageValidation ❌ (аватар как баннер)\nPOST /partners/:partnerId/banner → ImageValidation ✅ (корректно)\n\n// NftController\nPOST /nft/:nftId/image → ImageValidation ❌ (NFT != баннер)\n\n// CollectionMediaController\nPOST /collections/:collectionId/banner → ImageValidation ✅ (корректно) \nPOST /collections/:collectionId/avatar → ImageValidation ❌ (аватар как баннер)\n```\n\n**makeImageTransformer используется в 1 месте:**\n```typescript\n// FaqController\nPOST /faqs/:faqId/image → makeImageTransformer(''faq'') ❌ (без валидации)\n```\n\n### **🚨 3. КРИТИЧЕСКИЕ ПРОБЛЕМЫ**\n\n**Архитектурная проблема:**\n- **8 из 9 эндпоинтов** используют некорректную валидацию\n- **Аватары валидируются как баннеры** (2600x440px вместо квадратных)\n- **NFT изображения** ограничены размерами блогов\n- **FAQ** вообще не валидируется\n\n**Безопасность:**\n- ✅ **MIME-тип проверяется** в ImageValidation\n- ✅ **Sharp валидирует реальное содержимое** файла\n- ✅ **Размер файла ограничен** (5MB)\n- ❌ **FAQ эндпоинт** без валидации = уязвимость\n\n### **📊 4. СТАТИСТИКА ПРОБЛЕМ**\n\n| **Тип изображения** | **Ожидаемые размеры** | **Текущая валидация** | **Статус** |\n|---|---|---|---|\n| **Blog** | 2600x440px | ImageValidation (2600x440) | ✅ **Корректно** |\n| **User Banner** | 2600x440px | ImageValidation (2600x440) | ✅ **Корректно** |  \n| **Partner Banner** | 2600x440px | ImageValidation (2600x440) | ✅ **Корректно** |\n| **Collection Banner** | 2600x440px | ImageValidation (2600x440) | ✅ **Корректно** |\n| **User Avatar** | ~500x500px | ImageValidation (2600x440) | ❌ **Некорректно** |\n| **Partner Avatar** | ~500x500px | ImageValidation (2600x440) | ❌ **Некорректно** |\n| **Collection Avatar** | ~500x500px | ImageValidation (2600x440) | ❌ **Некорректно** |\n| **NFT Image** | Гибкие размеры | ImageValidation (2600x440) | ❌ **Некорректно** |\n| **FAQ Image** | Гибкие размеры | НЕТ валидации | ❌ **Критично** |\n\n### **🎯 5. ИТОГИ АНАЛИЗА**\n\n**Положительные стороны:**\n- ✅ Sharp установлен и работает\n- ✅ Базовая валидация реализована  \n- ✅ Безопасность на хорошем уровне\n- ✅ Архитектура с фабрикой уже существует\n\n**Критические недостатки:**\n- ❌ **67% эндпоинтов** валидируются некорректно\n- ❌ **11% эндпоинтов** вообще не валидируются\n- ❌ Невозможность гибкой настройки размеров\n\n### **🚀 6. НЕОБХОДИМЫЕ ИЗМЕНЕНИЯ**\n\n1. **Заменить** `ImageValidation` на гибкую фабрику `makeImageValidator`\n2. **Создать** типы изображений: `avatar`, `banner`, `blog`, `nft`, `faq`\n3. **Обновить** все 9 эндпоинтов с правильными типами валидации\n4. **Добавить** валидацию в FAQ контроллер\n\n**Задача по проверке валидации файлов (по весу + размеру) полностью подтверждена - система нуждается в кардинальной переработке!**','\n',char(10)),5,'["file-validation-audit", "pre-refactoring-state", "nft_collect", "architecture-analysis", "nestjs-pipes", "upload-errors", "security-audit"]',NULL,'2025-09-17 11:28:08');
INSERT INTO curated_memories VALUES('435562ef-e272-4dd1-996b-cef7d0936fa4','2025-09-17T16:58:51.563223','2025-09-17T16:58:51.563223',NULL,NULL,'manual','Правило архитектуры для проекта nft_collect: Использовать кастомный класс ApiException для всех API-ошибок вместо стандартных исключений NestJS. Это обеспечивает консистентность ответов сервера.',5,'["nft_collect", "architecture-rule", "best-practice", "error-handling", "ApiException"]',NULL,'2025-09-17 13:58:51');
INSERT INTO curated_memories VALUES('b8266e15-65a1-4118-bfc8-27bab6017489','2025-09-17T16:58:51.572683','2025-09-17T16:58:51.572683',NULL,NULL,'manual','Правило архитектуры для проекта nft_collect: Использовать внедряемый LoggerService для всего бэкенд-логирования вместо console.log. Это обеспечивает структурированные и настраиваемые логи.',5,'["nft_collect", "architecture-rule", "best-practice", "logging", "LoggerService"]',NULL,'2025-09-17 13:58:51');
INSERT INTO curated_memories VALUES('e4705f2a-768d-4ea3-8e6c-6deafebe8aef','2025-09-17T17:10:18.288851','2025-09-17T17:10:18.288851',NULL,NULL,'manual',replace('### **Система тегирования для архитектурных правил и паттернов**\n\n---\n\n### **1. Главный тег (обязательный): `project-rule`**\n\nЭтот тег будет у **каждой** записи, которая описывает правило, паттерн или важное архитектурное решение. Это позволит нам одной командой находить все ключевые правила проекта.\n\n---\n\n### **2. Тег категории (выбираем один):**\n\n*   `architecture`: для высокоуровневых решений (например, использование фабрик, репозиториев, CQRS).\n*   `code-style`: для соглашений по написанию кода (именование, структура файлов, как писать схемы Zod).\n*   `best-practice`: для общих рекомендаций и предпочтительных способов решения задач (например, использование `ApiException` вместо `BadRequestException`).\n*   `security`: для всего, что связано с безопасностью.\n\n---\n\n### **3. Теги технологий/тем (добавляем по необходимости):**\n\nЗдесь мы указываем конкретные технологии или темы, к которым относится правило.\n*   **Технологии:** `nestjs`, `react`, `zod`, `prisma`, `sharp`, `github-actions`\n*   **Темы:** `validation`, `logging`, `error-handling`, `auth`, `i18n`, `dto`, `repository-pattern`\n*   **Проект:** и, конечно, всегда добавляем тег проекта — `nft_collect`.\n\n---\n\n### **Пример использования:**\n\n*   **Правило про `ApiException`:**\n    `project-rule, best-practice, error-handling, nestjs, nft_collect`\n\n*   **Правило про создание Zod-схем:**\n    `project-rule, code-style, zod, schema-pattern, nft_collect`\n\n*   **Решение о фабрике валидаторов:**\n    `project-rule, architecture, validation, factory-pattern, nestjs, nft_collect`\n','\n',char(10)),5,'["project-rule", "code-style", "memory", "tagging-standard", "nft_collect", "\u0442\u044d\u0433\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435"]',NULL,'2025-09-17 14:10:18');
INSERT INTO curated_memories VALUES('456211a7-18f3-4d36-bad8-fe7581eac7a6','2025-09-17T19:31:51.996417','2025-09-17T19:31:51.996417',NULL,NULL,'manual',replace('Чтобы локальная система не захламлялась после работы с Docker, вам нужно будет очищать созданные им ресурсы.\n\nКогда вы запускаете `sudo docker compose ... up --build api`, Docker создает:\n1.  **Образы (Images):** Это "шаблоны" ваших приложений.\n2.  **Контейнеры (Containers):** Это запущенные экземпляры образов.\n3.  **Сети (Networks):** Для связи между контейнерами.\n4.  **(Опционально) Тома (Volumes):** Если в `docker-compose.yml` прописаны тома для постоянного хранения данных (например, для баз данных), они тоже создаются.\n\n### **Команды для очистки:**\n\n1.  **Остановить и удалить контейнеры и сети, созданные Docker Compose:**\n    Это основная команда для очистки ресурсов, запущенных через `docker compose`.\n    *   **Выполнять из папки `app/`:**\n        ```bash\n        sudo docker compose -f docker-compose.local.yml -f docker-compose.nft-collect.yml down\n        ```\n    *   **Если вы хотите удалить и тома (данные баз данных), добавьте `--volumes`:**\n        ```bash\n        sudo docker compose -f docker-compose.local.yml -f docker-compose.nft-collect.yml down --volumes\n        ```\n        *Используйте `--volumes` осторожно, если вам нужны данные в базе данных для следующего запуска.*\n\n2.  **Удалить неиспользуемые образы:**\n    После `down` контейнеры удаляются, но образы могут остаться. Эта команда удаляет "висящие" образы (те, которые не используются ни одним контейнером).\n    ```bash\n    sudo docker image prune\n    ```\n    *Вам могут предложить добавить `-a` для удаления всех неиспользуемых образов, а не только "висящих".*\n\n3.  **Полная очистка Docker (агрессивно):**\n    Эта команда удаляет все остановленные контейнеры, все неиспользуемые сети, все "висящие" образы и, опционально, все неиспользуемые тома.\n    ```bash\n    sudo docker system prune\n    ```\n    *Если вы хотите удалить и неиспользуемые тома, добавьте `--volumes` (или `-a` для всех неиспользуемых ресурсов):*\n    ```bash\n    sudo docker system prune --volumes\n    ```\n\n**Рекомендация:**\nПосле того как вы закончили работу с приложением в Docker, сначала выполните `sudo docker compose down`, а затем, время от времени, `sudo docker image prune` или `sudo docker system prune` для поддержания чистоты.','\n',char(10)),5,'["project-rule", "best-practice", "docker", "cleanup", "environment", "nft_collect"]',NULL,'2025-09-17 16:31:51');
INSERT INTO curated_memories VALUES('f7b83228-fb4e-44e2-af8d-8b746484ba04','2025-09-17T22:14:09.518783','2025-09-17T22:14:09.518783',NULL,NULL,'manual',replace('### **Проблема с `.env` при запуске в Docker: `ECONNREFUSED`**\n\n**Симптом:**\nПри запуске бэкенд-приложения (`api`) в Docker-контейнере, оно не может подключиться к базам данных (PostgreSQL и Redis), выдавая ошибку `ECONNREFUSED` (Connection Refused).\n\n**Корень проблемы:**\nВаше приложение `api` внутри своего Docker-контейнера пытается подключиться к базам данных по адресу `127.0.0.1` (или `localhost`).\n\nОднако **внутри Docker Compose сети** `127.0.0.1` указывает на сам контейнер `api`, а не на другие сервисы в сети. Сервисы в Docker Compose общаются друг с другом, используя **имена сервисов** как хосты.\n\n*   Сервис PostgreSQL называется `postgres` (как определено в `docker-compose.local.yml`).\n*   Сервис Redis называется `redis` (как определено в `docker-compose.local.yml`).\n\n**Роль файла `.env`:**\nВаше `api` приложение читает настройки подключения к базам данных из переменных окружения, которые загружаются из файла `app/apps/api/.env`.\n\n**Неправильная конфигурация в `.env`:**\nВ файле `app/apps/api/.env` переменные `DB_HOST` (или часть `DATABASE_URL`) и `REDIS_HOST` были установлены на `localhost` или `127.0.0.1`.\n\n**Решение:**\nНеобходимо изменить эти переменные в файле `app/apps/api/.env`, чтобы они указывали на **имена сервисов** в Docker Compose сети:\n\n*   **Для PostgreSQL:**\n    *   `DATABASE_URL=postgresql://postgres:postgres@postgres:5432/nft_collect_db` (меняем `localhost` на `postgres`)\n*   **Для Redis:**\n    *   `REDIS_HOST=redis` (меняем `localhost` на `redis`)\n\n**Почему это частая проблема:**\nЭто очень распространенная ошибка при переходе от разработки на хост-машине к контейнерам. На хосте `localhost` работает, но внутри изолированной сети Docker контейнеры имеют свои собственные "localhost", и для связи между собой им нужны имена сервисов.\n','\n',char(10)),5,'["project-rule", "devops", "docker", "environment-variables", "networking", "troubleshooting", "ECONNREFUSED", "nft_collect"]',NULL,'2025-09-17 19:14:09');
INSERT INTO curated_memories VALUES('f92e34a2-57f1-4937-af19-90fba2e33f5c','2025-09-18T10:57:37.450906','2025-09-18T10:57:37.450906',NULL,NULL,'manual',replace('**Дата сохранения:** 18.09.2025\n\n# Анализ и план рефакторинга обработки ошибок фронтенда\n\n## 1. Текущая ситуация\n\n- **Глобальный обработчик (Interceptor):** Существует `axios` interceptor в `api/instance.ts`, но он обрабатывает **только** ошибку `401 Unauthorized` для обновления токена. Все остальные ошибки (400, 500 и т.д.) он игнорирует.\n- **Локальная обработка:** Из-за отсутствия глобального обработчика, каждый хук `useMutation` вынужден иметь собственный блок `onError` для отлова и отображения ошибок с помощью `toast.error()`.\n\n## 2. Проблемы\n\n- **Дублирование кода:** Логика `toast.error(error.response?.data.message ?? ...)` разбросана по десяткам файлов.\n- **Риск человеческой ошибки:** Легко забыть добавить `onError` в новый хук, что приведет к "тихим" ошибкам.\n- **Неконсистентность:** Тексты резервных сообщений могут отличаться, нарушая единообразие UX.\n\n## 3. План решения: Централизация\n\n### Шаг 1: Создать центральную функцию-обработчик\n\nСоздать файл `app/apps/web/src/utils/handleApiError.ts` со следующей функцией:\n\n```typescript\nimport { toast } from "react-toastify";\nimport { AxiosError } from "axios";\nimport { IError } from "@/types/error.interface";\n\nexport const handleApiError = (error: AxiosError<IError>) => {\n  const message = error.response?.data?.message || "Что-то пошло не так. Пожалуйста, попробуйте снова.";\n  toast.error(message);\n};\n```\n\n### Шаг 2: Модифицировать Axios Interceptor\n\nОбновить `app/apps/web/src/api/instance.ts`, чтобы он использовал новую функцию.\n\n```typescript\nimport { handleApiError } from "@/utils/handleApiError";\n\napi.interceptors.response.use(\n  (config) => config,\n  async (error) => {\n    const originalRequest = error.config;\n\n    if (error.response?.status === 401 && !originalRequest._isRetry) {\n      // ... существующий код обновления токена\n    }\n\n    if (error.response?.status !== 401) {\n      handleApiError(error);\n    }\n\n    throw error;\n  },\n);\n```\n\n### Шаг 3: Рефакторинг (Рекомендуемый)\n\nПосле внедрения глобального обработчика, можно удалить дублирующиеся `onError` блоки из всех `useMutation` хуков, если они использовались только для вызова `toast.error()`.\n','\n',char(10)),5,'["frontend", " error-handling", " refactoring-plan", " axios-interceptors", " react-toastify", " react-query", " nft_collect", " architecture-analysis", " upload-errors"]',NULL,'2025-09-18 07:57:37');
INSERT INTO curated_memories VALUES('e19aa213-072f-42bd-92d0-5df7bc49f187','2025-09-18T11:19:08.208320','2025-09-18T11:19:08.208320',NULL,NULL,'manual',replace('**Дата сохранения:** 18.09.2025\n\n# Варианты отображения ошибок для клиента\n\n## 1. Всплывающие уведомления (Тосты/Снекбары)\n- **Что это:** Небольшие сообщения в углу экрана, которые исчезают через несколько секунд.\n- **Когда использовать:** Некритичные ошибки (неудачное сохранение, проблемы с сетью), не требующие немедленного действия.\n- **Реализация:** `react-toastify` (уже в проекте).\n\n## 2. Сообщения под полями ввода (Inline-ошибки)\n- **Что это:** Текст ошибки непосредственно под полем формы.\n- **Когда использовать:** Валидация полей в формах (неверный формат, обязательное поле).\n- **Реализация:** Связка `react-hook-form` + компоненты `Mantine` (уже в проекте).\n\n## 3. Глобальный баннер (Alert)\n- **Что это:** Заметный баннер вверху страницы, который висит до закрытия.\n- **Когда использовать:** Важные системные сообщения (сессия истекла, технические работы, нет доступа).\n- **Реализация:** Компонент `Alert` из `Mantine`.\n\n## 4. Модальные окна\n- **Что это:** Окно, блокирующее интерфейс до подтверждения.\n- **Когда использовать:** **Очень редко.** Для критичных, блокирующих работу ошибок (не удалось загрузить основные данные приложения).\n- **Реализация:** Компонент `Modal` из `Mantine`.\n\n## Рекомендуемая стратегия\nДля 95% случаев использовать комбинацию:\n- **Тосты** для ошибок API.\n- **Inline-ошибки** для валидации форм.\n','\n',char(10)),5,'["frontend", " error-handling", " ux-patterns", " ui-design", " mantine", " react-toastify", " nft_collect"]',NULL,'2025-09-18 08:19:08');
INSERT INTO curated_memories VALUES('844b2bae-1a27-40cd-ad3d-847c46e4213c','2025-09-18T16:12:38.190302','2025-09-18T16:12:38.190302',NULL,NULL,'manual',replace('**Дата и время сохранения:** 18.09.2025 17:05\n\n# Анализ реализации Этапа 2 (Централизация обработчика ошибок)\n\n## ✅ **Что было сделано в `instance.ts`:**\n\n1.  **Импорт:**\n    ```typescript\n    import { handleApiError } from "@/utils";\n    ```\n\n2.  **Интеграция в `interceptor`:**\n    ```typescript\n    api.interceptors.response.use(\n      (config) => config,\n      async (error) => {\n        // ... блок обработки 401 (refresh токена)\n        \n        handleApiError(error); // ← ДОБАВЛЕНО\n        \n        throw error;\n      },\n    );\n    ```\n\n## 🎯 **Корректность интеграции:**\n\n- **Позиция:** Правильная. Вызов `handleApiError` стоит после логики обновления токена, но до `throw error`, что позволяет ошибке распространяться дальше к `react-query`.\n- **Логика:**\n    - При **успешном refresh токена (401)**: `handleApiError` НЕ вызывается благодаря `return` внутри блока `try`.\n    - При **неудачном refresh токена (401)**: `handleApiError` вызывается, показывая пользователю ошибку.\n    - Для **всех остальных ошибок** (500, 404, и т.д.): `handleApiError` вызывается, обеспечивая централизованный показ уведомления.\n\n## 🚨 **Важное следствие и мотивация для Этапа 3:**\n\nРеализация Этапа 2 приводит к тому, что **все ошибки API теперь автоматически показывают уведомление** через глобальный `interceptor`.\n\nЭто означает, что существующие `onError` блоки в хуках `useMutation` теперь будут вызывать **ДВОЙНЫЕ УВЕДОМЛЕНИЯ**:\n1.  **Первое (глобальное):** от `interceptor`.\n2.  **Второе (локальное):** от `onError` в конкретной мутации.\n\nЭтот побочный эффект делает **Этап 3 (Рефакторинг)** обязательным для устранения дублирования.\n','\n',char(10)),5,'["error-handling", " axios-interceptors", " react-query", " refactoring-plan", " architecture-analysis", " nft_collect", " double-toast-issue", " upload-errors"]',NULL,'2025-09-18 13:12:38');
INSERT INTO curated_memories VALUES('1d5ccd58-daa5-41d0-8548-9ae4b82d3168','2025-09-18T16:37:53.879150','2025-09-18T16:37:53.879150',NULL,NULL,'manual',replace('**Дата и время сохранения:** 18.09.2025 17:20\n\n# Сравнение схем обработки ошибок (старая vs. новая)\n\n## Старая схема: "Каждый сам за себя"\n\n**Концепция:** Каждый API-запрос (мутация) был сам ответственен за обработку своих ошибок.\n\n**Путь ошибки:**\n1.  **API-вызов:** `app/apps/web/src/api/blogs/blogs.mutate.ts` (внутри хука `useUpdateBlog`).\n2.  **Перехват:** `react-query` ловит ошибку.\n3.  **Обработчик:** Срабатывает локальный `onError` внутри того же хука в `blogs.mutate.ts`.\n4.  **Уведомление:** Локальный `onError` вызывает `toast.error()`.\n\n**Проблемы:**\n- **Дублирование:** Код `onError` повторялся во всех файлах `*.mutate.ts`.\n- **Ненадежность:** Легко было забыть добавить `onError`.\n\n---\n\n## Новая схема: "Единый центр ответственности"\n\n**Концепция:** Глобальный "диспетчер" (перехватчик) ловит все ошибки API в одном месте.\n\n**Путь ошибки:**\n1.  **API-вызов:** `app/apps/web/src/api/blogs/blogs.mutate.ts` (в хуке `useUpdateBlog` блока `onError` больше нет).\n2.  **Глобальный перехват:** Ошибку ловит `axios interceptor` в файле `app/apps/web/src/api/instance.ts`.\n3.  **Вызов функции:** Перехватчик вызывает центральную функцию `handleApiError` из `app/apps/web/src/utils/handleApiError.ts`.\n4.  **Уведомление:** `handleApiError` показывает `toast.error()`.\n5.  **Проброс:** Ошибка пробрасывается дальше, чтобы `react-query` обновил состояние запроса (например, `isLoading`).\n\n**Преимущества:**\n- **Централизация:** Вся логика в `utils/handleApiError.ts`.\n- **Автоматизация:** Работает для всех запросов автоматически.\n- **Надежность:** Невозможно забыть обработать ошибку.\n\n---\n\n## Сравнительная таблица\n\n| Аспект | Старая схема | Новая схема |\n| :--- | :--- | :--- |\n| **Где логика?** | В каждом файле `*.mutate.ts` | В `utils/handleApiError.ts` |\n| **Кто вызывает `toast`?** | Локальный блок `onError` | Глобальный перехватчик в `api/instance.ts` |\n| **Надежность** | Низкая (зависит от разработчика) | Высокая (автоматически для всех) |\n| **Дублирование кода** | Очень высокое | Отсутствует |\n| **Действия для новой мутации**| Нужно было копировать `onError` | Ничего. Просто создать мутацию. |\n','\n',char(10)),5,'["error-handling", " architecture-comparison", " axios-interceptors", " react-query", " refactoring-plan", " nft_collect", " old-vs-new-schema", " architecture", " upload-errors", " \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430 \u043e\u0448\u0438\u0431\u043e\u043a"]',NULL,'2025-09-18 13:37:53');
INSERT INTO curated_memories VALUES('45d7823e-bf22-439c-8412-73f2ffd18de2','2025-09-18T16:55:33.912539','2025-09-18T16:55:33.912539',NULL,NULL,'manual',replace('**Дата и время сохранения:** 18.09.2025 17:40\n\n# Отчет по Этапу 3: Рефакторинг и удаление дублирующего кода\n\n## Цель этапа:\nУстранение избыточных локальных обработчиков ошибок (`onError`) для предотвращения двойных уведомлений и очистки кодовой базы после внедрения глобального обработчика.\n\n## Выполненные действия:\n1.  **Систематическое удаление `onError`:** Последовательно удалены `onError` блоки из всех хуков `useMutation` в `*.mutate.ts` файлах.\n2.  **Очистка импортов:** Вместе с `onError` были удалены неиспользуемые импорты (`toast`, `AxiosError`, `IError`).\n3.  **Рефакторинг Redux Thunks:** Исправлена логика в `adminSlice.ts`, где `rejected`-кейсы `createAsyncThunk` также вызывали дублирующие уведомления.\n4.  **Анализ кастомных уведомлений:** Проверен файл `NFTPage/index.tsx` и подтверждено, что его использование `toast` не связано с ошибками API и не требует изменений.\n\n## Список измененных файлов:\n- `app/apps/web/src/api/blogs/blogs.mutate.ts`\n- `app/apps/web/src/api/admin/admin.mutate.ts`\n- `app/apps/web/src/api/partner/partner.mutate.ts`\n- `app/apps/web/src/api/regions/regions.mutate.ts`\n- `app/apps/web/src/api/faq/faq.mutate.ts`\n- `app/apps/web/src/api/emoji/emoji.mutate.ts`\n- `app/apps/web/src/api/coutries/countries.mutate.ts`\n- `app/apps/web/src/api/collections/collections.mutate.ts`\n- `app/apps/web/src/api/basket/basket.mutate.ts`\n- `app/apps/web/src/api/faq/categories/category.mutate.ts`\n- `app/apps/web/src/api/collections/type/collections.type.mutatents.ts`\n- `app/apps/web/src/api/collections/media/media.mutate.ts`\n- `app/apps/web/src/api/collections/categories/collections.category.mutate.ts`\n- `app/apps/web/src/api/collections/additionalService/service.mutate.ts`\n- `app/apps/web/src/api/blogs/tags/blogs.tags.mutate.ts`\n- `app/apps/web/src/features/admin/adminSlice.ts`\n\n## Итог этапа:\nКодовая база успешно очищена. Обработка ошибок API полностью централизована, что исключает двойные уведомления и упрощает дальнейшую разработку.\n\n## Финальный коммит для этапа:\n`refactor(api): remove redundant error handlers from mutations`\n','\n',char(10)),5,'["refactoring-summary", " error-handling", " code-cleanup", " use-mutation", " redux-thunk", " nft_collect", " stage-3-report", " upload-errors"]',NULL,'2025-09-18 13:55:33');
INSERT INTO curated_memories VALUES('86f04e18-1d4c-4d1e-bb2a-8fbc6742fffa','2025-09-18T17:53:11.814427','2025-09-18T17:53:11.814427',NULL,NULL,'manual',replace('**Дата и время сохранения:** 18.09.2025 18:10\n\n# Централизация обработки ошибок в React Query + Axios приложении\n\n## Исходная проблема\n\n**Дублирование кода обработки ошибок** - в каждой мутации React Query повторялся идентичный блок `onError`, что создавало более 1500 строк дублированного кода, усложняло поддержку и приводило к неконсистентности. Игнорировались сетевые ошибки.\n\n## Решение\n\n### 1. Создание централизованного обработчика\n**Файл:** `/app/apps/web/src/utils/handleApiError.ts`\nСоздана универсальная функция `handleApiError`, которая умеет обрабатывать разные типы ошибок (серверные, сетевые, ошибки конфигурации) и имеет гибкие опции (отключение тостов, кастомные сообщения, исключение статус-кодов).\n\n### 2. Интеграция через Axios Interceptor\n**Файл:** `/app/apps/web/src/api/instance.ts`\n`handleApiError` была интегрирована в глобальный `axios response interceptor`, который теперь перехватывает все ошибки, вызывает обработчик и пробрасывает ошибку дальше для `react-query`.\n\n### 3. Рефакторинг мутаций\nБлоки `onError` были полностью удалены из 15+ файлов с мутациями (например, `/app/apps/web/src/api/blogs/blogs.mutate.ts`), так как обработка стала автоматической.\n\n## Техническая документация\n\n### Обработка типов ошибок Axios\nРешение основано на официальной документации Axios и различает:\n1.  **error.response**: Сервер ответил с ошибкой 4xx/5xx.\n2.  **error.request**: Запрос отправлен, но ответ не получен (сетевая ошибка).\n3.  **else**: Ошибка в конфигурации запроса.\n\n### React Query Offline поведение\nСистема совместима с поведением React Query, который ставит мутации в очередь при оффлайн-режиме и выполняет их при восстановлении соединения.\n\n## Текущий флоу обработки ошибок\n\n1.  **Обычные API ошибки:**\n    `API Request` → `Server Error (4xx/5xx)` → `Axios Interceptor` → `handleApiError()` → `toast.error() + console.error()`\n\n2.  **Сетевые ошибки:**\n    `API Request` → `Network Error` → `Axios Interceptor` → `handleApiError()` → `toast.error("Ошибка сети...") + console.error()`\n\n3.  **Offline → Online сценарий:**\n    При восстановлении сети React Query автоматически повторяет запрос. Если он завершается ошибкой (например, сущность уже удалена), `interceptor` корректно ее ловит и показывает тост.\n\n4.  **Исключения из обработки:**\n    - **422 Validation errors**: Не показывают тосты.\n    - **401 Refresh token**: Только обновление токена без тостов.\n    - **Custom `excludeStatusCodes`**: Возможность гибко отключать обработку для конкретных запросов.\n\n## Результаты\n\n- **Код:** Сокращен на ~1500 строк, дублирование устранено.\n- **Функциональность:** Обрабатываются все типы ошибок, сообщения консистентны, логирование информативно.\n- **Поддержка:** Легкость добавления новых типов ошибок и настройки исключений.\n\nСистема полностью соответствует лучшим практикам и готова к использованию.\n','\n',char(10)),5,'["refactoring-summary", " error-handling", " axios-interceptors", " react-query", " architecture-documentation", " nft_collect", " best-practices", " final-report", " upload-errors", " \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430 \u043e\u0448\u0438\u0431\u043e\u043a"]',NULL,'2025-09-18 14:53:11');
INSERT INTO curated_memories VALUES('fa3b4afc-73dc-4d87-b287-d21e23be943e','2025-09-18T18:23:58.531119','2025-09-18T18:23:58.531119',NULL,NULL,'manual',replace('**Дата и время сохранения:** 18.09.2025 18:30\n\n# Решение проблемы дублирования Toast-уведомлений\n\n## Проблема\nПри использовании глобального `axios interceptor` для показа ошибок, уведомления (`toast`) могут дублироваться. Это происходит по двум причинам:\n1.  **В `development` режиме:** `React.StrictMode` или особенности `react-query` могут вызывать двойное выполнение запросов, что приводит к двум вызовам обработчика ошибок.\n2.  **В `production` режиме:** `react-query` настроен на повторные попытки при сбое (`retry: 3`). Без защиты это привело бы к показу до 4 одинаковых уведомлений подряд при временном сбое сети.\n\n## Решение: Защита от дублирования (Debounce)\n\nРешение заключается в добавлении простого механизма дебаунсинга, который блокирует показ идентичных уведомлений в течение короткого промежутка времени (2 секунды).\n\n**Файл:** `app/apps/web/src/utils/handleApiError.ts`\n\n**Код механизма:**\n```typescript\n// Глобальные переменные для отслеживания последнего уведомления\nlet lastToastMessage = "";\nlet lastToastTime = 0;\nconst TOAST_DEBOUNCE_MS = 2000; // 2 секунды\n\n// Функция-проверка\nconst shouldShowToast = (message: string): boolean => {\n  const now = Date.now();\n  if (message === lastToastMessage && (now - lastToastTime) < TOAST_DEBOUNCE_MS) {\n    return false; // Дубликат, не показываем\n  }\n  lastToastMessage = message;\n  lastToastTime = now;\n  return true;\n};\n```\n\n**Применение внутри `handleApiError`:**\nЛогика показа уведомлений оборачивается в эту проверку.\n```typescript\n// Пример для ошибки сети\nif (showToast && shouldShowToast(message)) {\n  toast.error(message);\n}\n```\n\n## Анализ решения\nЭтот подход является **универсальным** и решает обе проблемы:\n- **Для разработки:** Устраняет раздражающие двойные тосты от `StrictMode`.\n- **Для продакшена:** Что более важно, предотвращает спам уведомлениями при повторных попытках `react-query` выполнить запрос при нестабильной сети.\n\nЭто прагматичное и надежное решение, которое улучшает пользовательский опыт в любом окружении, не требуя изменения общей архитектуры обработчика ошибок.\n','\n',char(10)),5,'["error-handling", " toast-debounce", " react-query-retry", " axios-interceptors", " ux-improvement", " production-bug-prevention", " nft_collect", " upload-errors"]',NULL,'2025-09-18 15:23:58');
INSERT INTO curated_memories VALUES('27ced49f-35bb-4808-a97b-40ad039c6ad6','2025-09-18T18:46:58.432166','2025-09-18T18:46:58.432166',NULL,NULL,'manual',replace('**Дата и время сохранения:** 18.09.2025 19:00\n\n# Финальный отчет по системе обработки ошибок в проекте\n\n## 1. Общая архитектура\n\nВ проекте внедрена комплексная, многоуровневая система обработки ошибок, разделенная по типам операций.\n\n---\n\n## 2. Тип 1: Ошибки действий (Мутации: POST, PATCH, DELETE)\n\n**Задача:** Информировать пользователя о результате действий, меняющих состояние данных.\n\n- **Технологии:** `axios`, `react-query` (`useMutation`), `react-toastify`.\n- **Архитектура:** Централизованная.\n    1.  **`axios Interceptor` (`api/instance.ts`):** Глобально перехватывает все сбойные запросы.\n    2.  **`handleApiError` (`utils/handleApiError.ts`):** Единая функция, вызываемая из `interceptor`.\n        - Различает типы ошибок (сервер, сеть, конфигурация).\n        - Содержит механизм **дебаунсинга** для предотвращения спама уведомлениями.\n        - Показывает пользователю **тост-уведомление**.\n        - Логирует подробную информацию для разработчиков.\n    3.  **Хуки `useMutation`:** Полностью очищены от `onError` логики для показа уведомлений.\n\n- **Пользовательский опыт:** Любое неудачное действие приводит к появлению **одного** стандартизированного тост-уведомления.\n\n---\n\n## 3. Тип 2: Ошибки загрузки данных (Queries: GET)\n\n**Задача:** Сообщить пользователю, что часть интерфейса не смогла загрузить необходимые данные.\n\n- **Технологии:** `react-query` (`useQuery`).\n- **Архитектура:** Локальная, на уровне компонентов.\n    1.  **Хук `useQuery`:** Компонент (напр., `AdminBlogs/index.tsx`) получает флаг `isError` из хука.\n    2.  **Условный рендеринг:** Компонент проверяет `if (isError)` и отрисовывает локальное сообщение об ошибке (напр., "Failed to load blogs") вместо данных.\n\n- **Пользовательский опыт:** Пользователь видит ошибку непосредственно в том блоке, где должны были быть данные.\n- **Предложенное улучшение:** Чтобы избежать двойного информирования (локальное сообщение + глобальный тост), предложено доработать `interceptor`, добавив проверку метода запроса (`if (method !== ''GET'')`), чтобы тосты показывались только для мутаций.\n\n---\n\n## 4. Тип 3: Ошибки валидации форм\n\n**Задача:** Помочь пользователю исправить ошибки ввода в формах.\n\n- **Технологии:** `react-hook-form`, `Mantine UI`.\n- **Архитектура:** Стандартная для `react-hook-form`.\n    - Ошибки (клиентские или с сервера со статусом `422`) обрабатываются и передаются в `error` prop UI-компонентов.\n- **Пользовательский опыт:** Сообщения появляются под конкретным полем ввода.\n- **Исключение:** Глобальный обработчик `handleApiError` **игнорирует** ошибки с кодом `422`.\n\n---\n\n## 5. Особые случаи\n\n- **Ошибка 401 (Unauthorized):** Обрабатывается отдельно в `axios interceptor` для попытки обновления токена доступа.\n','\n',char(10)),5,'["final-report", " architecture-documentation", " error-handling", " axios-interceptors", " react-query", " toast-debounce", " refactoring-summary", " nft_collect", " \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430 \u043e\u0448\u0438\u0431\u043e\u043a", " upload-errors"]',NULL,'2025-09-18 15:46:58');
INSERT INTO curated_memories VALUES('3d5e3535-c086-47e5-8dc8-8f1dff427608','2025-09-18T21:38:41.322666','2025-09-18T21:38:41.322666',NULL,NULL,'manual',replace('**Дата и время сохранения:** 18.09.2025 19:00\n\n# Финальный отчет по системе обработки ошибок в проекте\n\n## 1. Общая архитектура\n\nВ проекте внедрена комплексная, многоуровневая система обработки ошибок, разделенная по типам операций.\n\n---\n\n## 2. Тип 1: Ошибки действий (Мутации: POST, PATCH, DELETE)\n\n**Задача:** Информировать пользователя о результате действий, меняющих состояние данных.\n\n- **Технологии:** `axios`, `react-query` (`useMutation`), `react-toastify`.\n- **Архитектура:** Централизованная.\n    1.  **`axios Interceptor` (`api/instance.ts`):** Глобально перехватывает все сбойные запросы.\n    2.  **`handleApiError` (`utils/handleApiError.ts`):** Единая функция, вызываемая из `interceptor`.\n        - Различает типы ошибок (сервер, сеть, конфигурация).\n        - Содержит механизм **дебаунсинга** для предотвращения спама уведомлениями.\n        - Показывает пользователю **тост-уведомление**.\n        - Логирует подробную информацию для разработчиков.\n    3.  **Хуки `useMutation`:** Полностью очищены от `onError` логики для показа уведомлений.\n\n- **Пользовательский опыт:** Любое неудачное действие приводит к появлению **одного** стандартизированного тост-уведомления.\n\n---\n\n## 3. Тип 2: Ошибки загрузки данных (Queries: GET)\n\n**Задача:** Сообщить пользователю, что часть интерфейса не смогла загрузить необходимые данные.\n\n- **Технологии:** `react-query` (`useQuery`).\n- **Архитектура:** Локальная, на уровне компонентов.\n    1.  **Хук `useQuery`:** Компонент (напр., `AdminBlogs/index.tsx`) получает флаг `isError` из хука.\n    2.  **Условный рендеринг:** Компонент проверяет `if (isError)` и отрисовывает локальное сообщение об ошибке (напр., "Failed to load blogs") вместо данных.\n\n- **Пользовательский опыт:** Пользователь видит ошибку непосредственно в том блоке, где должны были быть данные.\n- **Предложенное улучшение:** Чтобы избежать двойного информирования (локальное сообщение + глобальный тост), предложено доработать `interceptor`, добавив проверку метода запроса (`if (method !== ''GET'')`), чтобы тосты показывались только для мутаций.\n\n---\n\n## 4. Тип 3: Ошибки валидации форм\n\n**Задача:** Помочь пользователю исправить ошибки ввода в формах.\n\n- **Технологии:** `react-hook-form`, `Mantine UI`.\n- **Архитектура:** Стандартная для `react-hook-form`.\n    - Ошибки (клиентские или с сервера со статусом `422`) обрабатываются и передаются в `error` prop UI-компонентов.\n- **Пользовательский опыт:** Сообщения появляются под конкретным полем ввода.\n- **Исключение:** Глобальный обработчик `handleApiError` **игнорирует** ошибки с кодом `422`.\n\n---\n\n## 5. Особые случаи\n\n- **Ошибка 401 (Unauthorized):** Обрабатывается отдельно в `axios interceptor` для попытки обновления токена доступа.\n','\n',char(10)),5,'["final-report", " architecture-documentation", " error-handling", " axios-interceptors", " react-query", " toast-debounce", " refactoring-summary", " nft_collect", " \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430 \u043e\u0448\u0438\u0431\u043e\u043a", " upload-errors"]',NULL,'2025-09-18 18:38:41');
INSERT INTO curated_memories VALUES('f79083c5-3866-4431-a9ac-509eb5d980cd','2025-09-18T21:54:19.834650','2025-09-18T21:54:19.834650',NULL,NULL,'manual',replace('**Дата и время сохранения:** 18.09.2025 19:30\n\n# Архитектурный паттерн: Централизованная обработка ошибок на фронтенде (React Query + Axios)\n\n## Проблема, которую решает паттерн:\n- Дублирование кода обработки ошибок в каждом хуке/запросе.\n- Неконсистентность пользовательских уведомлений об ошибках.\n- Пропуск обработки некоторых типов ошибок (сетевые, не-Axios).\n- Проблема "двойных тостов" в development-режиме и при повторных попытках запросов.\n\n## Описание паттерна:\nДанный паттерн обеспечивает единую, надежную и масштабируемую систему обработки ошибок в React-приложениях, использующих React Query для управления состоянием сервера и Axios для HTTP-запросов.\n\n### Ключевые компоненты и их роли:\n\n1.  **Центральный обработчик ошибок (`handleApiError`)**\n    *   **Файл:** `app/apps/web/src/utils/handleApiError.ts`\n    *   **Роль:** Единая точка для классификации ошибок, логирования и показа уведомлений.\n    *   **Особенности:** Различает ошибки ответа сервера, сетевые ошибки, ошибки конфигурации и не-Axios ошибки. Содержит логику дебаунсинга для предотвращения спама тостами.\n\n2.  **Глобальный обработчик ошибок React Query (`QueryClient.onError`)**\n    *   **Файл:** `app/apps/web/src/config/queryClient.ts`\n    *   **Роль:** Основная точка входа для всех ошибок, которые `React Query` окончательно помечает как проваленные.\n    *   **Особенности:** `handleApiError` назначается в `QueryCache.onError` и `MutationCache.onError`. `React Query` гарантирует, что `handleApiError` будет вызван **только один раз** после всех повторных попыток.\n    *   **Настройки `retry`:** `retry: 0` для мутаций (безопасность), `retry: 1` (или `0`) для запросов в dev-режиме.\n\n3.  **`axios Interceptor`**\n    *   **Файл:** `app/apps/web/src/api/instance.ts`\n    *   **Роль:** Сфокусирован исключительно на технических задачах HTTP-уровня (например, обновление токена при 401).\n    *   **Особенности:** **Не вызывает** `handleApiError` для показа уведомлений.\n\n4.  **Хуки `useMutation`**\n    *   **Файлы:** `*.mutate.ts`\n    *   **Роль:** Только инициируют запросы.\n    *   **Особенности:** **Не содержат** локальных блоков `onError` для показа уведомлений.\n\n5.  **Хуки `useQuery` и компоненты**\n    *   **Файлы:** `*.query.ts` и компоненты, использующие их.\n    *   **Роль:** Локальное отображение ошибок загрузки данных.\n    *   **Особенности:** Используют флаг `isError` для условного рендеринга сообщений об ошибке непосредственно в UI.\n\n## Преимущества паттерна:\n- **Централизация:** Вся логика обработки ошибок в одном месте.\n- **Надежность:** Гарантированная обработка всех типов ошибок.\n- **Консистентность:** Единый пользовательский опыт при ошибках.\n- **Отсутствие дублирования:** Чистый и легко поддерживаемый код.\n- **Эффективность:** Решает проблему "двойных тостов" и спама уведомлениями.\n- **Соответствие Best Practices:** Разделение ответственности между `Axios` и `React Query`.\n\n## Технологии:\n- React Query\n- Axios\n- React Toastify\n\n## Применимость:\n- Фронтенд-приложения на React с использованием React Query и Axios.\n','\n',char(10)),5,'["project-rule", " architecture", " error-handling", " react-query", " axios", " react-toastify", " pattern", " centralization", " nft_collect", " best-practice", " frontend"]',NULL,'2025-09-18 18:54:19');
INSERT INTO curated_memories VALUES('4e36fcd2-0de1-4b2f-948c-a3d26046b7a2','2025-09-19T12:37:22.083248','2025-09-19T12:37:22.083248',NULL,NULL,'manual',replace('**Дата и время сохранения:** 19.09.2025 12:32\n\n# Отчёт: ошибка сохранения в Flameshot\n\n## Симптомы\n\n* Ошибка: `Error trying to save as /home/dev-avk/Desktop/...`\n* Версия: Flameshot v12.1.0 (Ubuntu 24.04, apt).\n\n## Причина\n\n* В конфиге `~/.config/flameshot/flameshot.ini` был путь с кириллицей и пробелами.\n\n## Решение\n\n1. Сброс конфига:\n\n   ```bash\n   mv ~/.config/flameshot/flameshot.ini ~/.config/flameshot/flameshot.ini.bak\n   ```\n2. В настройках выставлен путь: `/home/dev-avk/Desktop`.\n3. Теперь сохранение работает.','\n',char(10)),5,'["flameshot", " ubuntu", " bug", " save error", " config path"]',NULL,'2025-09-19 09:37:22');
INSERT INTO curated_memories VALUES('f2a0f332-4b4e-4db3-9e1b-52b8595ed25b','2025-09-19T18:35:17.168264','2025-09-19T18:35:17.168264',NULL,NULL,'manual','тестовая запись',5,'["\u0442\u0435\u0441\u0442"]',NULL,'2025-09-19 15:35:17');
INSERT INTO curated_memories VALUES('919ec6a9-5493-4a31-a636-a11070ffd8ff','2025-09-19T18:35:28.504582','2025-09-19T18:35:28.504582',NULL,NULL,'manual',replace('**Дата и время сохранения:** 19.09.2025 15:00\n\n**Проблема:** В проекте `nft_collect` инпут поиска в хедере появлялся поверх модальных окон.\n\n**Причина:** У хедера был установлен `z-index: 999`, что выше, чем `z-index` по умолчанию у модальных окон библиотеки Mantine.\n\n**Решение:** В компонент модального окна (`BuyerEditModal`) был добавлен проп `zIndex={1000}`, чтобы его `z-index` был выше, чем у хедера.','\n',char(10)),5,'["z-index", " mantine", " react", " css", " bug-fix", " nft-collect", " header-input-collection-rights"]',NULL,'2025-09-19 15:35:28');
INSERT INTO curated_memories VALUES('4e8d81e3-f841-4fce-9fe6-0a0624bcec71','2025-09-19T20:11:22.888740','2025-09-19T20:11:22.888740',NULL,NULL,'manual',replace('**Дата и время сохранения:** 19.09.2025 20:10\n## 📋 Отчёт: настройка вставки даты через скрипт\n\n### Что сделали\n\n1. Создали скрипт `insert-date.sh` в папке с dotfiles:\n\n   ```\n   ~/dotfiles/scripts/insert-date.sh\n   ```\n\n2. Сделали его исполняемым:\n\n   ```bash\n   chmod +x ~/dotfiles/scripts/insert-date.sh\n   ```\n\n3. Добавили `~/dotfiles/scripts` в `$PATH`, чтобы скрипт можно было вызывать просто как `insert-date.sh`:\n\n   ```bash\n   export PATH=\"$HOME/dotfiles/scripts:$PATH\"\n   ```\n\n   (строка добавлена в `~/.bashrc`).\n\n4. В скрипте прописаны абсолютные пути к бинарям (`/usr/bin/xdotool`, `/bin/date`, `/usr/bin/xclip`) для стабильной работы.\n\n5. В настройках GNOME Custom Shortcuts указан абсолютный путь к скрипту:\n\n   ```\n   /home/dev-avk/dotfiles/scripts/insert-date.sh\n   ```\n\n### Результат\n\n* По хоткею **Ctrl+Shift+D** вставляется строка вида:\n\n  ```\n  2025-09-19.md\n  ```\n* Скрипт работает и в терминале, и в обычных приложениях (автоматически выбирает Ctrl+V или Ctrl+Shift+V).','\n',char(10)),5,'["ubuntu", " gnome", " hotkey", " xdotool", " xclip", " automation", " dotfiles", "sripts", "insert date", " \u0432\u0441\u0442\u0430\u0432\u043a\u0430 \u0434\u0430\u0442\u044b"]',NULL,'2025-09-19 17:11:22');
INSERT INTO curated_memories VALUES('2d4beba3-dcd3-4e72-9202-f410f6927568','2025-09-19T23:18:46.837926','2025-09-19T23:18:46.837926',NULL,NULL,'manual',replace('**Дата и время сохранения:** 19.09.2025 20:25\n### Проблема\n\nВ модальном окне редактирования профиля покупателя (`BuyerEditModal`), расположенном в файле:\n\n*   `/home/dev-avk/Documents/Dev/nft_collect/app/apps/web/src/components/ui/Modals/BuyerEditModal/index.tsx`\n\nпри выборе аватара или баннера, файл немедленно загружался на сервер. Это приводило к двум неудобствам:\n\n1.  **Лишние запросы:** Каждое изменение изображения отправляло запрос на сервер, даже если пользователь еще не был готов сохранить все изменения.\n2.  **Отсутствие отмены:** У пользователя не было возможности отменить выбор изображения до сохранения, кроме как выбрать другое.\n\n### Реализованное решение\n\nЯ полностью переработал логику загрузки изображений в указанном выше файле, чтобы она соответствовала лучшим практикам и была более удобной для пользователя.\n\nВот что было сделано:\n\n1.  **Внедрено локальное состояние (`state`):** Я добавил в компонент состояние `editData`, которое теперь хранит все вносимые изменения (никнейм, выбранный аватар и баннер) до момента нажатия кнопки "Сохранить".\n\n2.  **Реализован предпросмотр:** Теперь при выборе файла он не отправляется на сервер, а для него создается временный локальный URL (`blob`) с помощью `URL.createObjectURL()`. Это позволяет мгновенно отобразить превью выбранного изображения в интерфейсе.\n\n3.  **Добавлены кнопки удаления:** Поверх превью аватара и баннера теперь отображается иконка "крестик". При нажатии на нее выбранное изображение удаляется из локального состояния, а поле загрузки возвращается в исходный вид.\n\n4.  **Обновлена логика сохранения:** Функция `save`, привязанная к кнопке "Сохранить", была модифицирована. Теперь она проверяет, были ли выбраны новые файлы. Если да — она загружает их на сервер вместе с остальными данными профиля за один раз.\n\nВ результате этих изменений процесс редактирования профиля стал более интуитивным, отзывчивым и эффективным, сократив количество запросов к серверу и предоставив пользователю больше контроля.','\n',char(10)),5,'["react", " refactoring", " file-upload", " ux", " BuyerEditModal", " nft_collect", " header-input-collection-rights"]',NULL,'2025-09-19 20:18:46');
INSERT INTO curated_memories VALUES('37f2a1ef-9032-4ba6-a551-f653b6cfe91a','2025-09-20T16:32:08.074616','2025-09-20T16:32:08.074616',NULL,NULL,'manual',replace('**Дата и время сохранения:** 20.09.2025 12:29\n\n### **Итоговый Отчет по Рефакторингу Системы Обработки Ошибок**\n\n#### **1. Исходная Проблема**\n\nОбработка ошибок API на фронтенде в файле `/home/dev-avk/Documents/Dev/nft_collect/app/apps/web/src/utils/handleApiError.ts` реализована через `axios` interceptor. Текущая реализация отображает жестко закодированные сообщения на русском языке, получаемые напрямую из свойства `message` ответа бэкенда. Это делает невозможной интернационализацию (i18n), создает жесткую зависимость от текстов бэкенда и плохо масштабируется.\n\n#### **2. Поставленная Цель**\n\nРеализовать гибкую, надежную и масштабируемую систему обработки ошибок, которая поддерживает интернационализацию. Система должна использовать уникальные коды ошибок (`errorCode`) от бэкенда для поиска переведенных сообщений в файлах локализации фронтенда, обеспечивая профессиональный и локализованный пользовательский опыт.\n\n#### **3. Процесс Анализа и Результаты**\n\n1.  **Анализ фронтенда:** Анализ файла `/home/dev-avk/Documents/Dev/nft_collect/app/apps/web/src/utils/handleApiError.ts` подтвердил использование жестко закодированных сообщений.\n\n2.  **Поиск кода бэкенда:** В директории `/home/dev-avk/Documents/Dev/nft_collect/app/apps/` были обнаружены исходные коды `api` и `partner-api`.\n\n3.  **Поиск источника кодов ошибок:** Поиск по `errorCode` в коде `api` показал, что все типы ошибок импортируются из общего пакета `@repo/contracts`, расположенного в `/home/dev-avk/Documents/Dev/nft_collect/app/packages/contracts/`.\n\n4.  **Ключевая Находка — Определение Кодов Ошибок:** В файле `/home/dev-avk/Documents/Dev/nft_collect/app/packages/contracts/src/exceptions.ts` был найден полный список всех ошибок API. Каждая ошибка определена как класс с уникальным статическим свойством `CODE` (например, `PartnerNotFoundException.CODE = 9`). Это дало нам исчерпывающий источник для всех кодов и их стандартных сообщений.\n\n#### **4. Итоговое Предлагаемое Решение (с учетом улучшений)**\n\nНа основе анализа и ваших рекомендаций предлагается следующий комплексный план.\n\n**Этап 1: Автоматическая Генерация Карты Ошибок**\n\nВместо ручного создания словаря кодов мы автоматизируем этот процесс.\n\n*   **Действие:** Создать служебный скрипт (например, `scripts/generate-error-map.ts`).\n*   **Логика скрипта:**\n    1.  Прочитать содержимое файла `/home/dev-avk/Documents/Dev/nft_collect/app/packages/contracts/src/exceptions.ts`.\n    2.  С помощью регулярных выражений извлечь `static CODE` и имя класса для каждой ошибки.\n    3.  Сгенерировать новый TypeScript-файл `apps/web/src/utils/errorCodeMap.ts`, который будет экспортировать типизированный и неизменяемый объект `ERROR_CODE_MAP`.\n*   **Пример генерируемого файла:**\n    ```typescript\n    export const ERROR_CODE_MAP: Record<number, string> = {\n      9: partnerNotFound,\n      8: emailAlreadyRegistered,\n      // ... все остальные коды\n      -1: unknown\n    } as const;\n    ```\n*   **Преимущество:** Полная автоматизация. При добавлении новых ошибок на бэкенде достаточно будет просто перезапустить скрипт, чтобы обновить карту на фронтенде, что исключает ошибки и ручной труд.\n\n**Этап 2: Расширение Словарей Локализации**\n\nОбновить файлы локализации, добавив ключи для всех типов ошибок.\n\n*   **Файлы для модификации:**\n    *   `/home/dev-avk/Documents/Dev/nft_collect/app/apps/web/messages/en.json`\n    *   `/home/dev-avk/Documents/Dev/nft_collect/app/apps/web/messages/ru.json`\n*   **Структура:** Добавить объект `errors`, который будет содержать ключи для всех специфичных ошибок API (сгенерированных на Этапе 1), а также общие ключи для полного покрытия.\n    ```json\n    "errors": {\n      "unknown": "Неизвестная ошибка",\n      "network": "Ошибка сети. Проверьте ваше подключение.",\n      "server": "Ошибка сервера. Пожалуйста, попробуйте позже.",\n      // --- Ключи, сгенерированные из exceptions.ts ---\n      "partnerNotFound": "Аккаунт партнера не найден",\n      "emailAlreadyRegistered": "Данный email уже зарегистрирован"\n    }\n    ```\n\n**Этап 3: Модернизация Обработчика `handleApiError.ts`**\n\nПереписать обработчик ошибок с применением улучшенной логики.\n\n*   **Файл для модификации:** `/home/dev-avk/Documents/Dev/nft_collect/app/apps/web/src/utils/handleApiError.ts`\n*   **Новая логика:**\n    ```typescript\n    import { ERROR_CODE_MAP } from ./errorCodeMap;\n    // import { t } from i18n-library; // Условный импорт функции перевода\n    \n    export const handleApiError = (error: unknown) => {\n      // Обработка ошибок сети и других не-Axios ошибок\n      if (!axios.isAxiosError(error) || !error.response) {\n        toast.error(t(errors.network));\n        return;\n      }\n\n      const errorCode = error.response.data?.code;\n      const errorKey = ERROR_CODE_MAP[errorCode] || unknown;\n\n      // Логирование неопознанных кодов в режиме разработки\n      if (process.env.NODE_ENV === development && errorKey === unknown && errorCode) {\n        console.warn(`[API Error] Unhandled error code: ${errorCode}. Add it to the map.`);\n      }\n      \n      // Надежное получение сообщения с тройным fallback\n      const message = t(`errors.${errorKey}`, {\n        defaultValue: error.response.data?.message || t(errors.unknown)\n      });\n      \n      toast.error(message);\n    };\n    ```\n\n#### **5. Дополнительная Рекомендация**\n\nВ ходе анализа файла `exceptions.ts` была обнаружена потенциальная проблема: **дублирование кода ошибки `91`** для классов `FaqEmojiReactionNotFoundException` и `FaqAlreadyExistsException`. Рекомендуется сообщить об этом команде бэкенда для исправления, чтобы гарантировать уникальность каждого кода.\n\n#### **6. Заключение**\n\nПредлагаемый усовершенствованный план не только решает исходную задачу по интернационализации, но и выводит систему обработки ошибок на новый уровень. Благодаря автоматической генерации карты ошибок, надежной логике `fallback` и улучшенной структуре, решение становится профессиональным, легко поддерживаемым и устойчивым к будущим изменениям.','\n',char(10)),5,'["\u043e\u0442\u0447\u0435\u0442", "\u0440\u0435\u0444\u0430\u043a\u0442\u043e\u0440\u0438\u043d\u0433", "\u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430-\u043e\u0448\u0438\u0431\u043e\u043a", "i18n", "nft-collect", "\u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430", "\u043f\u043b\u0430\u043d-\u0440\u0430\u0431\u043e\u0442", "header-input-collection-rights", "upload-errors"]',NULL,'2025-09-20 13:32:08');
INSERT INTO curated_memories VALUES('1bdcf733-8332-4b1b-b173-0c4f5af43953','2025-09-20T22:39:34.073726','2025-09-20T22:39:34.073726',NULL,NULL,'manual',replace('**Дата и время сохранения:** 20.09.2025 13:18\n\n# 📋 Отчет: Реализация системы обработки ошибок с интернационализацией\n\n## 🎯 Исходная проблема\n\n### Симптомы\n- Пользователи видели "Unknown error" для ошибок валидации изображений\n- Сообщения об ошибках были жестко закодированы на русском языке\n- Отсутствовала поддержка интернационализации (i18n) для ошибок API\n- Фронтенд полностью зависел от текстов, присылаемых бэкендом\n\n### Техническая причина\nКонфликт форматов кодов ошибок между старым и новым бэкендом:\n- **Старый бэкенд**: числовые коды (`ValidationException.CODE = 1`)\n- **Новый бэкенд**: строковые коды (`ApiErrorCode.Validation = API-9`)\n- **Фронтенд**: поддерживал только числовые коды\n\n## 🏗️ Архитектурное решение\n\n### Принципы\n1. **React Query + i18n интеграция**: QueryClient с динамическими обработчиками ошибок\n2. **Unified error mapping**: Поддержка числовых и строковых кодов в единой карте\n3. **Smart message prioritization**: Комбинированные сообщения для validation ошибок\n4. **Backward compatibility**: Сохранение работы со старым форматом кодов\n\n### Компоненты системы\n- **Error Handler**: Централизованная обработка всех API ошибок\n- **Error Code Map**: Автогенерируемая карта кодов → ключей переводов  \n- **Translation System**: Поддержка множественных языков\n- **Smart Provider**: React Query провайдер с i18n интеграцией\n\n## 📁 Измененные файлы\n\n### 1. `/apps/web/src/providers/tanstackQuery.provider.tsx`\n**Статус**: ✅ Полностью переписан\n\n**Ключевые изменения**:\n```typescript\n// ❌ Было: Пересоздание QueryClient при смене языка\nconst queryClient = useMemo(() => new QueryClient({\n  onError: (error) => handleApiError(error, t)\n}), [t]);\n\n// ✅ Стало: Стабильный QueryClient + динамические обработчики\nconst queryClient = useMemo(() => new QueryClient(), []);\n\nuseEffect(() => {\n  const handleError = (error) => handleApiError(error, t);\n  queryClient.getQueryCache().config.onError = handleError;\n  queryClient.getMutationCache().config.onError = handleError;\n}, [t, queryClient]);\n```\n\n**Результат**: \n- Кеш React Query сохраняется при смене языка\n- Переводы ошибок обновляются динамически\n- Улучшена производительность\n\n### 2. `/apps/web/src/utils/handleApiError.ts`\n**Статус**: ✅ Значительно улучшен\n\n**Ключевые изменения**:\n```typescript\n// Поддержка строковых и числовых кодов\nconst errorKey = (ERROR_CODE_MAP as Record<string | number, string>)[errorCode] || unknown;\n\n// Умная логика для validation ошибок\nconst DETAILED_ERROR_CODES = [validation, badrequest];\n\nif (DETAILED_ERROR_CODES.includes(errorKey) && backendMessage) {\n  const translatedTitle = t(translationKey);\n  if (translatedTitle !== translationKey) {\n    message = `${translatedTitle}: ${backendMessage}`;\n    // "Validation error: Image width must be at least 1200px."\n  }\n}\n```\n\n**Новые возможности**:\n- Обработка строковых кодов ошибок (API-9)\n- Комбинированные сообщения: перевод + детали\n- Debouncing для предотвращения спама\n- Расширенное логирование в dev режиме\n\n### 3. `/scripts/generate-error-map.ts`\n**Статус**: ✅ Полностью переписан\n\n**Добавленный функционал**:\n- Парсинг старых числовых кодов из `exceptions.ts`\n- Парсинг новых строковых кодов из `new_exceptions/enum.ts`\n- Генерация unified карты `Record<string | number, string>`\n- Детектирование дублирующихся кодов\n- Расширенная типизация\n\n**Результат генерации**:\n```typescript\nexport const ERROR_CODE_MAP: Record<string | number, string> = {\n  // Числовые коды (legacy)\n  1: validation,\n  9: partnernotfound,\n  \n  // Строковые коды (modern)\n  API-9: validation,  // ← Решает основную проблему!\n  API-1: unknown,\n};\n```\n\n### 4. `/apps/web/src/utils/errorCodeMap.ts`\n**Статус**: ✅ Автогенерирован\n\n**Содержимое**:\n- 80 числовых кодов (старый бэкенд)\n- 12 строковых кодов (новый бэкенд)\n- 87 уникальных ключей переводов\n- TypeScript типизация для всех кодов\n\n### 5. `/README.md`\n**Статус**: ✅ Обновлен\n\n**Добавлено**:\n- Документация по генератору error map\n- Объяснение поддержки двух форматов кодов\n- Инструкции по обновлению карты\n\n### 6. `/apps/web/messages/en.json` & `/apps/web/messages/ru.json`\n**Статус**: ✅ Уже содержали необходимые переводы\n\n**Существующие переводы**:\n```json\n{\n  "errors": {\n    "validation": "Validation error" / "Ошибка валидации",\n    "unknown": "Unknown error" / "Неизвестная ошибка",\n    "network": "Network Error" / "Ошибка сети"\n  }\n}\n```\n\n### 7. `/config/queryClient.ts`\n**Статус**: ✅ Удален (больше не нужен)\n\n**Причина**: Заменен на создание QueryClient внутри провайдера\n\n## 🎯 Результаты тестирования\n\n### Сценарий 1: Validation ошибка (основная проблема)\n**Запрос**: Загрузка изображения неправильного размера\n\n**Ответ бэкенда**:\n```json\n{\n  "statusCode": 400,\n  "errorCode": "API-9",\n  "message": "Image width must be at least 1200px."\n}\n```\n\n**Результат пользователю**:\n- **Английский**: `"Validation error: Image width must be at least 1200px."`\n- **Русский**: `"Ошибка валидации: Image width must be at least 1200px."`\n\n### Сценарий 2: Обычная ошибка\n**Запрос**: Поиск несуществующего партнера\n\n**Ответ бэкенда**:\n```json\n{\n  "statusCode": 404, \n  "errorCode": 9,\n  "message": "Some backend message"\n}\n```\n\n**Результат пользователю**:\n- **Английский**: `"Partner account not found"`\n- **Русский**: `"Аккаунт партнера не найден"`\n\n## 🚀 Преимущества нового решения\n\n### Технические\n- ✅ **Обратная совместимость**: Работает со старым и новым бэкендом\n- ✅ **Type Safety**: Полная типизация всех кодов ошибок\n- ✅ **Производительность**: QueryClient не пересоздается\n- ✅ **Автоматизация**: Генератор синхронизирует фронтенд/бэкенд\n\n### UX улучшения  \n- ✅ **Детальные сообщения**: Пользователь видит конкретную причину ошибки\n- ✅ **Интернационализация**: Поддержка множественных языков\n- ✅ **Умные сообщения**: Комбинация переводов + технических деталей\n- ✅ **Нет спама**: Debouncing предотвращает дублирующиеся уведомления\n\n### Масштабируемость\n- ✅ **Легкое добавление языков**: Новые .json файлы переводов\n- ✅ **Простое расширение**: Добавление новых кодов через генератор\n- ✅ **Гибкая настройка**: Контроль детализации сообщений по типам ошибок\n\n## 📊 Статистика\n\n- **Файлов изменено**: 6\n- **Файлов удалено**: 1  \n- **Файлов автогенерировано**: 1\n- **Поддерживаемых кодов ошибок**: 93 (80 числовых + 12 строковых + 1 fallback)\n- **Языков поддерживается**: 3 (en, ru, ge)\n- **Обнаруженных дублирований**: 1 (код 91 в старом бэкенде)\n\n## 🔧 Инструкции по сопровождению\n\n### Добавление новой ошибки\n1. **Бэкенд**: Добавить exception в соответствующий файл\n2. **Фронтенд**: Запустить `bun run generate-error-map`\n3. **Переводы**: Добавить ключ в `messages/*.json` при необходимости\n\n### Добавление нового языка\n1. Создать `messages/{locale}.json`\n2. Скопировать структуру из `en.json`\n3. Перевести значения в разделе `errors`\n\n### Настройка детализации ошибок\nОтредактировать `DETAILED_ERROR_CODES` в `handleApiError.ts`:\n```typescript\nconst DETAILED_ERROR_CODES = [\n  validation,     // Показывать детали\n  badrequest,     // Показывать детали  \n  // unauthorized // Только переводы\n];\n```\n\n## ✅ Заключение\n\nРеализована комплексная система обработки ошибок с поддержкой интернационализации, которая:\n- Полностью решила проблему "Unknown error" для validation ошибок\n- Обеспечила унифицированную обработку старого и нового форматов кодов\n- Улучшила UX через детальные, переведенные сообщения об ошибках\n- Создала масштабируемую архитектуру для будущего развития\n\nСистема готова к production использованию и легко расширяется для новых требований.','\n',char(10)),5,'["\u0438\u0442\u043e\u0433\u043e\u0432\u044b\u0439-\u043e\u0442\u0447\u0435\u0442", "\u0440\u0435\u0444\u0430\u043a\u0442\u043e\u0440\u0438\u043d\u0433", "\u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430-\u043e\u0448\u0438\u0431\u043e\u043a", "i18n", "nft-collect", "\u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430", "best-practices", "\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u044f", "header-input-collection-rights", "upload-errors"]',NULL,'2025-09-20 19:39:34');
INSERT INTO curated_memories VALUES('98b7f829-c858-4dc0-9946-7024c64c4f1b','2025-09-21T23:00:12.622388','2025-09-21T23:00:12.622388',NULL,NULL,'manual',replace('**Дата и время сохранения:** 21.09.2025 23:00\n\n# Dev.to MCP Server - Полное рабочее решение\n\n## Архитектура решения\n\n```\nClaude Desktop (stdio) ←→ mcp-proxy ←→ dev-to-mcp HTTP Server ←→ dev.to API\n```\n\n**Компоненты:**\n- **dev-to-mcp HTTP Server** - Сервер на Node.js с Streamable HTTP транспортом\n- **mcp-proxy** - Преобразователь между stdio и HTTP транспортами  \n- **Claude Desktop** - Клиент с поддержкой только stdio\n\n## Установка и настройка\n\n### 1. Предварительные требования\n\n```bash\n# Node.js v22+ (через nvm)\ncurl -o- https://raw.githubusercontent.com/nvm-sh/nvm/v0.39.0/install.sh | bash\nnvm install 22\nnvm use 22\n\n# pipx для Python пакетов\nsudo apt install pipx  # Ubuntu/Debian\n# или\nbrew install pipx      # macOS\n```\n\n### 2. Установка dev-to-mcp сервера\n\n```bash\n# Клонируем репозиторий\ncd ~/projects/dev-tools  # или ваша директория\ngit clone https://github.com/nickytonline/dev-to-mcp.git\ncd dev-to-mcp\n\n# Устанавливаем зависимости\nnpm install\n\n# Собираем проект\nnpm run build\n\n# Проверяем сборку\nls dist/  # должен содержать index.js и другие файлы\n```\n\n### 3. Установка mcp-proxy\n\n```bash\n# Устанавливаем mcp-proxy через pipx\npipx install mcp-proxy\n\n# Проверяем установку\nmcp-proxy --help\n```\n\n### 4. Настройка Claude Desktop\n\nОтредактируйте конфигурационный файл:\n- **Linux:** `~/.config/Claude/claude_desktop_config.json`\n- **macOS:** `~/Library/Application Support/Claude/claude_desktop_config.json`\n- **Windows:** `%APPDATA%\\Claude\\claude_desktop_config.json`\n\n```json\n{\n  "mcpServers": {\n    "devto": {\n      "command": "mcp-proxy",\n      "args": [\n        "--transport", "streamablehttp",\n        "http://localhost:3021/mcp"\n      ]\n    }\n  }\n}\n```\n\n## Запуск системы\n\n### 1. Запуск dev-to-mcp сервера\n\n```bash\n# В первом терминале\ncd ~/projects/dev-tools/dev-to-mcp\nPORT=3021 npm start\n```\n\n**Ожидаемый вывод:**\n```\n[INFO]: Dev.to MCP Server started\n    service: "dev-to-mcp"\n    version: "1.0.0"\n    environment: "development"\n    port: 3021\n```\n\n### 2. Проверка HTTP сервера\n\n```bash\n# Во втором терминале\ncurl http://localhost:3021/mcp\n```\n\n**Ожидаемый ответ:**\n```json\n{\n  "name": "dev-to-mcp",\n  "version": "1.0.0", \n  "description": "MCP server for dev.to public API",\n  "capabilities": ["tools"]\n}\n```\n\n### 3. Перезапуск Claude Desktop\n\n1. Полностью закройте Claude Desktop\n2. Перезапустите приложение\n3. В новом чате проверьте наличие инструментов dev.to\n\n## Доступные инструменты\n\nПосле настройки в Claude Desktop доступны следующие инструменты:\n\n### `devto:get_articles`\nПолучение списка статей с dev.to\n```\nПараметры:\n- per_page: количество статей (по умолчанию 30, макс 1000)\n- page: номер страницы (по умолчанию 1)\n- username: фильтр по автору\n- tag: фильтр по тегу\n- state: состояние статей (fresh, rising, all)\n- top: топ статей за период (1, 7, 30 дней)\n```\n\n### `devto:get_article`\nПолучение конкретной статьи\n```\nПараметры:\n- id: ID статьи\n- path: путь статьи (например, "username/article-slug")\n```\n\n### `devto:get_user`\nПолучение информации о пользователе\n```\nПараметры:\n- id: ID пользователя\n- username: имя пользователя\n```\n\n### `devto:get_tags`\nПолучение популярных тегов\n```\nПараметры:\n- per_page: количество тегов (по умолчанию 10, макс 1000)\n- page: номер страницы (по умолчанию 1)\n```\n\n### `devto:get_comments`\nПолучение комментариев к статье\n```\nПараметры:\n- article_id: ID статьи (обязательно)\n```\n\n### `devto:search_articles`\nПоиск статей (может не работать из-за изменений API)\n```\nПараметры:\n- q: поисковый запрос (обязательно)\n- per_page: количество результатов\n- page: номер страницы\n```\n\n## Примеры использования\n\n### Получение последних статей\n```\nПокажи мне последние 5 статей с dev.to по React\n```\n\n### Поиск статей по тегу\n```\nНайди статьи по тегу "typescript" на dev.to\n```\n\n### Информация о пользователе\n```\nПокажи информацию о пользователе ben на dev.to\n```\n\n### Получение конкретной статьи\n```\nПокажи полную статью с ID 2859253 с dev.to\n```\n\n### Популярные теги\n```\nКакие самые популярные теги на dev.to?\n```\n\n## Автоматизация запуска\n\n### Создание systemd службы (Linux)\n\n```bash\n# Создаем сервисный файл\nsudo nano /etc/systemd/system/devto-mcp.service\n```\n\n```ini\n[Unit]\nDescription=Dev.to MCP Server\nAfter=network.target\n\n[Service]\nType=simple\nUser=your-username\nWorkingDirectory=/home/your-username/projects/dev-tools/dev-to-mcp\nEnvironment=PORT=3021\nEnvironment=NODE_ENV=production\nExecStart=/home/your-username/.nvm/versions/node/v22.18.0/bin/node dist/index.js\nRestart=always\nRestartSec=10\n\n[Install]\nWantedBy=multi-user.target\n```\n\n```bash\n# Активируем службу\nsudo systemctl enable devto-mcp.service\nsudo systemctl start devto-mcp.service\n\n# Проверяем статус\nsudo systemctl status devto-mcp.service\n```\n\n### Скрипт автозапуска (простой вариант)\n\n```bash\n# Создаем скрипт\nnano ~/start-devto-mcp.sh\n```\n\n```bash\n#!/bin/bash\ncd ~/projects/dev-tools/dev-to-mcp\nPORT=3021 nohup npm start > /tmp/devto-mcp.log 2>&1 &\necho "Dev.to MCP Server started on port 3021"\n```\n\n```bash\n# Делаем исполняемым\nchmod +x ~/start-devto-mcp.sh\n\n# Запускаем\n~/start-devto-mcp.sh\n```\n\n## Troubleshooting\n\n### Сервер не запускается\n\n**Проверьте зависимости:**\n```bash\ncd ~/projects/dev-tools/dev-to-mcp\nnpm install\nnpm run build\n```\n\n**Проверьте порт:**\n```bash\nlsof -i :3021\n# Если порт занят, используйте другой\nPORT=3022 npm start\n```\n\n### Claude Desktop не видит инструменты\n\n**Проверьте конфигурацию:**\n```bash\n# Валидация JSON\njq . ~/.config/Claude/claude_desktop_config.json\n```\n\n**Проверьте mcp-proxy:**\n```bash\n# Тест подключения\necho \''{"jsonrpc": "2.0", "method": "initialize", "params": {"protocolVersion": "2024-11-05", "capabilities": {}, "clientInfo": {"name": "test", "version": "1.0.0"}}, "id": 1}\'' | mcp-proxy --transport streamablehttp http://localhost:3021/mcp\n```\n\n**Проверьте логи Claude Desktop:**\n- **Linux:** `~/.config/Claude/logs/`\n- **macOS:** `~/Library/Logs/Claude/`\n- **Windows:** `%APPDATA%\\Claude\\logs\\`\n\n### Ошибки API\n\n**HTTP 404 на поиске:**\n- Функция search_articles может не работать из-за изменений в dev.to API\n- Используйте get_articles с параметром tag для фильтрации\n\n**Тайм-ауты:**\n```bash\n# Увеличьте тайм-аут в mcp-proxy\nmcp-proxy --transport streamablehttp --timeout 30 http://localhost:3021/mcp\n```\n\n## Мониторинг и логи\n\n### Проверка статуса системы\n```bash\n# Статус HTTP сервера\ncurl -s http://localhost:3021/mcp | jq .\n\n# Статус процесса\nps aux | grep "node.*dev-to-mcp"\n\n# Проверка подключения через mcp-proxy\nmcp-proxy --transport streamablehttp http://localhost:3021/mcp < /dev/null\n```\n\n### Логи\n```bash\n# Логи dev-to-mcp сервера\ntail -f /tmp/devto-mcp.log\n\n# Логи Claude Desktop\ntail -f ~/.config/Claude/logs/mcp-server-devto.log\n```\n\n## Обновление\n\n```bash\n# Обновление dev-to-mcp\ncd ~/projects/dev-tools/dev-to-mcp\ngit pull\nnpm install\nnpm run build\n\n# Перезапуск сервера\npkill -f "node.*dev-to-mcp"\nPORT=3021 npm start\n\n# Обновление mcp-proxy\npipx upgrade mcp-proxy\n```\n\n## Безопасность\n\n- Сервер работает только локально (localhost:3021)\n- Не требует API ключей или аутентификации\n- Использует только публичные API dev.to\n- Все данные проходят через локальную систему\n\n## Заключение\n\nЭто решение обеспечивает стабильную интеграцию dev.to API с Claude Desktop через комбинацию:\n- HTTP MCP сервера (dev-to-mcp)\n- Транспорт-прокси (mcp-proxy) \n- Конфигурации Claude Desktop\n\nСистема готова к продуктивному использованию для получения информации с dev.to прямо из Claude Desktop.\n','\n',char(10)),5,'["dev-to", "mcp", "setup", "guide", "mcp-proxy", "claude-desktop", "troubleshooting", "systemd", "automation"]',NULL,'2025-09-21 20:00:12');
INSERT INTO curated_memories VALUES('1959ee96-5abe-47be-bc0a-7bba8274a230','2025-09-22T12:02:25.626803','2025-09-22T12:02:25.626803',NULL,NULL,'manual',replace('**Дата и время сохранения:** 22.09.2025 20:35\n## 🚀 **Dev.to MCP Server - Краткая инструкция**\n\n### **⚡ Быстрый запуск**\n\n**1️⃣ Проверка сервера:**\n```bash\ncurl http://localhost:3021/mcp\n```\n\n**2️⃣ Если не отвечает - запуск:**\n```bash\ncd ~/projects/dev-tools/dev-to-mcp\nPORT=3021 npm start\n```\n\n**3️⃣ Перезапуск Claude Desktop:**\n- Полностью закрыть приложение\n- Запустить заново\n\n---\n\n### **🛠️ Работающие инструменты**\n\n**📰 Получение статей:**\n```\nнайди последние 5 статей по React на dev.to\nпокажи топ статьи за неделю по Python\n```\n\n**👤 Информация о пользователях:**\n```\nпокажи информацию о пользователе ben на dev.to\n```\n\n**🏷️ Популярные теги:**\n```\nкакие самые популярные теги на dev.to?\n```\n\n**📄 Конкретная статья:**\n```\nпокажи статью с ID 2859253 с dev.to\n```\n\n---\n\n### **⚙️ Параметры инструментов**\n\n**`devto:get_articles`**\n- `per_page`: 1-1000 (по умолчанию 30)\n- `tag`: фильтр по тегу ("react", "python")\n- `username`: статьи конкретного автора\n- `top`: топ за период (1, 7, 30 дней)\n\n**`devto:get_user`**\n- `username`: имя пользователя\n- `id`: ID пользователя\n\n**`devto:get_tags`**\n- `per_page`: количество тегов\n\n---\n\n### **❌ НЕ работает**\n\n- `devto:search_articles` - HTTP 404 (изменения в API)\n- Используйте вместо поиска: `get_articles` + `tag`\n\n---\n\n### **🔧 Troubleshooting**\n\n**Проблема:** `Tool not found`\n**Решение:** Перезапустить сервер + Claude Desktop\n\n**Проблема:** `Failed to connect localhost:3021`  \n**Решение:** `cd ~/projects/dev-tools/dev-to-mcp && PORT=3021 npm start`\n\n**Проблема:** HTTP 404 в search\n**Решение:** Использовать `get_articles` с параметром `tag`\n\n---\n\n### **📋 Конфигурация Claude Desktop**\n\n**Файл:** `~/.config/Claude/claude_desktop_config.json`\n```json\n{\n  "mcpServers": {\n    "devto": {\n      "command": "mcp-proxy",\n      "args": [\n        "--transport", "streamablehttp", \n        "http://localhost:3021/mcp"\n      ]\n    }\n  }\n}\n```\n\n---\n\n### **🎯 Примеры запросов**\n\n```\n✅ "найди статьи по TypeScript на dev.to"\n✅ "покажи информацию об авторе ben"  \n✅ "последние статьи по тегу webdev"\n✅ "топ 10 популярных тегов"\n❌ "поищи статьи про API" (используй get_articles + tag)\n```\n\n**💡 Главное:** Держать терминал с сервером открытым!\n','\n',char(10)),5,'["ubuntu", " claude", " desktop-claude", " dev.to", " mcp server", " gemini", " \u043f\u043e\u0438\u0441\u043a \u0441\u0442\u0430\u0442\u0435\u0439 \u043d\u0430 dev.to"]',NULL,'2025-09-22 09:02:25');
INSERT INTO curated_memories VALUES('7c89f778-ddc9-4a57-ae37-3158ea722d60','2025-09-22T16:01:37.117263','2025-09-22T16:01:37.117263',NULL,NULL,'manual',replace('**Дата и время сохранения:** 22.09.2025 14:30\n\n# Отчет по реализации отображения символов валют в NFT Collect\n\n**Дата:** 2025-09-22  \n**Задача:** Отобразить символ рубля (₽) рядом со всеми ценами на фронтенде\n\n## 1. Анализ проблемы\n\n### Исходная ситуация\nПользователи сайта nft-collect.com и разработчики (localhost) не видели символов валют рядом с ценами, в то время как для других доменов (например, blacklex.com) символы отображались корректно.\n\n### Техническая причина\nВ центральном хранилище состояния `useAppStore` переменная `currency` не была установлена для доменов `nft-collect.com` и `localhost`, оставаясь пустой строкой.\n\n## 2. Архитектурный анализ\n\n### Централизованное управление валютами\nПроект использует архитектуру с централизованным управлением валют через Zustand store:\n\n**Файл:** `/apps/web/src/store/app/app.store.ts`\n```typescript\nexport const useAppStore = create<IState & IActions>((set) => ({\n  currency: "",\n  setAppName: () => {\n    const host = location.hostname;\n    switch (host) {\n      case "blacklex.com":\n        set({ appName: AppName.BlackLexCom, currency: "₽" });\n        break;\n      // другие домены...\n    }\n  }\n}));\n```\n\n### Паттерн отображения валют\nВо всех компонентах используется единообразный паттерн:\n```typescript\nconst { currency } = useAppStore();\n// В рендере:\n{formatPrice(price)} {currency}\n```\n\n### Найденные места использования\n- `CollectionTable` (рейтинги коллекций)\n- `Basket` (корзина покупок)  \n- `NFTPage` (страницы NFT)\n- `Rating/Collections` (рейтинги)\n- `HomePage` (главная страница)\n\n## 3. Варианты решения\n\n### ❌ Вариант 1: Ручное добавление символов\n```typescript\n// Плохо - дублирование\n<Text>{formatPrice(price)} ₽</Text>\n```\n**Проблемы:**\n- Нарушение DRY принципа\n- Отсутствие поддержки i18n\n- Сложность изменений (20+ мест)\n- Нет централизованного управления\n\n### ✅ Вариант 2: Централизованное решение\n```typescript\n// Хорошо - через store\n<Text>{formatPrice(price)} {currency}</Text>\n```\n**Преимущества:**\n- Один источник истины\n- Поддержка разных валют для разных доменов\n- Легкость изменений\n- Следование существующей архитектуре\n\n## 4. Реализация\n\n### Этап 1: Выявление проблемы\nДобавлено логирование для диагностики:\n```javascript\nconsole.log("🔍 setAppName called, hostname:", host);\n```\n\n**Найденная проблема:** \n- `location.host` возвращал `"localhost:3001"` с портом\n- `case "localhost"` не срабатывал\n\n### Этап 2: Исправление логики определения домена\n```typescript\n// Было:\nconst host = location.host; // "localhost:3001"\n\n// Стало:\nconst host = location.hostname; // "localhost"\n```\n\n### Этап 3: Добавление поддержки целевых доменов\n```typescript\ncase "nft-collect.com":\n  set({ appName: AppName.NFTCollect, currency: "₽" });\n  break;\ncase "localhost":\n  set({ appName: AppName.NFTCollect, currency: "₽" });\n  break;\n```\n\n## 5. Архитектурные особенности проекта\n\n### Multi-domain архитектура\nПроект поддерживает несколько доменов с разными валютами:\n- `nft-collect.com` → ₽ (рубль)\n- `blacklex.com` → ₽ (рубль)  \n- `blacklex.ge` → ₾ (лари)\n- `localhost` → ₽ (для разработки)\n\n### Инициализация состояния\nИнициализация происходит в `MainLayout`:\n```typescript\nuseEffect(() => {\n  setAppName(); // Устанавливает currency в зависимости от домена\n}, []);\n```\n\n### Типизация\nСтрогая типизация через TypeScript:\n```typescript\ninterface IState {\n  currency: string;\n}\ninterface IActions {\n  setAppName: () => void;\n}\n```\n\n## 6. Результат\n\n### ✅ Достигнутые цели\n- Символ рубля появился во всех местах с ценами\n- Решение работает на localhost и готово для production\n- Сохранена существующая архитектура\n- Поддержка i18n для других доменов\n\n### ✅ Технические характеристики\n- **Количество измененных файлов:** 1 (`app.store.ts`)\n- **Количество строк кода:** 2 (добавлено `currency: "₽"`)\n- **Влияние на компоненты:** автоматическое (20+ компонентов)\n- **Время реализации:** ~15 минут\n\n### ✅ Best Practices соблюдены\n- Централизованное состояние\n- Single Source of Truth\n- DRY принцип\n- Типобезопасность\n- Консистентность с существующей архитектурой\n\n## 7. Рекомендации на будущее\n\n### Улучшение архитектуры\n```typescript\n// Вынести конфигурацию в константы\nconst DOMAIN_CONFIG = {\n  ''nft-collect.com'': { appName: AppName.NFTCollect, currency: ''₽'' },\n  ''blacklex.ge'': { appName: AppName.BlackLex, currency: ''₾'' },\n  ''localhost'': { appName: AppName.NFTCollect, currency: ''₽'' }\n} as const;\n```\n\n### Env переменные\n```typescript\nconst defaultCurrency = process.env.NEXT_PUBLIC_DEFAULT_CURRENCY || ''₽'';\n```\n\n## 8. Вывод\n\n**Задача решена оптимальным способом:** одно централизованное изменение привело к отображению символов валют во всех компонентах проекта. Решение:\n- Следует архитектурным принципам проекта\n- Масштабируемо и поддерживаемо\n- Готово для production без дополнительных изменений\n\n**Ключевой успех:** правильный выбор централизованного подхода вместо множественных точечных изменений.\n\n\n## ✅ Отлично! Решение улучшено\n\n**Анализ финального кода:**\n\n### 🎯 **Архитектурные улучшения**\n```typescript\n// ✅ Заменен switch на объект конфигурации  \nconst config = {\n  "nft-collect.com": { appName: AppName.NFTCollect, currency: "₽" },\n  "blacklex.ge": { appName: AppName.BlackLex, currency: "₾" },\n  "blacklex.com": { appName: AppName.BlackLexCom, currency: "₽" },\n  localhost: { appName: AppName.NFTCollect, currency: "₽" },\n};\n```\n\n### 🔧 **Технические преимущества**\n\n1. **Читаемость**: Конфигурация в одном месте\n2. **Типобезопасность**: `keyof typeof config`\n3. **Безопасность**: `if (data) set(data)` для неизвестных доменов\n4. **Расширяемость**: Легко добавить новые домены\n\n### ✅ **Корректность решения**\n\n- **localhost**: `currency: "₽"` ✅\n- **nft-collect.com**: `currency: "₽"` ✅  \n- **location.hostname**: Без порта ✅\n- **Fallback**: Есть проверка `if (data)` ✅\n\n### 📊 **Оценка**\n\n**Решение идеальное** - это именно то улучшение, которое я предлагал в рекомендациях отчета:\n\n> ```typescript\n> const DOMAIN_CONFIG = {\n>   ''nft-collect.com'': { appName: AppName.NFTCollect, currency: ''₽'' }\n> } as const;\n> ```\n\n**Готово к production!** 🚀','\n',char(10)),5,'["nft-collect", " frontend", " fix", " refactor", " zustand", " currency-display", " architecture-decision", " best-practices", " technical-report", " i18n", " 494-add-ruble-symbols"]',NULL,'2025-09-22 13:01:37');
INSERT INTO curated_memories VALUES('7e79ae53-1653-44f3-8b48-161bb6b92ed9','2025-09-22T17:54:56.874706','2025-09-22T17:54:56.874706',NULL,NULL,'manual',replace('**Дата и время сохранения:** 22.09.2025 16:05\n\n### **Финальный план: Доработка и рефакторинг UI управления коллекциями**\n\n**Цель:** Завершить реализацию UI для **Категорий**, **Типов** и **Коллекций**, подключив существующую логику и улучшив формы с помощью `React Hook Form + Zod`.\n\n---\n\n### **Эпик 1: Установка зависимостей**\n\n*   **Задача:** Добавить недостающие зависимости для валидации форм.\n*   **Действие:** Выполнить команду `npm install zod @hookform/resolvers` в директории `app/apps/web`.\n*   **Коммит:** `chore(deps): add zod and @hookform/resolvers`\n\n---\n\n### **Эпик 2: Доработка и рефакторинг UI Категорий**\n\n*   **Задача 2.1: Рефакторинг формы**\n    *   **Действие:** В существующем `CollectionCategoryModal` заменить ручное управление формой (`useState`) на `React Hook Form` с валидацией через `Zod`. **Добавить поля для всех переводов** (`ru`, `en`, `ge`), как того требует DTO.\n    *   **Файл:** Изменить: `app/apps/web/src/components/ui/Modals/Admin/CollectionCategoryModal/index.tsx`\n    *   **Коммит:** `refactor(categories): upgrade CategoryModal form to RHF and add translation fields`\n\n*   **Задача 2.2: Подключение логики на странице**\n    *   **Действие:** В `AdminCollectionCategoriesPageComponent` раскомментировать и подключить обработчики `onAdd`, `onEdit`, `onDelete`, чтобы они вызывали соответствующие mutation-хуки.\n    *   **Файл:** Изменить: `app/apps/web/src/components/pages/AdminCollectionCategories/index.tsx`\n    *   **Коммит:** `feat(categories): connect UI actions to mutation hooks`\n\n---\n\n### **Эпик 3: Доработка и рефакторинг UI Типов**\n\n*   **Действие:** Полностью повторить все шаги из **Эпика 2**, но для сущности "Типы" (рефакторинг `CollectionTypeModal` и доработка `AdminCollectionTypesPageComponent`).\n*   **Коммит:** `feat(types): complete and refactor UI for collection types CRUD`\n\n---\n\n### **Эпик 4: Доработка UI Коллекций**\n\n*   **Действие:** Аналогично предыдущим эпикам — раскомментировать код на странице `.../admin/collections/page.tsx`, провести рефакторинг `CollectionModal` на `RHF + Zod` и подключить всю необходимую логику.\n*   **Коммит:** `feat(collections): complete and refactor UI for collection management`\n','\n',char(10)),5,'["nft-collect", " implementation-plan", " admin-panel", " crud", " collections", " categories", " types", " frontend", " ui-task", " refactoring", " react-hook-form", " zod", " 477-collections"]',NULL,'2025-09-22 14:54:56');
INSERT INTO curated_memories VALUES('f2513bd6-e4b4-4fda-9200-dde365fe43f3','2025-09-23T14:37:42.338085','2025-09-23T14:37:42.338085',NULL,NULL,'manual',replace('**Дата и время сохранения:** 23.09.2025 15:10\n**Заголовок:** Правила сборки в monorepo-проекте nft_collect\n\n**Основной принцип:** Изменения в пакетах (`packages/*`, например `@repo/contracts`) не будут видны в приложениях (`apps/*`, например `api`), пока проект не будет пересобран. Это стандартное поведение для monorepo с `turbo`.\n\n**Команды для пересборки:**\n\n1.  **Полная сборка проекта (из `app/README.md`):**\n    *   **Команда:** `bun run build`\n    *   **Директория:** `/home/dev-avk/Documents/Dev/nft_collect/app`\n\n2.  **Сборка через Makefile:**\n    *   **Команда:** `make build`\n    *   **Директория:** `/home/dev-avk/Documents/Dev/nft_collect` (корень проекта)\n\n3.  **Оптимизированная сборка (предложенная вами):**\n    *   **Команда:** `bunx turbo run build --filter=@repo/contracts...`\n    *   **Директория:** `/home/dev-avk/Documents/Dev/nft_collect/app`\n','\n',char(10)),5,'["nft_collect", " monorepo", " build", " turbo", " bun", " makefile", " \u043f\u0440\u043e\u0435\u043a\u0442\u043d\u0430\u044f-\u043f\u0430\u043c\u044f\u0442\u043a\u0430"]',NULL,'2025-09-23 11:37:42');
INSERT INTO curated_memories VALUES('203415dd-0a04-40ad-b002-827881b64ef4','2025-09-23T15:40:20.207204','2025-09-23T15:40:20.207204',NULL,NULL,'manual',replace('**Дата и время сохранения:** 23.09.2025 15:45\n**Заголовок:** Архитектурное правило: Паттерн получения данных в `apps/web` (React Query)\n\n**Суть правила:** Любая новая логика для получения серверных данных в `apps/web` **обязана** следовать паттерну "Фасад над асинхронным слоем данных".\n\n**Компоненты паттерна:**\n1.  **Ядро:** `@tanstack/react-query` (`useQuery`, `useMutation`).\n2.  **Фасад:** Кастомный хук (например, `useCollectionCategories`), который инкапсулирует всю логику запроса.\n3.  **Единый источник правды (SSoT) для URL:** Файл с константами эндпоинтов (например, `.../endpoints/collections.endpoint.ts`).\n4.  **Единый источник правды (SSoT) для ключей кэша:** Фабрика ключей в `.../config/queryKeys.ts`.\n\n**Порядок реализации нового запроса (query):**\n1.  **Endpoint:** Добавить URL нового эндпоинта в соответствующий класс в `constants/endpoints/`.\n2.  **Query Key:** Добавить функцию-фабрику для нового ключа в `config/queryKeys.ts`.\n3.  **Хук-фасад:** Создать новый хук (например, `useMyNewData`), который использует `useQuery`, а также константу эндпоинта и фабрику ключей из предыдущих шагов.\n4.  **UI Компонент:** Компонент должен вызывать только хук-фасад (`useMyNewData()`) и не должен содержать в себе URL, ключи или логику `fetch`.\n','\n',char(10)),5,'["project-rule", " architecture", " react", " react-query", " data-fetching", " facade-pattern", " sso-pattern", " nft_collect"]',NULL,'2025-09-23 12:40:20');
INSERT INTO curated_memories VALUES('f3719135-9f75-4e89-956d-53b6bd6d1bed','2025-09-23T16:58:36.119638','2025-09-23T16:58:36.119638',NULL,NULL,'manual',replace('**Дата и время сохранения:** 23.09.2025 17:10\n**Заголовок:** Архитектурное правило: Инвалидация кэша в React Query\n\n**Проблема:** После выполнения мутации (создание, обновление, удаление) данные в таблице (списке) не обновляются автоматически.\n\n**Причина:** Инвалидация кэша по специфичному ключу (например, с параметрами `.withParams()`) может не затронуть активный запрос списка из-за тонкостей в параметрах (например, `locale`).\n\n**Правило (Best Practice):**\nДля надежного обновления списка ресурсов после мутации, в `onSuccess` колбэке следует инвалидировать **корневой (root) ключ** этого ресурса, который обычно хранится в свойстве `.all`.\n\n**Пример:**\nЧтобы обновить список категорий, который запрашивается с ключом `queryKeys.collectionCategories.withParams(params, locale)`, нужно инвалидировать `queryKeys.collectionCategories.all`.\n\n**Правильная реализация:**\n```typescript\n// в useUpdateCollectionCategory\nonSuccess: (data) => {\n  // Можно инвалидировать и ключ конкретной сущности, если нужно\n  queryClient.invalidateQueries({\n    queryKey: queryKeys.collectionCategories.categoryId(data.id), \n  });\n\n  // ОБЯЗАТЕЛЬНО инвалидировать корневой ключ для обновления всех списков\n  queryClient.invalidateQueries({\n    queryKey: queryKeys.collectionCategories.all,\n  });\n}\n```\nЭто гарантирует, что все запросы, начинающиеся с `[''collection-categories'']`, будут помечены как устаревшие и автоматически обновлены.\n','\n',char(10)),5,'["project-rule", " best-practice", " react-query", " caching", " cache-invalidation", " mutation", " nft_collect"]',NULL,'2025-09-23 13:58:36');
INSERT INTO curated_memories VALUES('334255e7-fa6c-4709-99d3-e7ff9b8c8dbd','2025-09-24T16:24:04.677683','2025-09-24T16:24:04.677683',NULL,NULL,'manual',replace('**Дата и время сохранения:** 24.09.2025 15:00\n\n### Отчет: Логика работы модального окна `CollectionModal`\n\n#### 1. Общая цель\nМодальное окно `CollectionModal` предназначено для создания, редактирования и управления жизненным циклом (workflow) NFT-коллекций в админ-панели.\n\n#### 2. Управление данными\n*   **Получение данных:** Окно получает данные о текущей коллекции через пропс `data`. Если `data` равно `null`, окно работает в режиме создания новой коллекции.\n*   **Внутреннее состояние:** Внутри компонента используется состояние `editData`, которое хранит все редактируемые поля коллекции, включая ее текущий статус (`status`).\n*   **Инициализация:** При открытии окна (или при изменении входных данных) хук `useEffect` инициализирует внутреннее состояние `editData` данными из пропса `data`. Если данных нет, устанавливаются значения по умолчанию, включая статус `draft`.\n\n#### 3. Логика "Только для чтения" (Read-Only)\n*   В коде определена переменная `isReadOnly`. Она становится `true`, если статус коллекции — `pending` (на рассмотрении), `verified` (подтверждена) или `declined` (отклонена).\n*   Эта переменная используется для блокировки всех полей формы (текстовые поля, селекторы, загрузка изображений, добавление ссылок и т.д.), предотвращая любые изменения в коллекциях, которые не находятся в статусе `draft`.\n\n#### 4. Логика кнопок и жизненного цикла (Workflow)\nОтображение кнопок действий полностью зависит от статуса коллекции (`editData.status`), который хранится в состоянии окна.\n\n*   **Если статус `draft` (Черновик):**\n    *   Отображаются две кнопки:\n        1.  **"Save" / "Add"**: Сохраняет текущие изменения (для существующего черновика) или создает новую коллекцию.\n        2.  **"Submit for Review"**: Отправляет коллекцию на модерацию, меняя ее статус.\n\n*   **Если статус `pending` (На рассмотрении):**\n    *   Отображаются две кнопки для модератора:\n        1.  **"Approve"**: Утверждает коллекцию.\n        2.  **"Decline"**: Отклоняет коллекцию.\n    *   Все поля формы в этом режиме заблокированы (`isReadOnly = true`).\n\n*   **Если статус `verified` или `declined` (Подтверждена или Отклонена):**\n    *   Кнопки действий **не отображаются**, так как жизненный цикл коллекции на этом этапе завершен или приостановлен. Редактирование невозможно.\n\n*   **Если тип модального окна `delete`:**\n    *   Отображается только одна кнопка — **"Delete"**.\n\n#### 5. Обратные вызовы (Callbacks)\nМодальное окно является «глупым» компонентом. Оно не выполняет API-запросы напрямую. Каждое действие (сохранение, отправка на ревью, утверждение и т.д.) выполняется через функции-колбэки (`onAdd`, `onEdit`, `onSubmitForReview`, `onApprove`, `onDecline`), которые передаются в компонент из родительской страницы. Это обеспечивает чистоту архитектуры и разделение ответственности.','\n',char(10)),5,'["477-collections", "react", "modal-logic", "workflow", "nft-collections", "dumb-component", "frontend-architecture"]',NULL,'2025-09-24 13:24:04');
